    "",
    "Sch gio khoa *Vt l 10* khng phi l cun sch trnh by sn cc ni dung kin thc cn hc m l cun sch hng dn hc sinh hot ng  tm ti, khm ph ra kin thc mi, vn dng chng vo vic gii quyt cc vn  trong hc tp v cuc sng. Thng qua cc hot ng hc tp ny, cc em khng nhng hnh thnh v pht trin cc nng lc khoa hc ni chung v vt l ni ring m cn ng thi hnh thnh v pht trin c cc nng lc chung nh nng lc t ch v t hc, giao tip v hp tc, gii quyt vn  v sng to,...",
