INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B1', 'Bài 1. Làm quen với vật lí', 7, 2, $JSON$
{
  "content": [
    "# Bi 1 LM QUEN VI VT L",
    "",
    "**Khi ng:** Hnh bn l cc nh vt l tiu biu cho mi giai on pht trin khoa hc v cng ngh ca nhn loi. Em  bit g v cc nh khoa hc ny?",
    "[Hnh nh 3 nh khoa hc: Galilei, Newton, Einstein]",
    "Galilei (Ga-li-l) (1564  1642): Cha  ca phng php thc nghim.",
    "Newton (Niu-tn) (1642  1727): Ngi tm ra nh lut vn vt hp dn.",
    "Einstein (Anh-xtanh) (1879  1955): Ngi tm ra thuyt tng i v cng thc: E = mc$^2$.",
    "",
    "## I. I TNG NGHIN CU CA VT L V MC TIU CA MN VT L",
    "",
    "Thut ng vt l c ngun gc t ting Hy Lp physiko c ngha l kin thc v t nhin. Vt l l mn \"khoa hc t nhin\" c i tng nghin cu tp trung vo cc dng vn ng ca vt cht (cht, trng), nng lng.",
    "Cc lnh vc nghin cu ca Vt l rt a dng, t C hc, in hc, in t hc, Quang hc, m hc, Nhit hc, Nhit ng lc hc n Vt l nguyn t v ht nhn, Vt l lng t, Thuyt tng i.",
    "Vic hc tp mn Vt l gip cc em hnh thnh, pht trin nng lc vt l vi cc biu hin chnh sau y:",
    " C c nhng kin thc, k nng c bn v vt l.",
    " Vn dng c kin thc, k nng  hc  khm ph, gii quyt cc vn  c lin quan trong hc tp cng nh trong i sng.",
    " Nhn bit c nng lc, s trng ca bn thn, nh hng ngh nghip $^{(1)}$.",
    "",
    "**? Cu hi:**",
    "1. Hy k tn cc lnh vc vt l m em  c hc  cp Trung hc c s.",
    "2. Em thch nht lnh vc no ca Vt l? Ti sao?",
    "",
    "## II. QU TRNH PHT TRIN CA VT L",
    "",
    "Di y l s  trnh by cc giai on chnh trong qu trnh pht trin ca Vt l. Mi giai on c mt tnh cht, c im ring.",
    "",
    "Cc nh trit hc tm hiu th gii t nhin da trn quan st v suy lun ch quan.",
    "*T nm 350 trc Cng nguyn n th k XVI (tin Vt l)*",
    "| 350 TCN: Aristotle (A-ri-xtt) da vo quan st cho rng vt nng ri nhanh hn vt nh.",
    "",
    "Cc nh vt l dng phng php thc nghim  tm hiu th gii t nhin.",
    "*T th k XVII n cui th k XIX (Vt l c in)*",
    "| 1600: Galilei lm th nghim ti thp nghing Pisa.",
    "| 1687: Newton cng b cc nguyn l Ton hc ca Trit hc t nhin.",
    "| 1785: Joule (Jun) tm ra cc nh lut nhit ng lc hc.",
    "| 1831: Faraday (Pha-ra-y) tm ra hin tng cm ng in t.",
    "",
    "Cc nh vt l tp trung vo cc m hnh l thuyt tm hiu th gii vi m v s dng th nghim  kim chng.",
    "*T cui th k XIX n nay (Vt l hin i)*",
    "| 1900: Planck (Plng) xy dng thuyt lng t.",
    "| 1905: Einstein xy dng thuyt tng i.",
    "| 1958: Ra i l thuyt v thc hnh mch IC.",
    "",
    "$^{(1)}$ *Theo Chng trnh GDPT mn Vt l  B GD v T (2018)*",
    "",
    "7",
    "CHNG I  M U",
    "",
    "## III. VAI TR CA VT L I VI KHOA HC, K THUT V CNG NGH",
    "",
    "a) Vt l c quan h vi mi ngnh khoa hc v thng c coi l c s ca khoa hc t nhin (KHTN). Cc khi nim, nh lut, nguyn l ca Vt l c s dng rng ri trong mi lnh vc ca KHTN, c bit l trong vic gii thch c ch ca cc hin tng t nhin, t cc hin tng xy ra trong th gii sinh hc, cc phn ng ho hc n cc hin tng xy ra trong v tr,...",
    "Khng phi ngu nhin m cng ngy cng xut hin nhiu lnh vc lin mn nh Vt l sinh hc, Vt l a l, Vt l thin vn, Ho l, Sinh hc lng t, Ho hc lng t,...",
    "",
    "b) Vt l l c s ca cng ngh. C th khng nh l khng c cc thnh tu nghin cu ca Vt l th khng c cng ngh.",
    "My hi nc do James Watt (Gim Ot) sng ch nm 1765 da trn nhng kt qu nghin cu v Nhit ca Vt l  to nn bc khi u cho cuc cch mng cng nghip ln th nht vi c trng c bn l thay th sc lc c bp bng sc lc my mc (Hnh 1.1).",
    "",
    "[Hnh 1.1. My hi nc ca James Watt]",
    "",
    "**? Cu hi:**",
    "1. Hy nu tn mt s thit b c ng dng cc kin thc v nhit.",
    "2. Theo em, vic s dng my hi nc ni ring v ng c nhit ni chung c nhng hn ch no?",
    "",
    "**? Cu hi:**",
    "1. C ch ca cc phn ng ho hc c gii thch da trn kin thc thuc lnh vc no ca Vt l?",
    "2. Kin thc v t trng Tri t c dng  gii thch c im no ca loi chim di tr?",
    "3. S tng tc gia cc thin th c gii thch da vo nh lut vt l no ca Newton?",
    "4. Hy nu thm v d v vic dng kin thc vt l  gii thch hin tng t nhin m cc em  hc.",
    "",
    "Nh vic khm ph ra hin tng cm ng in t ca nh vt l Faraday m sau  cc my pht in ra i, m u cho k nguyn s dng in nng ca nhn loi v l mt trong nhng c s cho s ra i ca cuc cch mng cng nghip ln th hai vo cui th k XIX. Mt trong nhng c trng c bn ca cuc cch mng cng nghip ny l s xut hin cc thit b dng in trong mi lnh vc sn xut v i sng con ngi (Hnh 1.2).",
    "",
    "[Hnh 1.2. Nh my thu in Ho Bnh]",
    "",
    "**? Cu hi:**",
    "Theo em, s dng ng c in c nhng u im vt tri no so vi s dng my hi nc?",
    "",
    "Cuc cch mng cng nghip ln th ba bt u vo nhng nm 70 ca th k XX, vi c trng l t ng ho cc qu trnh sn xut (xy dng cc dy chuyn sn xut t ng) cng l nh c nhng thnh tu nghin cu v in t, cht bn dn v vi mch,... ca Vt l hc (Hnh 1.3).",
    "",
    "[Hnh 1.3. Dy chuyn sn xut  t]",
    "",
    "8",
    "CHNG I  M U",
    "",
    "**? Cu hi:**",
    "Hy k tn mt s nh my t ng ho qu trnh sn xut  nc ta.",
    "",
    "Cuc cch mng cng nghip ln th t c coi l bt u vo u th k XXI vi tc  pht trin v mc  nh hng vt xa cc cuc cch mng cng nghip trc . c trng ca cuc cch mng cng nghip ny l s dng tr tu nhn to, robot, internet ton cu, cng ngh vt liu siu nh (nano); l s xut hin t bng n thng minh, in thoi thng minh n nh  thng minh, nh my thng minh. Tt c u da trn nhng thnh tu ca cc lnh vc nghin cu khc nhau ca Vt l hin i (Hnh 1.4).",
    "",
    "[Hnh 1.4. Robot v my tnh]",
    "",
    "**Hot ng:**",
    "Hy su tm ti liu trn internet v cc phng tin truyn thng khc v thnh ph thng minh (thnh ph s)  trnh by v tho lun trn lp v ch  \"Th no l thnh ph thng minh?\"",
    "",
    "c) Vai tr ca Vt l trong s pht trin cc cng ngh nu trn cho thy s nh hng to ln ca n i vi cuc sng con ngi. Mi thit b m con ngi s dng hng ngy u t nhiu gn vi nhng thnh tu nghin cu ca Vt l.",
    "Tuy nhin, vic ng dng cc thnh tu ca Vt l vo cng ngh khng ch mang li li ch cho nhn loi m cn c th lm  nhim mi trng sng, hu hoi h sinh thi,... nu khng c s dng ng phng php, ng mc ch (Hnh 1.5, 1.6).",
    "",
    "[Hnh 1.5. Kh thi t nh my]",
    "[Hnh 1.6. V n bom nguyn t]",
    "",
    "**? Cu hi:**",
    "1. Hy nu mi lin quan gia cc lnh vc ca Vt l i vi mt s dng c gia nh m em thng s dng.",
    "2. Hy ni v nh hng ca Vt l i vi mt s lnh vc nh: giao thng vn ti; thng tin lin lc; nng lng; du hnh v tr;... Su tm hnh nh  minh ho.",
    "3. Hy nu v d v  nhim mi trng v hu hoi h sinh thi m em bit  a phng mnh.",
    "",
    "## IV. PHNG PHP NGHIN CU VT L",
    "",
    "**1. Phng php thc nghim**",
    "Phng php thc nghim l phng php quan trng ca Vt l.",
    "Cu chuyn di y v s ra i ca phng php thc nghim s gip cc em hiu c c im ca phng php ny. T vic quan st s ri ca cc vt nng nh khc nhau m Aristotle, mt nh khoa hc Hy Lp sng vo nhng nm 300 trc Cng nguyn cho rng: Vt nng ri nhanh hn vt nh, vt cng nng ri cng nhanh (Hnh 1.7a).",
    "",
    "9",
    "Quan im ny thng tr trong Vt l hc ngt 2000 nm cho n khi Galilei nghi ng n. ng suy lun rng, nu nh vt nng ri nhanh hn vt nh th khi buc vt nng vo vt nh ri cho chng ri, vt nh s ko vt nng li, lm n ri chm i, cn vt nng s ko vt nh theo lm n ri nhanh ln. Nh vy, c hai vt cng ri s phi ri nhanh hn vt nh v ri chm hn vt nng. iu ny tht v l. ng d on cc vt nng nh ri nhanh nh nhau.  kim tra d on ny, ng  lm th nghim th nhng qu cu c trng lng khc nhau ri t thp nghing Pisa (Hnh 1.7b). Kt qu l chng u ri chm t cng mt lc, ng nh d on ca ng.",
    "Nh th nghim ny, Galilei  bc b c quan im ca Aristotle, ng thi m ra k nguyn ca phng php thc nghim trong Vt l.",
    "M hnh v phng php thc nghim gm cc bc nh trong Hnh 1.8.",
    "",
    "[Hnh 1.7. Aristotle (a) v Galilei (b)]",
    "[Hnh 1.8. S  cc bc ca phng php thc nghim]",
    "Bc 1: Xc nh vn  cn nghin cu",
    "Bc 2: Quan st, thu thp thng tin",
    "Bc 3: a ra d on",
    "Bc 4: Tin hnh th nghim kim tra d on",
    "- Nu kt qu th nghim khng ph hp vi d on: Quay li Bc 3 hoc Bc 2.",
    "- Nu kt qu th nghim ph hp vi d on: Kt lun.",
    "",
    "**? Cu hi:**",
    "Hy phn tch s tin trin qu trnh nghin cu ca Galilei theo s  trn.",
    "",
    "**2. Phng php m hnh**",
    "Vic dng cc m hnh  nghin cu, gii thch cc tnh cht ca vt tht, tm ra c ch hot ng ca n... c gi l phng php m hnh.",
    "",
    "Cc loi m hnh thng dng  trng ph thng:",
    "- M hnh vt cht:  l cc vt thu nh hoc phng to ca vt tht, c mt s c im ging vt tht. Qu a cu l m hnh thu nh ca Tri t (Hnh 1.9a), h Mt Tri l m hnh h hnh tinh (Hnh 1.9b)...",
    "- M hnh l thuyt: Khi nghin cu s ri ca cc vt, ngi ta pht hin ra s ri nhanh hay chm ca cc vt ph thuc vo sc cn ca khng kh. Nu coi sc cn khng kh l khng ng k th cc vt ri t do l ri nh nhau. Coi sc cn khng kh khng ng k l m hnh l thuyt.  chng trnh Trung hc c s, cc em  dng m hnh tia sng (Hnh 1.9c)  biu din ng truyn ca nh sng.",
    "",
    "10",
    "CHNG I  M U",
    "",
    "Aristotle dng suy lun  bo v  kin ca mnh. ng  lp lun nh sau: Bn hn  buc li vi nhau, ri nhanh gp 4 ln mt hn , cng ging nh xe ko bng bn con nga chy nhanh gp 4 ln xe ko bng mt con nga (Hnh 1.7c).",
    "Vo thi i ca Aristotle, khoa hc cha pht trin, Aristotle li l mt nh bc hc rt c uy tn, nn chng ai nghi ng  kin ca ng, chng ai ngh n vic kim tra xem c tht bn hn  buc li vi nhau ri nhanh gp 4 ln mt hn  hay khng.",
    "Phi mi gn 20 th k sau, khi khoa hc  bt u pht trin, mi c ngi ngh n vic kim tra xem  kin ca Aristotle c ng hay khng.  l Galilei,  thnh ph Pisa nc Italia. Galilei  lm nh sau:",
    "1. Xc nh vn  cn tm hiu: C ng vt nng ri nhanh hn vt nh khng?",
    "2. Bng nhng quan st hng ngy, ng  thy khi tri ma nhng git nc ma d to hay nh u ri xung nh nhau, cng ging nh khi c tuyt ri th nhng ht tuyt to hay nh cng ri xung nh nhau.",
    "3. T nhng quan st ca mnh, Galilei d on: S ri nhanh hay chm khng ph thuc vo vt nng hay nh (Hnh 1.7b).",
    "4. Khc vi Aristotle ch dng li  suy lun, Galilei ngh ra cch lm th nghim  kim tra d on ca mnh. ng cho rng nu dng th nghim chng minh c hai vt nng, nh rt khc nhau u ri nhanh nh nhau th s bc b c  kin ca Aristotle.",
    "ng cng cc hc tr ca mnh mang ln thp nghing Pisa hai qu cu bng kim loi, qu to nng gp khong 10 ln qu nh v th hai qu cu xung cng mt lc. Trc s chng kin ca hng trm ngi dn thnh ph Pisa, c hai qu cu u ri nhanh nh nhau, cng chm t mt lc (Hnh 1.7d).",
    "5. Th nghim  chng t  kin ca Galilei l ng: S ri nhanh hay chm khng ph thuc vo vt nng hay nh.",
    "Phng php m Galilei dng  trn sau ny c gi l phng php thc nghim v Galilei c coi l \"cha \" ca phng php ny. S  ca phng php thc nghim c m t trn Hnh 1.8.",
    "Nu th nghim chng t d on l sai th ngi ta phi a ra d on mi v lm th nghim kim tra d on ny, hoc xc nh li vn  cn nghin cu.",
    "",
    "[Bng so snh Quan nim v s ri ca cc vt nng nh khc nhau: Aristotle (Phng php nghin cu: Quan st v suy lun) vs Galilei (Phng php nghin cu: Thc nghim). Km theo hnh nh minh ha 1.7c, 1.7d]",
    "*Hnh 1.7. So snh quan nim, phng php nghin cu ca Aristotle v Galilei*",
    "",
    "[S  cc bc ca phng php thc nghim: 1. Xc nh vn  cn nghin cu -> 2. Quan st, thu thp thng tin -> 3. a ra d on -> 4. Th nghim kim tra d on -> 5. Kt lun]",
    "*Hnh 1.8. S  ca phng php thc nghim*",
    "",
    "**? Cu hi:**",
    "Nu mt v d v s dng phng php thc nghim m em  c hc trong mn KHTN.",
    "",
    "10",
    "CHNG I  M U",
    "",
    "**2. Phng php m hnh**",
    "y l phng php dng cc m hnh  nghin cu, gii thch cc tnh cht ca vt tht, tm ra c ch hot ng ca n,... Cc loi m hnh sau y l cc m hnh thng dng  trng ph thng:",
    " M hnh vt cht:  l cc vt thu nh hoc phng to ca vt tht, c mt s c im ging vt tht. Qu a cu trong phng th nghim l v d v m hnh vt cht thu nh ca Tri t, h Mt Tri c th coi l m hnh vt cht phng to ca mu nguyn t ca Rutherford.",
    " M hnh l thuyt: Khi nghin cu chuyn ng ca mt  t ang chy trn ng di, ngi ta coi  t l mt \"cht im\", khi nghin cu v nh sng ngi ta dng m hnh tia sng  biu din ng truyn ca nh sng.",
    "Cht im, tia sng nu trn l cc v d v m hnh l thuyt.",
    " M hnh ton hc:  l cc cng thc, phng trnh,  th, k hiu,... ca Ton hc dng  m t cc c im ca cc i tng nghin cu. Vect dng  m t mt i lng c hng, v d lc,  dch chuyn; phng trnh $s = v.t$ l m hnh ton hc ca chuyn ng thng u,...",
    "Tu theo tng loi m hnh c th m c th c cc quy trnh xy dng v s dng m hnh khc nhau. Tuy nhin cc bc sau y c coi l cc bc cn thit cho vic xy dng mi loi m hnh:",
    "1. Xc nh i tng cn c m hnh ho.",
    "2. a ra cc m hnh khc nhau  th nghim.",
    "3. Kim tra s ph hp ca cc m hnh vi cc kt qu cho bi th nghim, thc t, l thuyt.",
    "4. Kt lun v m hnh.",
    "",
    "**? Cu hi:**",
    "1. Hy k tn mt s m hnh vt cht m em thy trong phng th nghim.",
    "2. Hy nu tn mt m hnh l thuyt m em  hc.",
    "3. Cc m hnh ton hc v  Hnh 1.9 dng  m t loi chuyn ng no?",
    "[Hnh 1.9 a)  th s-t; b)  th v-t]",
    "",
    "[S  ca phng php m hnh: 1. Xc nh i tng cn m hnh ho -> 2. Xy dng m hnh (gi thuyt) -> 3. Kim tra s ph hp ca m hnh -> 4. Kt lun / iu chnh m hnh nu cn]",
    "*Hnh 1.10. S  ca phng php m hnh*",
    "",
    "**EM  HC**",
    "- i tng nghin cu ch yu ca Vt l l cc dng ca vt cht, nng lng.",
    "- Phng php nghin cu thng s dng ca Vt l l phng php thc nghim v phng php m hnh.",
    "- Vt l c coi l c s ca KHTN v cng ngh.",
    "",
    "**EM C TH**",
    "D on v s ph thuc tc  bay hi ca nc vo nhit  nc v gi thi trn mt nc, ri lp phng n th nghim  kim tra d on.",
    "",
    "11"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B2', 'Bài 2. Các quy tắc an toàn trong phòng thực hành vật lí', 13, 3, $JSON$
{
  "content": [
    "# Bi 2 CC QUY TC AN TON TRONG PHNG THC HNH VT L",
    "",
    "**Khi ng:** Khi lm th nghim cn m bo ngi lm th nghim khng gp nguy him,  dng, thit b khng b h hng, chy n. Lm th no  m bo an ton trong khi tin hnh th nghim?",
    "",
    "## I. AN TON KHI S DNG THIT B TH NGHIM",
    "**1. S dng cc thit b in**",
    "Trong s cc th nghim vt l ph thng th cc thit b s dng in c nguy c mt an ton cao nht. Cn quan st k cc k hiu v nhn thng s trn thit b  s dng ng chc nng, ng yu cu k thut.",
    "",
    "[Hnh 2.1a: My bin p (my bin th) vi cc cng AC, DC]",
    "[Hnh 2.1b: B chuyn i in p vi cc thng s input, output]",
    "*Hnh 2.1. Hai loi thit b cung cp ngun in*",
    "",
    "**Hot ng:** Hy quan st hai thit b chuyn i in p, tham kho k hiu  Bng 2.1 v tho lun  tr li cc cu hi sau:",
    "1. Chc nng ca hai thit b l g? Ging v khc nhau nh th no?",
    "2. B chuyn i in p (Hnh 2.1b) s dng hiu in th vo bao nhiu?",
    "3. Cc hiu in th u ra nh th no?",
    "4. Nhng nguy c no c th gy mt an ton hoc hng cc thit b khi s dng thit b chuyn i in p ny?",
    "",
    "12",
    "CHNG I  M U",
    "",
    "**Bng 2.1. Mt s k hiu trn cc thit b th nghim**",
    "",
    "| K hiu | M t | K hiu | M t |",
    "|---|---|---|---|",
    "| DC hoc du  | Dng in mt chiu | \"+\" hoc mu  | Cc dng |",
    "| AC hoc du ~ | Dng in xoay chiu | \"\" hoc mu xanh | Cc m |",
    "| Input (I) | u vo | [K hiu hai mi tn ch ln] | Dng c t ng |",
    "| Output | u ra | [K hiu mt tri b gch cho] | Trnh nh nng chiu trc tip |",
    "| [K hiu hnh thoi mu ] | Bnh kh nn p sut cao | [K hiu li thu tinh] | Dng c d v |",
    "| [K hiu cnh bo tia laser] | Cnh bo tia laser | [K hiu thng rc b gch cho] | Khng c php b vo thng rc |",
    "| [K hiu cnh bo nhit  cao] | Nhit  cao | [K hiu du chm than] | Lu  cn thn |",
    "| [K hiu nam chm] | T trng | | |",
    "",
    "**2. S dng cc thit b nhit v thu tinh**",
    "Cc thit b un nng c th gy bng vi ngi s dng, gy nt, v cc b phn lm bng thu tinh.",
    "",
    "**Hot ng:** Quan st thit b th nghim v nhit hc  Hnh 2.2 v cho bit: c im ca cc dng c th nghim trong khi tin hnh th nghim  m bo an ton cn ch  n iu g?",
    "[Hnh 2.2. Th nghim o nhit  si ca nc. Hnh nh cho thy Nhit k, Bnh thu tinh chu nhit, n cn]",
    "",
    "**3. S dng cc thit b quang hc**",
    "Cc thit b quang hc rt d mc, xc, nt, v v dnh bi bn, lm nh hng n ng truyn tia sng v sai lch kt qu th nghim.",
    "",
    "**Hot ng:** Quan st thit b th nghim quang hnh (Hnh 2.3) v cho bit: c im ca cc dng c th nghim khi s dng v bo qun thit b cn ch  n iu g?",
    "[Hnh 2.3. B th nghim quang hnh. Hnh nh cho thy n, Thu knh, Mn nh, Gng phng]",
    "",
    "13",
    "CHNG I  M U",
    "",
    "## II. NGUY C MT AN TON TRONG S DNG THIT B TH NGHIM VT L",
    "**1. Nguy c gy nguy him cho ngi s dng**",
    "Vic thc hin sai thao tc s dng cc thit b c th dn n nguy him cho ngi s dng. V vy, khi tin hnh th nghim cn tun th nghim ngt cc quy nh trong phng thc hnh v hng dn ca gio vin.",
    "",
    "**Hot ng:** Em hy quan st mt s hnh nh v thao tc s dng cc thit b th nghim trong Hnh 2.4 v d on xem c nhng nguy c no c th gy nguy him trong phng thc hnh vt l.",
    "K thm nhng thao tc s dng thit b th nghim khc c th gy nguy him trong phng thc hnh.",
    "[Hnh 2.4a: Cm phch in vo  (tay cm khng ng cch)]",
    "[Hnh 2.4b: Rt phch in (cm vo dy thay v phch)]",
    "[Hnh 2.4c: Dy in b sn]",
    "[Hnh 2.4d: Chiu tia laser (chiu vo mt)]",
    "[Hnh 2.4e: un nc trn n cn (khng cn thn)]",
    "*Hnh 2.4. Mt s thao tc c th gy mt an ton khi s dng thit b th nghim*",
    "",
    "**2. Nguy c hng thit b o in**",
    "Khi s dng cc thit b o in cn chn ng thang o, khng nhm ln khi thao tc  m bo an ton cho thit b o.",
    "",
    "**? Cu hi:**",
    "1. Gii hn o ca ampe k  Hnh 2.5 l bao nhiu?",
    "2. Nu s dng ampe k  o dng in vt qu gii hn o th c th gy ra nguy c g?",
    "",
    "Khi s dng ng h o in a nng (thit b o in vi cc chc nng chnh l o in tr, o hiu in th v o dng in AC, DC), cn lu :",
    " Chn chc nng v thang o ph hp.",
    " Cm dy o vo cht cm ph hp vi chc nng o.",
    "",
    "[Hnh 2.5: Ampe k kim, c gii hn o 3A, ang cm  cht 3A]",
    "*Hnh 2.5. Ampe k*",
    "",
    "14",
    "CHNG I  M U",
    "",
    "[Hnh 2.6a: ng h o in a nng kim khung quay]",
    "[Hnh 2.6b: ng h o in a nng hin s]",
    "*Hnh 2.6. ng h o in a nng kim khung quay a) v ng h o in a nng hin s b)*",
    "",
    "**? Cu hi:**",
    "iu chnh v tr ca kim o, chn thang o v cm cc dy o trn ng h a nng (Hnh 2.6)  o hiu in th, cng  dng in v in tr nh th no?",
    "",
    "**3. Nguy c chy n trong phng thc hnh**",
    "Khi tin hnh th nghim vi cc thit b in v nhng ho cht, cht d chy n trong phng thc hnh cn tun th quy tc an ton, nht l nhng quy tc an ton v phng chy cha chy v an ton khi s dng ho cht d chy, n.",
    "",
    "**Hot ng:** Em hy quan st mt s hnh nh v cc th nghim trong Hnh 2.7 v d on c nhng nguy c chy n no c th xy ra trong phng thc hnh.",
    "[Hnh 2.7a:  cc kp in gn nhau]",
    "[Hnh 2.7b:  cht d chy gn th nghim mch in]",
    "[Hnh 2.7c: Khng eo gng tay cao su chu nhit khi lm th nghim vi nhit  cao]",
    "*Hnh 2.7. Mt s tnh hung thc hin th nghim trong phng thc hnh*",
    "",
    "**! Ch :** Khi phng thc hnh c m chy, cn ngt in, t chc thot nn, cu ngi, cu ti sn, chng chy lan, dp tt m chy.",
    "Mt s lu :",
    " Ngt ton b h thng in.",
    " a ton b cc ho cht, cc cht d chy ra khu vc an ton.",
    " Khng c s dng nc dp m chy ni c cc thit b in, m chy hydrocacbon hoc cc cht lng c t trng nh hn nc nh du, cn,...",
    " Khng c s dng CO$_2$  dp tt m chy qun o trn ngi hoc chy kim loi kim nh magnesium, cc cht chy c kh nng tch oxygen nh peroxide, chlorate, potassium nitrate,...",
    "",
    "15",
    "CHNG I  M U",
    "",
    "## III. QUY TC AN TON TRONG PHNG THC HNH",
    " c k hng dn s dng thit b v quan st cc ch dn, cc k hiu trn cc thit b th nghim.",
    " Kim tra cn thn thit b, phng tin, dng c th nghim trc khi s dng.",
    " Ch tin hnh th nghim khi c s cho php ca gio vin hng dn th nghim.",
    " Tt cng tc ngun thit b in trc khi cm hoc tho thit b in.",
    " Ch cm phch / gic cm ca thit b in vo  cm khi hiu in th ca ngun in tng ng vi hiu in th nh mc ca dng c.",
    " Phi b tr dy in gn gng, khng b vng khi qua li.",
    " Khng tip xc trc tip vi cc vt v cc thit b th nghim c nhit  cao khi khng c dng c bo h.",
    " Khng  nc cng nh cc dung dch dn in, dung dch d chy gn thit b in.",
    " Gi khong cch an ton khi tin hnh th nghim nung nng cc vt, th nghim c cc vt bn ra, tia laser.",
    " Phi v sinh, sp xp gn gng cc thit b v dng c th nghim, b cht thi th nghim vo ng ni quy nh sau khi tin hnh th nghim.",
    "",
    "[Hnh 2.8. Cc bin bo trong phng th nghim]",
    "[Bin bo Cht c sc kho]",
    "[Bin bo Cht c mi trng]",
    "[Bin bo Ni nguy him v in]",
    "[Bin bo Li thot him]",
    "[Bin bo Cht d chy]",
    "[Bin bo Cht n mn]",
    "[Bin bo Ni cm la]",
    "[Bin bo Ni c cht phng x]",
    "",
    "**! Ch :** Khi pht hin ngi b in git cn nhanh chng ngt ngun in hoc s dng vt cch in  tch ngi b nn ra khi ngun in.",
    "",
    "**EM  HC**",
    "-  m bo an ton khi s dng thit b trong phng thc hnh, cn c k hng dn v cc k hiu trn thit b.",
    "- Thc hin nghim tc cc quy nh v an ton trong phng thc hnh.",
    "",
    "**EM C TH**",
    "Gii thch c v sao:",
    "1. Khi s dng thit b o in, phi lun t  thang o ph hp.",
    "2. Khi s dng my bin p phi t nt iu chnh in p  mc thp nht ri tng dn ln.",
    "",
    "**EM C BIT?**",
    "1. Sc in (hay in git): Sc in xy ra khi dng in chy qua ngi, c th gy ra tn thng cc b phn ca c th hoc t vong.",
    "2. Khi c ho hon cn bnh tnh, s dng cc bin php dp tt ngn la theo hng dn ca phng thc hnh.",
    "",
    "16"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B3', 'Bài 3. Thực hành tính sai số trong phép đo. Ghi kết quả đo', 18, 4, $JSON$
{
  "content": [
    "# Bi 3 THC HNH TNH SAI S TRONG PHP O. GHI KT QU O",
    "",
    "**Khi ng:** Khng mt php o no c th cho ta gi tr ng ca i lng cn o, mi php o u c sai s. Lm th no  xc nh c cc sai s ny? Nguyn nhn gy ra cc sai s l g v cch khc phc nh th no?",
    "",
    "## I. PHP O TRC TIP V PHP O GIN TIP",
    " o trc tip mt i lng bng dng c o, kt qu c c trc tip trn dng c o c gi l *php o trc tip*.",
    " o mt i lng khng trc tip m thng qua cng thc lin h vi cc i lng c th o trc tip gi l *php o gin tip*.",
    "",
    "**? Cu hi:**",
    "Em hy lp phng n o tc  chuyn ng ca chic xe  t  chi ch dng thc, ng h bm giy v tr li cc cu hi sau:",
    "a)  o tc  chuyn ng ca chic xe cn o nhng i lng no?",
    "b) Xc nh tc  chuyn ng ca xe theo cng thc no?",
    "c) Php o no l php o trc tip? Ti sao?",
    "d) Php o no l php o gin tip? Ti sao?",
    "",
    "## II. SAI S PHP O",
    "**1. Phn loi sai s**",
    "**a) Sai s h thng**",
    "Khi s dng dng c o  o cc i lng vt l lun c s sai lch do c im v cu to ca dng c gy ra.",
    "S sai lch ny gi l sai s dng c hoc sai s h thng.",
    "Sai s h thng c nguyn nhn khch quan (do dng c), nguyn nhn ch quan do ngi o (cn loi b).",
    "",
    "**b) Sai s ngu nhin**",
    "Khi lp li cc php o, ta nhn c cc gi tr khc nhau, s sai lch ny khng c nguyn nhn r rng nn gi l sai s ngu nhin, c th do thao tc o khng chun, iu kin lm th nghim khng n nh hoc hn ch v gic quan,...",
    " khc phc ngi ta thng tin hnh th nghim nhiu ln v tnh sai s.",
    "",
    "**! Ch :** Sai s gy bi dng c s dng o thng ly bng mt na  chia nh nht trn dng c (v d thc o chiu di c  chia nh nht l 1 mm th sai s dng c l 0,5 mm), hoc c ghi trc tip trn dng c do nh sn xut xc nh.",
    "",
    "17",
    "CHNG I  M U",
    "",
    "**2. Cch xc nh sai s php o**",
    "- *Sai s ngu nhin tuyt i* ca tng ln o l tr tuyt i ca hiu s gia gi tr trung bnh cc ln o v gi tr ca mi ln o ca php o trc tip.",
    "$\\Delta A_1 = |\\overline{A} - A_1|; \\Delta A_2 = |\\overline{A} - A_2|; ...; \\Delta A_n = |\\overline{A} - A_n|$ (3.1)",
    "Trong : $\\overline{A} = \\frac{A_1 + A_2 + ... + A_n}{n}$",
    "Sai s ngu nhin tuyt i trung bnh ca n ln o c tnh theo cng thc:",
    "$\\overline{\\Delta A} = \\frac{\\Delta A_1 + \\Delta A_2 + ... + \\Delta A_n}{n}$ (3.2)",
    "Sai s tuyt i ca php o l tng sai s ngu nhin v sai s dng c:",
    "$\\Delta A = \\overline{\\Delta A} + \\Delta A_{dc}$",
    "- *Sai s t i* ca php o l t l phn trm gia sai s tuyt i v gi tr trung bnh ca i lng o, cho bit mc  chnh xc ca php o.",
    "$\\delta A = \\frac{\\Delta A}{\\overline{A}} . 100\\%$ (3.3)",
    "",
    "**3. Cch xc nh sai s php o gin tip**",
    " xc nh sai s ca php o gin tip, vn dng quy tc sau:",
    "- Sai s tuyt i ca mt tng hay hiu bng tng cc sai s tuyt i ca cc s hng.",
    "A = B + C",
    "$\\Delta A = \\Delta B + \\Delta C$",
    "- Sai s t i ca mt tch hay thng th bng tng cc sai s t i ca cc tha s.",
    "A = B.C",
    "$\\delta A = \\delta B + \\delta C$",
    "- T sai s t i, c th s dng cng thc (3.3)  tnh c sai s tuyt i.",
    "*V d 1:* o qung ng s t A n C bng tng qung ng $s_1$ t A n B v $s_2$ t B n C.",
    "Sai s tuyt i: $\\Delta s = \\Delta s_1 + \\Delta s_2$",
    "*V d 2:* o tc  theo cng thc $v = \\frac{s}{t}$, sai s php o l:",
    "$\\delta v = \\frac{\\Delta s}{\\overline{s}} . 100\\% + \\frac{\\Delta t}{\\overline{t}} . 100\\%$",
    "$\\Delta v = \\delta v . \\overline{v}$",
    "",
    "**4. Cch ghi kt qu o**",
    "- Kt qu o i lng A c ghi di dng mt khong gi tr:",
    "$(\\overline{A} - \\Delta A) \\le A \\le (\\overline{A} + \\Delta A)$ hoc $A = \\overline{A} \\pm \\Delta A$",
    "Trong :",
    "+ $\\Delta A$ l sai s tuyt i thng vit n s ch s c ngha ti n v ca  chia nh nht (CNN) trn dng c o.",
    "+ Gi tr trung bnh $\\overline{A}$ c vit n bc thp phn tng ng vi $\\Delta A$.",
    "- Quy tc lm trn s:",
    "+ Nu ch s  hng b i nh hn 5 th ch s bn tri vn gi nguyn.",
    "+ Nu ch s hng b i ln hn hoc bng 5 th ch s bn tri tng thm mt n v.",
    "",
    "$^{(1), (2)}$ K hiu $\\Delta, \\delta$ u c l \"en - ta\".",
    "",
    "**EM C BIT?**",
    "Cch xc nh sai s t i ca mt tch hay mt thng khi cc i lng c lu tha",
    "V d: Nu $A = B.\\sqrt{C}$ th $\\delta A = \\delta B + \\frac{1}{2}.\\delta C$",
    "",
    "18",
    "CHNG I  M U",
    "",
    "**Hot ng:** Dng mt thc c CNN l 1 mm v mt ng h o thi gian c CNN 0,01 s  o 5 ln thi gian chuyn ng ca chic xe  chi chy bng pin t im A ($v_A = 0$) n im B (Hnh 3.1). Ghi cc gi tr vo Bng 3.1 v tr li cc cu hi.",
    "",
    "**Bng 3.1**",
    "| n | s (m) | $\\Delta s (m)$ | t (s) | $\\Delta t (s)$ |",
    "|---|---|---|---|---|",
    "| 1 | | | | |",
    "| 2 | | | | |",
    "| 3 | | | | |",
    "| 4 | | | | |",
    "| 5 | | | | |",
    "| Trung bnh | $\\overline{s} = ...$ | $\\overline{\\Delta s} = ...$ | $\\overline{t} = ...$ | $\\overline{\\Delta t} = ...$ |",
    "",
    "[Hnh 3.1. Th nghim o tc . Hnh nh c mt chic xe  chi vng, im A v B, v mt ng h bm giy]",
    "",
    "a) Nguyn nhn no gy ra s sai khc gia cc ln o?",
    "b) Tnh sai s tuyt i ca php o s, t v in vo Bng 3.1.",
    "c) Vit kt qu o:",
    "$s = .......... ; t = ..........$",
    "d) Tnh sai s t i:",
    "$\\delta t = \\frac{\\Delta t}{\\overline{t}} . 100\\% = ...; \\delta s = \\frac{\\Delta s}{\\overline{s}} . 100\\% = ...$",
    "$\\delta v = ...; \\Delta v = ...$",
    "",
    "**EM  HC**",
    "- C hai loi php o l php o trc tip v php o gin tip.",
    "- Hai loi sai s gm sai s dng c v sai s ngu nhin.",
    "- Cch ghi kt qu o: $A = \\overline{A} \\pm \\Delta A$ vi $\\Delta A = \\overline{\\Delta A} + \\Delta A_{dc}$.",
    "",
    "**EM C TH**",
    "1. Gii thch c ti sao  o mt i lng chnh xc ngi ta cn lp li php o nhiu ln v tnh sai s.",
    "2. Tnh c sai s tuyt i, sai s t i ca php o trc tip v php o gin tip.",
    "",
    "**EM C BIT?**",
    "Sai s v kt qu ca php o c th biu din bng  th. Phng php  th cho php tm quy lut s ph thuc ca i lng y vo i lng x.",
    "Khi s dng  th cn ch  cch biu din cc gi tr c sai s:",
    "Mi gi tr c c t thc nghim u c sai s: $\\pm \\Delta x$ v $\\pm \\Delta y$. Do  trn  th, mi gi tr s c biu din bng mt im nm trong  ch nht c cnh l $2\\Delta x$ v $2\\Delta y$.",
    "",
    "[Hnh 3.2. Biu din sai s bng  th]",
    "",
    "19"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B4', 'Bài 4. Độ dịch chuyển và quãng đường đi được', 22, 1, $JSON$
{
  "content": [
    "# Bi 4  DCH CHUYN V QUNG NG I C",
    "",
    "**Khi ng:**",
    "Mt  t i ti im O ca mt ng t ng c 4 hng: ng, Ty, Nam, Bc vi tc  khng i 36 km/h. Nu  t i tip th sau 10 s:",
    "a) Qung ng i tip ca  t l bao nhiu mt?",
    "b) V tr ca  t  im no trn hnh v?",
    "",
    "[Hnh nh minh ha ng t vi la bn ch hng Bc, Nam, ng, Ty. C cc im A, B, C, D, E, F trn ng i ln (Bc) v i xung (Nam); H, G trn ng sang Tri (Ty) v K, L, M trn ng sang Phi (ng). Khong cch 1 on nh l 50m.]",
    "",
    "## I. V TR CA VT CHUYN NG TI CC THI IM",
    "Khi vt chuyn ng th v tr ca vt so vi vt c chn lm mc thay i theo thi gian. Bi ton c bn ca ng hc l xc nh v tr ca vt ti cc thi im khc nhau.",
    "-  xc nh v tr ca vt, ngi ta dng h to  vung gc c gc l v tr ca vt mc, trc honh Ox v trc tung Oy. Cc gi tr trn cc trc to  c xc nh theo mt t l xc nh.",
    "V d: Nu t l l $\\frac{1}{1000}$ th v tr ca im A trong Hnh 4.1 c xc nh trn h to  l A (x = 10 m; y = 20 m) v ca im B l B (x = - 10 m; y = 20 m).",
    "",
    "[Hnh 4.1. H to : Trc Ox nm ngang, Oy thng ng, gc O. im A(1, 2) v im B(-1, 2) trn  th vi ch thch \"T xch 1 cm ng vi 10 m\"]",
    "",
    "**EM C BIT?**",
    "1. ng hc l phn vt l nghin cu chuyn ng ca vt m khng  cp n tc dng ca lc ln chuyn ng.",
    "2. Khi kch thc ca vt rt nh so vi  di ca qung ng i c th vt c coi l cht im. Trong chng ny chng ta ch tm hiu chuyn ng ca cht im.",
    "",
    "21",
    "CHNG II  NG HC",
    "",
    "Trong thc t, ngi ta thng chn h to  trng vi h to  a l, c gc l v tr ca vt mc, trc honh l ng ni hai hng a l Ty  ng, trc tung l ng ni hai hng a l Bc  Nam (Hnh 4.2).",
    "V d: Nu OA = 2 cm v t l l $\\frac{1}{1000}$ th v tr ca im A cch im gc 20 m theo hng 45 ng  Bc: A (d = 20 m; 45 ng  Bc).",
    "",
    "[Hnh 4.2. H to  a l. im O, trc Ty - ng, trc Bc - Nam. im A c gc 45  so vi trc ng.]",
    "",
    "**? Cu hi:**",
    "Hy dng bn  Vit Nam v h to  a l, xc nh v tr ca thnh ph Hi Phng so vi v tr ca Th  H Ni.",
    "",
    "-  xc nh thi im, ngi ta phi chn mt mc thi gian, o khong thi gian t thi im c chn lm mc n thi im cn xc nh.",
    "V d: Nu chn mc thi gian l $t_0$ = 8 h v thi gian chuyn ng l $\\Delta t$ = 2 h, th thi im khi kt thc chuyn ng l $t_n = t_0 + \\Delta t$ = 10 h.",
    "H to  kt hp vi mc thi gian v ng h o thi gian c gi l *h quy chiu*.",
    "",
    "**! Ch :** Khi vt chuyn ng trn ng thng th ch cn dng h to  c im gc O (v tr ca vt mc) v trc Ox trng vi qu o chuyn ng ca vt.",
    "",
    "**? Cu hi:**",
    "Xc nh v tr ca vt A trn trc Ox v  Hnh 4.3 ti thi im 11 h. Bit vt chuyn ng thng, mi gi i c 40 km.",
    "[Hnh 4.3. Xc nh v tr ca vt theo h quy chiu. Trc Ox, $t_0$ = 8 h ti O. on 20 km]",
    "",
    "## II.  DCH CHUYN",
    "Trong bi ton  phn m bi, bit qung ng i c c th xc nh c khong cch gia im u v im cui ca chuyn ng, nhng cha   xc nh v tr ca vt.",
    "Mun xc nh c v tr ca vt phi bit thm hng ca chuyn ng. V d, nu bit  t chuyn ng theo hng Bc th d dng xc nh c v tr ca  t l im B trn bn .",
    "i lng va cho bit  di va cho bit hng ca s thay i v tr ca vt gi l * dch chuyn*.",
    " dch chuyn ca  t trong bi ton trn l:",
    "$d_{OB}$ = 100 m (Bc)",
    "Mt i lng va cho bit  ln, va cho bit hng nh  dch chuyn gi l *i lng vect*.",
    " dch chuyn c biu din bng mt mi tn ni v tr u v v tr cui ca chuyn ng, c  di t l vi  ln ca  dch chuyn. K hiu l $\\vec{d}$.",
    "",
    "22",
    "CHNG II  NG HC",
    "",
    "Hnh 4.4 v vect  dch chuyn ca  t trong bi ton nu  u bi.",
    "",
    "**? Cu hi:**",
    "Hy xc nh cc  dch chuyn m t  Hnh 4.5 trong to  a l.",
    "",
    "[Hnh 4.4. Vect  dch chuyn OB. T xch 1 cm ng vi 50 m]",
    "[Hnh 4.5. Cc vect  dch chuyn $d_1, d_2, d_3$ trn h trc to  ng Ty Nam Bc. T xch 1 cm ng vi 100 m]",
    "",
    "## III. PHN BIT  DCH CHUYN V QUNG NG I C",
    "V d di y gip chng ta phn bit  dch chuyn v qung ng i c.",
    "Trong Hnh 4.6 ngi i xe my (1), ngi i b (2), ngi i  t (3) u khi hnh t siu th A  i n bu in B.",
    "",
    "[Hnh 4.6. S  m t qung ng i c ca ngi i xe my, ngi i b v ngi i  t. im A (Siu th) v im B (Bu in). 3 ng v khc nhau. T xch 1 cm ng vi 100 m]",
    "",
    "**Hot ng:**",
    "1. Hy so snh  ln ca  dch chuyn v qung ng i c ca ba chuyn ng  Hnh 4.6.",
    "2. Theo em, khi no  ln ca  dch chuyn v qung ng i c ca mt chuyn ng bng nhau?",
    "",
    "23",
    "CHNG II  NG HC",
    "",
    "**? Cu hi:**",
    "Bn A i xe p t nh qua trm xng, ti siu th mua  ri quay v nh ct , sau  i xe n trng (Hnh 4.7).",
    "[Hnh 4.7. Trc ta  Ox vi gc ti N (Nh), X (Trm xng)  400m, S (Siu th)  800m, T (Trng)  1200m]",
    "1. Chn h to  c gc l v tr nh bn A, trc Ox trng vi ng i t nh bn A ti trng.",
    "a) Tnh qung ng i c v  dch chuyn ca bn A khi i t trm xng ti siu th.",
    "b) Tnh qung ng i c v  dch chuyn ca bn A trong c chuyn i trn.",
    "2. V Bng 4.1 vo v v ghi kt qu tnh c  cu 1 vo cc  thch hp.",
    "Bng 4.1",
    "| Chuyn ng | Qung ng i c s (m) |  dch chuyn d (m) |",
    "|---|---|---|",
    "| T trm xng n siu th | $s_{XS}$ = ...? | $d_{XS}$ = ...? |",
    "| C chuyn i | $s$ = ...? | $d$ = ...? |",
    "3. Hy da vo bng kt qu trn  kim tra d on ca em trong cu hi 2 cui trang 23 l ng hay sai.",
    "",
    "## IV. TNG HP  DCH CHUYN",
    "C th dng php cng vect  tng hp  dch chuyn ca vt.",
    "*Bi tp v d:* Hai ngi i xe p t A n C, ngi th nht i theo ng t A n B, ri t B n C; ngi th hai i thng t A n C (Hnh 4.8). C hai u v ch cng mt lc.",
    "Hy tnh qung ng i c v  dch chuyn ca ngi th nht v ngi th hai. So snh v nhn xt kt qu.",
    "",
    "*Gii*",
    "Qung ng i c ca ngi th nht:",
    "$s_1 = AB + BC = 4 + 4 = 8$ km",
    "V ABC l tam gic vung nn  ln ca  dch chuyn $\\vec{AC}$ ca ngi th nht c tnh bng cng thc:",
    "$d_1 = \\sqrt{AB^2 + BC^2} = \\sqrt{4^2 + 4^2} \\approx 5,7$ km",
    "",
    "[Hnh 4.8. Tam gic vung ABC vung ti B. AB = 4 km, BC = 4 km. Ngi th nht i A->B->C, ngi th hai i thng A->C]",
    "",
    "24",
    "CHNG II  NG HC",
    "",
    "V ABC l tam gic vung cn nn $\\widehat{CAB} = 45^\\circ$. Hng ca  dch chuyn l hng $45^\\circ$ ng  Bc.  dch chuyn ca ngi th nht l: $d_1 \\approx 5,7$ km (hng $45^\\circ$ ng  Bc).",
    "Qung ng i c ca ngi th hai l:",
    "$s_2 = AC \\approx 5,7$ km",
    " dch chuyn ca ngi th hai l:",
    "$d_2 \\approx 5,7$ km, hng $45^\\circ$ ng  Bc",
    "",
    "**Bng 4.2**",
    "| | Ngi th nht | Ngi th hai |",
    "|---|---|---|",
    "| Qung ng i c | $s_1$ = 8 km | $s_2 \\approx 5,7$ km |",
    "|  dch chuyn | $d_1 \\approx 5,7$ km | $d_2 \\approx 5,7$ km |",
    "",
    "Da vo kt qu  Bng 4.2, ta thy:",
    "- V s dch chuyn v tr ca ngi th nht v ngi th hai l nh nhau u t A n C, nn hai ngi c cng  dch chuyn.",
    "- Tuy v ch cng mt lc nhng ngi th nht i nhanh hn v phi i qung ng di hn. Tuy nhin nu ch ch  n s thay i v tr th phi coi c hai u thay i v tr nhanh nh nhau.",
    "",
    "**? Cu hi:**",
    "1. Mt ngi li  t i thng 6 km theo hng Ty, sau  r tri i thng theo hng Nam 4 km ri quay sang hng ng i 3 km. Xc nh qung ng i c v  dch chuyn ca  t.",
    "2. Mt ngi bi ngang t b bn ny sang b bn kia ca mt dng sng rng 50 m c dng chy theo hng t Bc xung Nam. Do nc sng chy mnh nn khi sang n b bn kia th ngi   tri xui theo dng nc 50 m. Xc nh  dch chuyn ca ngi .",
    "",
    "**EM  HC**",
    "-  dch chuyn l mt i lng vect, cho bit  di v hng ca s thay i v tr ca vt.",
    "- Khi vt chuyn ng thng, khng i chiu th  ln ca  dch chuyn v qung ng i c bng nhau. Khi vt chuyn ng thng, c i chiu th  ln ca  dch chuyn v qung ng i c khng bng nhau.",
    "- Tng hp cc  dch chuyn bng cch tng hp vect.",
    "",
    "**EM C TH**",
    "Xc nh c v tr ca mt a im trn bn .",
    "",
    "25"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B5', 'Bài 5. Tốc độ và vận tốc', 27, 2, $JSON$
{
  "content": [
    "# Bi 5 TC  V VN TC",
    "",
    "**Khi ng:**",
    "Trong i sng, tc  v vn tc l hai i lng u dng  m t s nhanh chm ca chuyn ng. Em  tng s dng hai i lng ny trong nhng trng hp c th no?",
    "",
    "## I. TC ",
    "**1. Tc  trung bnh**",
    "Ngi ta dng hai cch sau y  xc nh  nhanh hay chm ca chuyn ng:",
    "- So snh qung ng i c trong cng mt thi gian.",
    "- So snh thi gian  i cng mt qung ng.",
    "",
    "**Hot ng:**",
    "Mt vn ng vin ngi Nam Phi  lp k lc th gii v chy ba c li: 100 m, 200 m v 400 m (Bng 5.1). Hy dng hai cch trn  xc nh vn ng vin ny chy nhanh nht  c li no.",
    "",
    "**Bng 5.1.** K lc chy ba c li ca mt vn ng vin ngi Nam Phi",
    "| C li chy (m) | Thi gian chy (s) |",
    "|---|---|",
    "| 100 | 9,98 |",
    "| 200 | 19,94 |",
    "| 400 | 43,45 |",
    "Ch : t cng thc (5.1a) suy ra cng thc ca:",
    "- Qung ng i c:",
    "$s = v.t$",
    "- Thi gian i: $t = \\frac{s}{v}$.",
    "",
    "Ngi ta thng dng qung ng i c trong cng mt n v thi gian  xc nh  nhanh, chm ca chuyn ng. i lng ny gi l tc  trung bnh ca chuyn ng (gi tt l tc  trung bnh), k hiu l $v$:",
    "Tc  trung bnh = $\\frac{\\text{Qung ng i c}}{\\text{Thi gian}}$",
    "$v = \\frac{s}{t}$ (5.1a)",
    "",
    "**! Ch :** Nu gi qung ng i c t thi im ban u ti thi im $t_1$ l $s_1$, ti thi im $t_2$ l $s_2$ th:",
    "- Thi gian i l: $\\Delta t = t_2 - t_1$;",
    "- Qung ng i c trong thi gian $\\Delta t$ l $\\Delta s = s_2 - s_1$;",
    "- Tc  trung bnh ca chuyn ng l: $v = \\frac{\\Delta s}{\\Delta t}$ (5.1b)",
    "",
    "**? Cu hi:**",
    "1. Ti sao tc  ny c gi l tc  trung bnh?",
    "2. Hy tnh tc  trung bnh ra n v m/s v km/h ca n vn ng vin ti mt s gii thi u da vo Bng 5.2.",
    "",
    "**Bng 5.2.** Thnh tch ca mt n vn ng vin Vit Nam",
    "| Gii thi u | C li chy (m) | Thi gian chy (s) |",
    "|---|---|---|",
    "| in kinh quc gia 2016 | 100 | 11,64 |",
    "| SEA Games 29 (2017) | 100 | 11,56 |",
    "| SEA Games 30 (2019) | 100 | 11,54 |",
    "",
    "26",
    "CHNG II  NG HC",
    "",
    "**2. Tc  tc thi**",
    "Trn xe my v  t, ng h tc  (tc k) t trc mt ngi li xe, ch tc  m xe ang chy vo thi im ngi li xe c s ch ca tc k. Tc  ny c gi l *tc  tc thi*.",
    "",
    "**? Cu hi:**",
    "B bn A a A i hc bng xe my vo lc 7 gi. Sau 5 pht xe t tc  30 km/h. Sau 10 pht na, xe tng tc  ln thm 15 km/h. n gn trng, xe gim dn tc  v dng trc cng trng lc 7 gi 30 pht.",
    "a) Tnh tc  trung bnh ca xe my ch A khi i t nh n trng. Bit qung ng t nh n trng di 15 km.",
    "b) Tnh tc  ca xe vo lc 7 gi 15 pht v 7 gi 30 pht. Tc  ny l tc  g?",
    "",
    "**EM C BIT?**",
    "Khi nim tc  tc thi lin quan n php tnh o hm ca mn Ton s c hc  lp 11. C th coi tc  tc thi l tc  trung bnh trong mt khong thi gian rt ngn.",
    "",
    "## II. VN TC",
    "**1. Vn tc trung bnh**",
    "Bit tc  v thi gian chuyn ng nhng cha bit hng chuyn ng th cha th xc nh c v tr ca vt. Bit tc , thi gian chuyn ng v hng chuyn ng ca vt th c th xc nh c v tr ca vt.",
    "",
    "[Hnh 5.1. Bn  khu vc quanh Sn vn ng, Ng t c cc im A, B, C, D, E, G, H, I. Trng hc, Siu th]",
    "",
    "**? Cu hi:**",
    "Mt ngi i xe my qua ng t (Hnh 5.1) vi tc  trung bnh 30 km/h theo hng Bc. Sau 3 pht ngi  n v tr no trn hnh?",
    "",
    "**? Cu hi:**",
    "Theo em biu thc no sau y xc nh gi tr vn tc? Ti sao?",
    "a) $\\frac{s}{t}$",
    "b) $vt$",
    "c) $\\frac{d}{t}$",
    "d) $d.t$",
    "",
    "Trong Vt l, ngi ta dng thng s ca  dch chuyn v thi gian dch chuyn  xc nh  nhanh, chm ca chuyn ng theo mt hng xc nh. i lng ny c gi l vn tc trung bnh, k hiu l $\\vec{v}$.",
    "$\\vec{v} = \\frac{\\vec{d}}{t}$ (5.2a)",
    "Tng t nh trng hp (5.1b), ta c th vit: $v = \\frac{\\Delta d}{\\Delta t}$. (5.2b)",
    "Trong  $\\Delta d$ l  dch chuyn trong thi gian $\\Delta t$.",
    "",
    "27",
    "CHNG II  NG HC",
    "",
    "V  dch chuyn l mt i lng vect nn vn tc cng l mt i lng vect. Vect vn tc c:",
    "- Gc nm trn vt chuyn ng;",
    "- Hng l hng ca  dch chuyn;",
    "-  di t l vi  ln ca vn tc.",
    "",
    "**2. Vn tc tc thi**",
    "Vn tc tc thi l vn tc ti mt thi im xc nh, c k hiu l $\\vec{v}_t$:",
    "$\\vec{v}_t = \\frac{\\Delta \\vec{d}}{\\Delta t}$ vi $\\Delta t$ rt nh.",
    "",
    "**3. Tng hp vn tc**",
    "**a) Tng hp hai vn tc cng phng**",
    "*Bi tp v d:* Trn on tu ang chy thng vi vn tc trung bnh 36 km/h so vi mt ng, mt hnh khch i v pha u tu vi vn tc 1 m/s so vi mt sn tu (Hnh 5.3).",
    "a) Hnh khch ny tham gia my chuyn ng?",
    "b) Lm cch no  xc nh c vn tc ca hnh khch i vi mt ng?",
    "",
    "*Gii*",
    "a) Hnh khch ny tham gia 2 chuyn ng: Chuyn ng vi vn tc 1 m/s so vi sn tu v chuyn ng do tu ko i (chuyn ng ko theo) vi vn tc bng vn tc ca tu so vi mt ng. Chuyn ng ca hnh khch so vi mt ng l tng hp ca hai chuyn ng trn.",
    "b) Nu gi $\\vec{v}_{1,2}$ l vn tc ca hnh khch so vi tu, $\\vec{v}_{2,3}$ l vn tc ca tu so vi mt ng v $\\vec{v}_{1,3}$ l vn tc ca hnh khch so vi mt ng th: $\\vec{v}_{1,3} = \\vec{v}_{1,2} + \\vec{v}_{2,3}$",
    "V cc chuyn ng trn u l chuyn ng thng theo hng chy ca on tu nn:",
    "$v_{1,3} = v_{1,2} + v_{2,3} = 1\\text{ m/s} + 10\\text{ m/s} = 11\\text{ m/s}$.",
    "Hng ca vn tc l hng on tu chy.",
    "",
    "[Hnh 5.2. L trnh ABC ca bn A. T nh (A) n B ri t B n Trng (C).]",
    "[Hnh 5.3. Hnh khch i trn tu ang chy. Hng chuyn ng ca tu l sang phi.]",
    "",
    "**? Cu hi:**",
    "Bn A i hc t nh n trng theo l trnh ABC (Hnh 5.2). Bit bn A i on ng AB = 400 m ht 6 pht, on ng BC = 300 m ht 4 pht. Xc nh tc  trung bnh v vn tc trung bnh ca bn A khi i t nh n trng.",
    "",
    "**? Cu hi:**",
    "1. Hy xc nh vn tc ca hnh khch i vi mt ng nu ngi ny chuyn ng v cui on tu vi vn tc c cng  ln 1 m/s.",
    "2. Mt ngi bi trong b bi yn lng c th t ti vn tc 1 m/s. Nu ngi ny bi xui dng sng c dng chy vi vn tc 1 m/s th c th t vn tc ti a l bao nhiu?",
    "3. Mt ca n chy ht tc lc trn mt nc yn lng c th t 21,5 km/h. Ca n ny chy xui dng sng trong 1 gi ri quay li th phi mt 2 gi na mi v ti v tr ban u. Hy tnh vn tc chy ca dng sng.",
    "",
    "28",
    "CHNG II  NG HC",
    "",
    "**b) Tng hp hai vn tc vung gc vi nhau**",
    "*Bi tp v d:* Mt ca n chy trong h nc yn lng c vn tc ti a 18 km/h. Nu ca n chy ngang mt con sng c dng chy theo hng Bc  Nam vi vn tc ln ti 5 m/s th vn tc ti a n c th t c so vi b sng l bao nhiu v theo hng no?",
    "",
    "*Gii*",
    "Gi vn tc ca ca n i vi mt nc l $\\vec{v}_{1,2}$; vn tc ca nc chy i vi b sng l $\\vec{v}_{2,3}$. Vn tc ca ca n i vi b sng l:",
    "$\\vec{v}_{1,3} = \\vec{v}_{1,2} + \\vec{v}_{2,3}$. Suy ra: $v_{1,3} = \\sqrt{v_{1,2}^2 + v_{2,3}^2} = \\sqrt{5^2 + 5^2} = 7,07$ m/s.",
    "V AB = BC nn $\\Delta ABC$ l tam gic vung cn v $\\widehat{BAC} = 45^\\circ$. Hng ca vn tc nghing $45^\\circ$ theo hng ng  Nam (Hnh 5.4).",
    "",
    "[Hnh 5.4. Cc vect vn tc $\\vec{v}_{1,2}, \\vec{v}_{2,3}, \\vec{v}_{1,3}$ to thnh tam gic vung]",
    "",
    "**? Cu hi:**",
    "1. Mt my bay ang bay theo hng Bc vi vn tc 200 m/s th b gi t hng Ty thi vo vi vn tc 20 m/s. Xc nh vn tc tng hp ca my bay lc ny.",
    "2. Mt ngi li my bay th thao ang tp bay ngang. Khi bay t A n B th vn tc tng hp ca my bay l 15 m/s theo hng $60^\\circ$ ng  Bc v vn tc ca gi l 7,5 m/s theo hng Bc.",
    "Hy chng minh rng khi bay t A n B th ngi li phi lun hng my bay v hng ng.",
    "",
    "**EM  HC**",
    "- Tc  trung bnh trn mt on ng xc nh (hoc trong mt khong thi gian xc nh):",
    "$v = \\frac{s}{t}$ hoc $v = \\frac{\\Delta s}{\\Delta t}$",
    "- Tc  tc thi l tc  ti mt thi im xc nh.",
    "- Vn tc trung bnh trn mt  dch chuyn xc nh (hoc trong mt khong thi gian xc nh):",
    "$\\vec{v} = \\frac{\\vec{d}}{t}$ hoc $\\vec{v} = \\frac{\\Delta \\vec{d}}{\\Delta t}$",
    "- Vn tc tc thi l vn tc ti mt thi im xc nh:",
    "$\\vec{v}_t = \\frac{\\Delta \\vec{d}}{\\Delta t}$ vi $\\Delta t$ rt nh.",
    "- Khi vt chuyn ng thng theo mt hng th tc  v vn tc c  ln bng nhau: $v = |\\vec{v}|$.",
    "- Cng thc cng vn tc: $\\vec{v}_{1,3} = \\vec{v}_{1,2} + \\vec{v}_{2,3}$",
    "Trong  $\\vec{v}_{1,2}$ l vn tc ca vt (1) i vi vt (2); $\\vec{v}_{2,3}$ l vn tc ca vt (2) so vi vt (3) ng yn; $\\vec{v}_{1,3}$ (vn tc tng hp ca vt) l vn tc ca vt (1) i vi vt (3).",
    "",
    "**EM C TH**",
    "1. T xc nh c tc  chuyn ng ca mnh trong mt s trng hp n gin.",
    "2. S dng ng cc thut ng tc  v vn tc trong cc tnh hung khc nhau.",
    "",
    "29"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B6', 'Bài 6. Thực hành: Đo tốc độ của vật chuyển động', 31, 3, $JSON$
{
  "content": [
    "# Bi 6 THC HNH: O TC  CA VT CHUYN NG",
    "",
    "**Khi ng:**",
    "Lm th no o c tc  chuyn ng ca vt bng dng c th nghim thc hnh?",
    "",
    "## I. CCH O TC  TRONG PHNG TH NGHIM",
    " o tc  chuyn ng ca mt vt c th o thi gian v qung ng chuyn ng ca vt .",
    "",
