INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B7', 'Bài 7. Đồ thị độ dịch chuyển - thời gian', 35, 4, $JSON$
{
  "content": [
    "# Bi 7  TH  DCH CHUYN  THI GIAN",
    "",
    "**Khi ng:**",
    "Hy nh li kin thc  hc v  th ca chuyn ng trong mn Khoa hc t nhin 7  pht hin ra tnh cht ca cc chuyn ng thng c  th m t  nhng hnh sau.",
    "[Hnh nh cc  th $s-t$ a, b, c, d. Trc tung l $s$, trc honh l $t$.",
    "a)  th l ng thng i ln t gc to .",
    "b)  th l ng thng song song vi trc $t$.",
    "c)  th gm hai ng (1) v (2) i ln t gc to , (1) dc hn (2).",
    "d)  th gm hai ng: (1) t mt im trn trc tung i xung, (2) t mt im thp hn trn trc tung i ln ct (1).]",
    "",
    "## I. CHUYN NG THNG",
    "Chuyn ng thng l chuyn ng thng gp trong i sng, c qu o chuyn ng l ng thng.",
    "Khi vt chuyn ng thng theo mt chiu khng i th  dch chuyn v qung ng i c c  ln nh nhau $d = s$; vn tc v tc  c  ln nh nhau $v = v$.",
    "Khi vt ang chuyn ng thng theo chiu dng, nu i chiu chuyn ng th trong khong thi gian chuyn ng ngc chiu  qung ng i c vn c gi tr dng, cn  dch chuyn c gi tr m; tc  vn c gi tr dng cn vn tc c gi tr m $v = -v$.",
    "Da vo cc cng thc (5.1) v (5.2) ta c th xc nh c qung ng i c,  dch chuyn, tc  v vn tc ca chuyn ng.",
    "",
    "**? Cu hi:**",
    "Hy tnh qung ng i c,  dch chuyn, tc , vn tc ca bn A khi i t nh n trng v khi i t trng n siu th (Hnh 7.1). Coi chuyn ng ca bn A l chuyn ng u v bit c 100 m bn A i ht 25 s.",
    "[Hnh 7.1. Trc ta  Ox vi gc ti Nh (0m), Siu th (800m) v Trng hc (1000m)]",
    "",
    "34",
    "CHNG II  NG HC",
    "",
    "## II.  TH  DCH CHUYN  THI GIAN TRONG CHUYN NG THNG",
    " th  dch chuyn  thi gian ca mt chuyn ng khng nhng cho php m t c chuyn ng, m cn c th cho bit nhiu thng tin khc na v chuyn ng.",
    "",
    "**1. Cch v  th  dch chuyn  thi gian (d  t) trong chuyn ng thng u**",
    " th n gin nht l  th  dch chuyn  thi gian ca chuyn ng thng u. Trong chuyn ng thng u th $d = v.t$ (vi v l mt hng s). Biu thc $d = v.t$ c dng ging biu thc ca hm s $y = a.x$  hc trong mn Ton nn c ng biu din l mt on thng.",
    "",
    "**Hot ng:** Hy v  th  dch chuyn  thi gian trong chuyn ng ca bn A nu  trn theo trnh t sau y:",
    "1. V bng ghi s liu vo v.",
    "|  dch chuyn (m) | 0 | 200 | 400 | 600 | 800 | 1000 | 800 |",
    "|---|---|---|---|---|---|---|---|",
    "| Thi gian (s) | 0 | 50 | 100 | 150 | 200 | 250 | 300 |",
    "2. V  th: trn trc tung (trc  dch chuyn) 1 cm ng vi 200 m; trn trc honh (trc thi gian) 1 cm ng vi 50 s.",
    "",
    "**2. S dng  th  dch chuyn  thi gian trong chuyn ng thng**",
    "**Hot ng:** Hnh 7.2 l  th  dch chuyn  thi gian ca mt ngi ang bi trong mt b bi di 50 m.  th ny cho bit nhng g v chuyn ng ca ngi ?",
    "1. Trong 25 giy u mi giy ngi  bi c bao nhiu mt? Tnh vn tc ca ngi  ra m/s.",
    "2. T giy no n giy no ngi  khng bi?",
    "3. T giy 35 n giy 60 ngi  bi theo chiu no?",
    "4. Trong 20 giy cui cng, mi giy ngi  bi c bao nhiu mt? Tnh vn tc ca ngi  ra m/s.",
    "5. Xc nh  dch chuyn v vn tc ca ngi  khi bi t B n C.",
    "6. Xc nh  dch chuyn v vn tc ca ngi  trong c qu trnh bi.",
    "",
    "[Hnh 7.2.  th d-t ca ngi bi. Gc O(0,0), ln A(25, 50), ngang n B(35, 50), xung C(60, 20)]",
    "",
    "**EM C BIT?**",
    "1.  th ca cc hm s  hc trong mn Ton:",
    "[Hnh 7.3a:  th hm s y = a.x (a > 0)]",
    "[Hnh 7.3b:  th hm s y = a.x + b (a < 0; b > 0)]",
    "2. Khi vt chuyn ng thng vi vn tc khng i $v > 0$ th $d = v.t$. Phng trnh ny c dng ca hm s $y = a.x$ nn c  th  Hnh 7.3a.",
    "3. Khi vt ang chuyn ng thng, theo chiu dng, nu i chiu chuyn ng th trong khong thi gian chuyn ng ngc chiu , qung ng i c vn c gi tr dng cn  dch chuyn c gi tr m.  th  dch chuyn  thi gian c dng nh Hnh 7.3b.",
    "",
    "**? Cu hi:**",
    "Hy xc nh vn tc v tc  ca ngi bi t giy 45 n giy 60 bng  th  Hnh 7.2.",
    "",
    "35",
    "CHNG II  NG HC",
    "",
    "## III. VN TC V  TH  DCH CHUYN  THI GIAN TRONG CHUYN NG THNG",
    "T  th  dch chuyn  thi gian c th d dng tnh c gi tr ca vn tc.",
    "Trong  th v  Hnh 7.2, h s gc ( dc) ca ng biu din OA l:",
    "$\\frac{\\Delta d}{\\Delta t} = \\frac{50 - 20}{25 - 10} = \\frac{30}{15} = 2$ m/s",
    "y chnh l  ln vn tc ca ngi bi trong 50 m u.",
    " dc ca  th  dch chuyn  thi gian trong chuyn ng thng cho bit  ln vn tc chuyn ng.",
    "",
    "**Hot ng: Vn dng**",
    "1. S liu v  dch chuyn v thi gian ca chuyn ng thng ca mt xe  t  chi chy bng pin c ghi trong bng bn:",
    "|  dch chuyn (m) | 1 | 3 | 5 | 7 | 7 | 7 |",
    "|---|---|---|---|---|---|---|",
    "| Thi gian (s) | 0 | 1 | 2 | 3 | 4 | 5 |",
    "Da vo bng ny :",
    "a) V  th  dch chuyn  thi gian ca chuyn ng.",
    "b) M t chuyn ng ca xe.",
    "c) Tnh vn tc ca xe trong 3 s u.",
    "2.  th  dch chuyn  thi gian trong chuyn ng thng ca mt xe  t  chi iu khin t xa c v  Hnh 7.4.",
    "[Hnh 7.4.  th d-t. Gc(0,0), ln im(2, 4), ngang n im(4, 4), xung im(9, -1), ngang n im(10, -1)]",
    "a) M t chuyn ng ca xe.",
    "b) Xc nh v tr ca xe so vi im xut pht ca xe  giy th 2, giy th 4, giy th 8 v giy th 10.",
    "c) Xc nh tc  v vn tc ca xe trong 2 giy u, t giy 2 n giy 4 v t giy 4 n giy 8.",
    "d) Xc nh qung ng i c v  dch chuyn ca xe sau 10 giy chuyn ng. Ti sao gi tr ca chng khng ging nhau?",
    "",
    "**EM  HC**",
    "- Dng  th  dch chuyn  thi gian ca chuyn ng thng c th m t c chuyn ng: bit khi no vt chuyn ng, khi no vt dng, khi no vt chuyn ng nhanh, khi no vt chuyn ng chm, khi no vt i chiu chuyn ng,...",
    "- Vn tc c gi tr bng h s gc ( dc) ca ng biu din trong  th  dch chuyn  thi gian ca chuyn ng thng.",
    "",
    "**EM C TH**",
    "1. V c  th  dch chuyn  thi gian ca chuyn ng thng.",
    "2. Da vo  th  dch chuyn  thi gian, xc nh c v tr v vn tc ca vt  bt k thi im no.",
    "",
    "36"
  ]
}
