INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B8', 'Bài 8. Chuyển động biến đổi. Gia tốc', 38, 5, $JSON$
{
  "content": [
    "# Bi 8 CHUYN NG BIN I. GIA TC",
    "",
    "**Khi ng:**",
    "Hnh di l nh chp hot nghim th nghim v s thay i vn tc ca mt  t  chi chy bng pin c gn anten dng  iu khin t xa, trong ba giai on chuyn ng. Vn tc trong ba giai on chuyn ng ny c g ging nhau, khc nhau?",
    "[Hnh nh 3 giai on chuyn ng a), b), c) ca mt chic  t  chi. Mi nh c cc v tr ca  t  chi theo thi gian, cho thy khong cch gia cc v tr trong (a) xa dn, (b) u nhau, (c) gn dn]",
    "",
    "## I. CHUYN NG BIN I",
    "Mt  t ang ng yn, bt u chuyn ng s chuyn ng nhanh dn (vn tc tng dn); khi ang chuyn ng mun dng li s phi chuyn ng chm dn (vn tc gim dn).",
    "Chuyn ng c vn tc thay i c gi l chuyn ng bin i.",
    "",
    "**? Cu hi:**",
    "Hy tm thm v d v chuyn ng bin i trong cuc sng.",
    "",
    "## II. GIA TC CA CHUYN NG BIN I",
    "**1. Khi nim gia tc**",
    " xc nh c s thay i vn tc theo thi gian, phi bit vn tc tc thi ca chuyn ng ti cc thi im khc nhau. Cc phng tin giao thng nh xe my,  t c trang b tc k l thit b o trc tip vn tc tc thi. Do  c th dng tc k trn xe my hoc  t  tm hiu s thay i vn tc ca chuyn ng bin i.",
    "Bng di y ghi vn tc tc thi o bi tc k ca mt  t sau cc khong thi gian 2 s k t khi bt u chy trn mt ng thng.",
    "",
    "**Bng 8.1.** Bng ghi s liu vn tc tc thi ca mt chuyn ng",
    "| Thi im t (s) | 0 | 2 | 4 | 6 | 8 |",
    "|---|---|---|---|---|---|",
    "| Vn tc tc thi $v_t$ | (km/h) | 0 | 9 | 19 | 30 | 45 |",
    "| | (m/s) | 0 | 2,50 | 5,28 | 8,33 | 12,50 |",
    "Bng trn cho thy vn tc ca  t tng dn theo thi gian:  t chuyn ng nhanh dn.",
    "",
    "**EM C BIT?**",
    "1. Thut ng gia tc c ngha l tng thm tc . Tuy nhin trong vt l, gia tc khng ch c dng  m t s tng vn tc m cn dng  m t s gim vn tc.",
    "2. Trong cc bi sau, chng ta s thy gia tc khng nhng dng  m t s thay i v  ln ca vn tc m cn dng  m t c s thay i hng ca vn tc.",
    "3. Gia tc xc nh bng cng thc $a = \\frac{\\Delta v}{\\Delta t}$ c gi l gia tc trung bnh.",
    "Nu $\\Delta t$ rt nh th c th coi gia tc ny l gia tc tc thi.",
    "",
    "37",
    "CHNG II  NG HC",
    "",
    "**? Cu hi:**",
    "1. Xc nh  bin thin vn tc sau 8 s ca chuyn ng trn.",
    "2. Xc nh  bin thin vn tc sau mi giy ca chuyn ng trn trong 4 s u v trong 4 s cui.",
    "3. Cc i lng xc nh c  cu 2 cho ta bit iu g v s thay i vn tc ca chuyn ng trn?",
    "",
    "Nu trong thi gian $\\Delta t$,  bin thin vn tc l $\\Delta v$ th  bin thin ca vn tc trong mt n v thi gian l:",
    "$a = \\frac{\\Delta v}{\\Delta t} = \\frac{v_t - v_0}{t - t_0}$ (1)",
    "i lng a cho bit s thay i nhanh hay chm ca vn tc c gi l gia tc ca chuyn ng (gi tt l gia tc).",
    "Nu $\\Delta v$ c n v l m/s (m.s$^{-1}$), $\\Delta t$ c n v l giy (s), th gia tc c n v l m/s$^2$ (m.s$^{-2}$).",
    "V $\\Delta\\vec{v}$ l i lng vect, nn gia tc $\\vec{a}$ cng l i lng vect:",
    "$\\vec{a} = \\frac{\\Delta\\vec{v}}{\\Delta t}$ (2)",
    "",
    "**? Cu hi:**",
    "Hy chng t khi $\\vec{a}$ cng chiu vi $\\vec{v}$ (a.v > 0) th chuyn ng l nhanh dn, khi $\\vec{a}$ ngc chiu vi $\\vec{v}$ (a.v < 0) th chuyn ng l chm dn.",
    "",
    "**2. Bi tp v d**",
    "Mt xe my ang chuyn ng thng vi vn tc 10 m/s th tng tc. Bit rng sau 5 s k t khi tng tc, xe t vn tc 12 m/s.",
    "a) Tnh gia tc ca xe.",
    "b) Nu sau khi t vn tc 12 m/s, xe chuyn ng chm dn vi gia tc c  ln bng gia tc trn th sau bao lu xe s dng li?",
    "",
    "*Gii*",
    "a) $v_0$ = 10 m/s",
    "$v$ = 12 m/s",
    "$\\Delta t$ = 5 s",
    "---",
    "a?",
    "$a = \\frac{\\Delta v}{\\Delta t} = \\frac{12 - 10}{5} = 0,4$ m/s$^2$",
    "Gia tc ca xe a = 0,4 m/s$^2$",
    "",
    "b) $v_0'$ = 12 m/s",
    "$v'$ = 0",
    "$a$ = - 0,4 m/s$^2$",
    "---",
    "$\\Delta t$?",
    "$\\Delta t' = \\frac{\\Delta v'}{a} = \\frac{0 - 12}{-0,4} = 30$ s",
    "Xe dng li sau 30 s.",
    "",
    "38",
    "CHNG II  NG HC",
    "",
    "**? Cu hi:**",
    "1. a) Tnh gia tc ca  t trn 4 on ng trong Hnh 8.1.",
    "b) Gia tc ca  t trn on ng 4 c g c bit so vi s thay i vn tc trn cc on ng khc?",
    "[Hnh 8.1. Cc  t trn 4 on ng. $t_0 = 0$, $t_1 = 1s$ (v = 5 km/h), $t_2 = 4s$ (v = 29 km/h), $t_3 = 6s$ (v = 49 km/h), $t_4 = 7s$ (v = 30 km/h)]",
    "2. Mt con bo ang chy vi vn tc 30 m/s th chuyn ng chm dn khi ti gn mt con sui. Trong 3 giy, vn tc ca n gim cn 9 m/s. Tnh gia tc ca con bo.",
    "3.  th  Hnh 8.2 m t s thay i vn tc theo thi gian trong chuyn ng ca mt  t th thao ang chy th v pha Bc.",
    "Tnh gia tc ca  t:",
    "a) Trong 4 s u.",
    "b) T giy th 4 n giy th 12.",
    "c) T giy th 12 n giy th 20.",
    "d) T giy th 20 n giy th 28.",
    "[Hnh 8.2.  th v-t. Gc (0,0), ln im(4, 20), ngang n im(12, 20), xung im(20, 0), xung im(28, -20)]",
    "",
    "**EM  HC**",
    "- Gia tc l i lng cho bit s thay i nhanh chm ca s thay i vn tc: $\\vec{a} = \\frac{\\Delta \\vec{v}}{\\Delta t}$.",
    "- Khi $\\vec{a}$ cng chiu vi $\\vec{v}$ (a.v > 0): chuyn ng nhanh dn; khi $\\vec{a}$ ngc chiu vi $\\vec{v}$ (a.v < 0): chuyn ng chm dn.",
    "- n v ca gia tc trong h SI l m/s$^2$ (m.s$^{-2}$).",
    "",
    "**EM C TH**",
    "Dng khi nim gia tc  gii thch mt s hin tng v chuyn ng di tc dng ca lc. V d nh chuyn ng ri ca mt vt l chuyn ng c gia tc v vt ri chu tc dng ca lc ht ca Tri t.",
    "",
    "39"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B9', 'Bài 9. Chuyển động thẳng biến đổi đều', 41, 6, $JSON$
{
  "content": [
    "# Bi 9 CHUYN NG THNG BIN I U",
    "",
    "**Khi ng:**",
    "[Hnh nh m t s thay i v tr v vn tc ca  t v ngi.",
    "a)  t: t=0s, v=0km/h; t=1s, v=10km/h; t=2s, v=20km/h; t=3s, v=30km/h",
    "b) Ngi: t=0s, v=6m/s; t=1s, v=4m/s; t=2s, v=2m/s; t=3s, v=0m/s]",
    "Hnh trn m t s thay i v tr v vn tc ca  t, ngi sau nhng khong thi gian bng nhau. Hai chuyn ng ny c g ging nhau, khc nhau?",
    "",
    "## I. GIA TC CA CHUYN NG THNG BIN I U",
    "Chuyn ng thng bin i u l chuyn ng thng m vn tc c  ln tng hoc gim u theo thi gian.",
    "Chuyn ng thng c  ln vn tc tng u theo thi gian gi l chuyn ng thng nhanh dn u; chuyn ng thng c  ln vn tc gim u theo thi gian gi l chuyn ng thng chm dn u.",
    "V chuyn ng thng bin i u c vn tc thay i u theo thi gian nn gia tc ca chuyn ng ny khng i theo thi gian:",
    "$a = \\frac{\\Delta v}{\\Delta t} = \\text{hng s}$ (9.1)",
    "",
    "**? Cu hi:**",
    "1. Tnh gia tc ca cc chuyn ng trong hnh v  u bi.",
    "2. Cc chuyn ng trong hnh v  u bi c phi l chuyn ng thng bin i u khng?",
    "",
    "## II. VN TC TC THI CA CHUYN NG THNG BIN I U",
    "Gi $v_0$ l vn tc ti thi im ban u $t_0$, $v_t$ l vn tc ti thi im t.",
    "V $a = \\frac{\\Delta v}{\\Delta t} = \\frac{v_t - v_0}{t - t_0} = \\frac{v_t - v_0}{\\Delta t}$ nn $v_t = v_0 + a.\\Delta t$.",
    "Nu  thi im ban u $t_0 = 0$ th:",
    "$v_t = v_0 + a.t$ (9.2)",
    "Nu  thi im ban u $t_0 = 0$ vt mi bt u chuyn ng th:",
    "$v_0 = 0$ v $v_t = a.t$ (9.3)",
    "",
    "40",
    "CHNG II  NG HC",
    "",
    "## III.  TH VN TC  THI GIAN CA CHUYN NG THNG BIN I U",
    "Cc cng thc (9.2) v (9.3) cho thy vn tc tc thi v trong chuyn ng thng bin i u l hm bc nht ca thi gian t, nn  th vn tc  thi gian ca chuyn ng ny c cc dng nh Hnh 9.1.",
    "[Hnh 9.1. Cc dng  th vn tc - thi gian.",
    "a)  th i qua gc to , i ln.",
    "b)  th ct trc tung ti $v_0 > 0$, i ln.",
    "c)  th ct trc tung ti $v_0 > 0$, i xung.]",
    "*Hnh 9.1. Cc dng  th vn tc - thi gian trong chuyn ng thng bin i u*",
    "",
    "**? Cu hi:**",
    "1. T cc  th trong Hnh 9.1:",
    "a) Hy vit cng thc v mi lin h gia v vi a v t ca tng chuyn ng ng vi tng  th trong Hnh 9.1.",
    "b) Chuyn ng no l chuyn ng nhanh dn u, chm dn u?",
    "2. Hnh 9.2 l  th vn tc  thi gian trong chuyn ng ca mt bn ang i trong siu th. Hy da vo  th  m t bng li chuyn ng ca bn  (khi no i u, i nhanh ln, i chm li, ngh).",
    "[Hnh 9.2.  th v-t. i ngang t t=0 n t=4 (v=1), t t=4 n t=6 tc  gim xung v=0, t t=6 n t=8 vn tc v=0, t t=8 n t=10 vn tc gim xung v=-0,5]",
    "",
    "## IV.  DCH CHUYN CA CHUYN NG THNG BIN I U",
    "**1. Tnh  dch chuyn bng  th vn tc  thi gian (v  t)**",
    "- Trong khong thi gian t, nu vt chuyn ng thng u vi vn tc v, th  th (v  t) c dng nh Hnh 9.3a v  dch chuyn trong thi gian ny c  ln l: $d = v.t$.",
    " ln ny bng din tch ca hnh ch nht, cc cnh c  di l v v t. Din tch ny gi l din tch gii hn ca  th (v  t) i vi trc honh.",
    "[Hnh 9.3a.  th v-t ca chuyn ng thng u, v=3, t t 0 n 5. Din tch hnh ch nht l 3x5=15]",
    "a)  th (v  t) ca chuyn ng thng u:",
    "Din tch  th: S = 3.5 = 15",
    " dch chuyn d = 15 m",
    "",
    "- Trong thi gian t, nu vt chuyn ng thng bin i u vi vn tc ban u $v_0$, th cng thc tnh vn tc l $v_t = v_0 + a.t$,  th (v  t) c dng nh Hnh 9.3b. C th da vo  th ny  tnh  dch chuyn.",
    "K cc ng song song vi trc tung Ov, cch nhau mt khong $\\Delta t$ rt nh  chia  th thnh cc hnh thang nh c ng cao $\\Delta t$.",
    "Chn mt hnh thang nh bt k trong hnh. V vt chuyn ng thng bin i u nn trong khong thi gian nh t $t_A$ n $t_B$, c th coi chuyn ng ca vt l thng u vi vn tc $v_C = \\frac{v_A + v_B}{2}$ (C nm gia A v B).",
    " dch chuyn ca vt trong thi gian $\\Delta t$ c  ln bng din tch hnh ch nht c cnh l $v_C$ v $\\Delta t$.",
    "[Hnh 9.3b.  th v-t ca chuyn ng thng bin i u. Hm bc nht v(t). C chia thnh nhiu di nh, xt di t $t_A$ n $t_B$]",
    "b)  th (v  t) ca chuyn ng thng bin i u.",
    "*Hnh 9.3*",
    "",
    "41",
    "CHNG II  NG HC",
    "",
    "Hnh v cho thy din tch ca hnh ny bng din tch ca hnh thang nh gch cho trong hnh c ng cao $\\Delta t$ v cc y c  di $v_A, v_B$.  dch chuyn trong thi gian t, bng tng cc  dch chuyn trong cc khong thi gian $\\Delta t$, nn c  ln bng din tch ca hnh thang vung c ng cao l t v cc y c  ln $v_0, v$.",
    "",
    "**? Cu hi:**",
    "1. Hy tnh  dch chuyn ca chuyn ng c  th (v  t) v  Hnh 9.3b. Bit mi cnh ca  vung nh trn trc tung ng vi 2 m/s, trn trc honh ng vi 1 s.",
    "2. Chng t rng c th xc nh c gi tr ca gia tc da trn  th (v  t).",
    "",
    "**2. Tnh  dch chuyn bng cng thc**",
    "**? Cu hi:**",
    "1. Bit  dch chuyn trong chuyn ng thng bin i u c  ln bng din tch gii hn  th (v  t) trong thi gian t ca chuyn ng. Hy chng minh rng cng thc tnh  ln ca  dch chuyn trong chuyn ng thng bin i u l:",
    "$d = v_0.t + \\frac{1}{2}.a.t^2$ (9.4)",
    "2. T cng thc (9.2) v (9.4) chng minh rng:",
    "$v_t^2 - v_0^2 = 2.a.d$ (9.5)",
    "",
    "**? Cu hi:**",
    "Hy dng  th (v  t) v  Hnh 9.4 :",
    "a) M t chuyn ng;",
    "b) Tnh  dch chuyn trong 4 giy u, 2 giy tip theo v 3 giy cui;",
    "c) Tnh gia tc ca chuyn ng trong 4 giy u;",
    "d) Tnh gia tc ca chuyn ng t giy th 4 n giy th 6.",
    "Kim tra kt qu ca cu b v cu c bng cch dng cng thc.",
    "[Hnh 9.4.  th v-t. Trc v(m/s) t 0 n 8, trc t(s) t 0 n 9.  th i t (0, 9) xung (4, 1), sau  i ngang n (6, 1) (im ny thc cht l (5, 0) nu dng k,  khng, n ct trc honh  4.5s? Khng,  th i t v=9 lc t=0 xung v=1 lc t=4? Nhn k th n i t (0, 9) xung n im v=0 ti t=4.5 hoc t=5. Nhng im gy l  t=4, v=1? Khng, n i thng t (0,9) qua cc  n khi ct trc honh. Ch, 4 giy u, 2 giy tip, 3 giy cui. Tng l 4+2+3 = 9s. N ct  t=4 th sao? , n i t v=9, qua (4,1)... Tht ra  th v t v=9, xung im (5, -1)? N ct trc honh  t=4.5]",
    "",
    "42",
    "CHNG II  NG HC",
    "",
    "*Bi tp vn dng*",
    "1.  th vn tc  thi gian  Hnh 9.5 m t chuyn ng ca mt ch ch con ang chy trong mt ng thng v hp.",
    "a) Hy m t chuyn ng ca ch ch.",
    "b) Tnh qung ng i c v  dch chuyn ca ch ch sau: 2 s; 4 s; 7 s v 10 s bng  th v bng cng thc.",
    "[Hnh 9.5.  th v-t. i ngang  v=1 t t=0 n t=2. i ln t v=3  t=5. i xung t v=0  t=7. Xung tip t v=-1  t=8. i ngang  v=-1 t t=8 n t=10]",
    "*Hnh 9.5*",
    "",
    "2. Mt vn ng vin ua xe p ng di vt qua vch ch vi tc  10 m/s. Sau  vn ng vin ny i chm dn u thm 20 m mi dng li. Coi chuyn ng ca vn ng vin l thng.",
    "a) Tnh gia tc ca vn ng vin trong on ng sau khi qua vch ch.",
    "b) Tnh thi gian vn ng vin  cn  dng li k t khi cn ch.",
    "c) Tnh vn tc trung bnh ca ngi  trn qung ng dng xe.",
    "",
    "**EM  HC**",
    "- Chuyn ng thng bin i u l chuyn ng thng c gia tc khng i theo thi gian.",
    "- Chuyn ng thng nhanh dn u c (a.v) > 0, chuyn ng thng chm dn u c (a.v) < 0.",
    "- H s gc ca  th vn tc  thi gian ca chuyn ng thng bin i u cho bit gi tr ca gia tc.",
    "- Cc cng thc ca chuyn ng thng bin i u:",
    "1. $v_t = v_0 + a.t$",
    "2. $d = v_0.t + \\frac{1}{2}.a.t^2$",
    "3. $v_t^2 - v_0^2 = 2.a.d$",
    "",
    "**EM C TH**",
    "T  th vn tc  thi gian ca chuyn ng thng bin i u m t c chuyn ng ny.",
    "",
    "43"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B10', 'Bài 10. Sự rơi tự do', 45, 7, $JSON$
{
  "content": [
    "# Bi 10 S RI T DO",
    "",
    "**Khi ng:**",
    "*Nm 1971, nh du hnh v tr ngi M David Scott  ng thi th ri trn Mt Trng mt chic lng chim v mt chic ba  cng mt  cao v nhn thy c hai u ri xung nh nhau. Em c suy ngh g v hin tng ny?*",
    "[Hnh nh phi hnh gia ang th ba v lng chim trn Mt Trng]",
    "",
    "## I. S RI TRONG KHNG KH",
    "S ri ca cc vt trong khng kh l chuyn ng thng gp. Ai cng thy hn  ri nhanh hn vin phn, vin phn ri nhanh hn chic lng chim. Nhiu ngi d on rng, ri nhanh hay chm l do vt nng hay nh. Em c ng  vi d on  khng? Em c d on no v nguyn nhn lm cho cc vt ri nhanh chm khc nhau khng?",
    "",
    "**Hot ng:** Cc th nghim (TN) sau y s gip chng ta kim tra d on ca mnh v s ri ca cc vt t cng  cao trong khng kh.",
    "TN 1: Th ri mt vin bi v mt chic l.",
    "TN 2: Th hai t giy ging nhau, nhng mt t c vo trn, mt t  nguyn.",
    "TN 3: Th ri hai vin bi c cng kch thc, mt bng st v mt bng thu tinh.",
    "T nhng th nghim trn, rt ra nhn xt v s ri trong khng kh.",
    "",
    "**? Cu hi:**",
    "1. Trong TN 1, ti sao qu bng ri nhanh hn chic l?",
    "2. Trong TN 2, hai t giy ging nhau, nng nh nhau, ti sao t giy vo trn li ri nhanh hn?",
    "3. Trong TN 3, trng lng bi st ln hn bi thu tinh, ti sao hai vin bi ri nhanh nh nhau?",
    "",
    "Cc th nghim trn cho thy s ri nhanh hay chm ca vt ph thuc vo  ln ca lc cn khng kh tc dng ln vt. Lc cn cng nh so vi trng lc tc dng ln vt th vt s ri cng nhanh v ngc li.",
    "",
    "**? Cu hi:**",
    "Theo em nu loi b c sc cn ca khng kh, cc vt s ri nh th no?",
    "",
    "Cu hi ny  c nh bc hc Newton tr li bng kt qu th nghim vi cc ng ht chn khng (Hnh 10.1): Hai vt ri l vin bi ch v chic lng chim. Kt qu cho thy trong chn khng mi vt ri nhanh nh nhau.",
    "[Hnh 10.1. Th nghim v s ri t do. a) Trong ng c khng kh: bi ch ri nhanh hn. b) Trong ng khng c khng kh: bi ch v lng chim ri nh nhau]",
    "",
    "44",
    "CHNG II  NG HC",
    "",
    "## II. S RI T DO",
    "**1. S ri t do**",
    "S ri t do l s ri ch di tc dng ca trng lc.",
    "Nu vt ri trong khng kh m  ln ca lc cn khng kh khng ng k so vi trng lng ca vt th cng coi l ri t do.",
    "",
    "**2. c im ca chuyn ng ri t do**",
    "**a) Phng v chiu ca chuyn ng ri t do**",
    "V trng lc c phng thng ng, chiu t trn xung nn c th d on s ri ch di tc dng ca trng lc cng c phng thng ng, chiu t trn xung.",
    "",
    "**Hot ng:**",
    "1. Hy thc hin th nghim (Hnh 10.2)  kim tra d on v phng v chiu ca s ri t do.",
    "2. Da vo c im v phng ca s ri t do, hy tm cch kim tra b mt ca bc tng trong lp hc c phi l mt phng thng ng khng.",
    "3. Hy ngh cch dng ke tam gic vung cn v dy di  kim tra xem sn lp mnh c phng hay khng.",
    "[Hnh 10.3. ke tam gic vung cn]",
    "[Hnh 10.2. Th nghim kim tra phng thng ng bng dy di v qu nng th ri t do]",
    "",
    "**b) Tnh cht ca chuyn ng ri t do**",
    "Quan st s ri t do ta thy  l chuyn ng thng nhanh dn. Tuy nhin,  bit s ri t do c phi l chuyn ng thng nhanh dn u hay khng th phi da vo th nghim. V vt ri t do rt nhanh nn ngi ta thng dng phng php chp nh hot nghim (dng my nh c bit chp lin tip vt chuyn ng sau nhng khong thi gian bng nhau)  c th o qung ng ri c sau nhng khong thi gian bng nhau.",
    "Bng 10.1 ghi kt qu chp nh hot nghim trong phng th nghim ca mt trng ph thng v s ri ca mt hn bi thp sau nhng khong thi gian 0,1 s.",
    "",
    "**? Cu hi:**",
    "Hy cn c vo s liu trong Bng 10.1 :",
    "1. Chng t chuyn ng ri t do l nhanh dn u.",
    "2. Tnh gia tc ca chuyn ng ri t do.",
    "",
    "**? Cu hi:**",
    "Trong cc chuyn ng sau, chuyn ng no c coi l ri t do? Ti sao?",
    "A. Chic l ang ri.",
    "B. Ht bi chuyn ng trong khng kh.",
    "C. Qu t ri trong khng kh.",
    "D. Vn ng vin ang nhy d.",
    "",
    "Trong bi chuyn ng bin i u ta  bit:",
    "Mt vt chuyn ng thng nhanh dn u khng vn tc ban u th qung ng i c s t l vi bnh phng thi gian t:",
    "$s = \\frac{1}{2}.a.t^2$",
    "",
    "**Bng 10.1.** Qung ng vt ri t do theo thi gian t kt qu chp nh hot nghim",
    "| Thi gian ri (s) | Qung ng ri (m) |",
    "|---|---|",
    "| 0,1 | 0,049 |",
    "| 0,2 | 0,197 |",
    "| 0,3 | 0,441 |",
    "| 0,4 | 0,785 |",
    "| 0,5 | 1,227 |",
    "",
    "45",
    "CHNG II  NG HC",
    "",
    "**c) Gia tc ri t do**",
    " cng mt ni trn Tri t, mi vt ri t do vi cng mt gia tc.",
    "Gia tc ri t do k hiu l g, gi tr ca g ph thuc vo v  a l v  cao.  gn b mt Tri t ngi ta thng ly gi tr ca g bng 9,8 m/s$^2$.",
    "",
    "**3. Cng thc ri t do**",
    "Ri t do c cc cng thc ca chuyn ng nhanh dn u khng vn tc ban u. Chn thi im ban u $t_0 = 0$.",
    " dch chuyn, qung ng i c ti thi im t:",
    "$d = s = \\frac{1}{2}.g.t^2$",
    "Vn tc tc thi ti thi im t: $v_t = g.t$.",
    "Lin h gia vn tc v qung ng i c vi gia tc: $v_t^2 = 2.g.s$.",
    "",
    "*Bi tp vn dng:* Mt ngi th mt hn bi t trn cao xung t v o c thi gian ri l 3,1 s. B qua sc cn khng kh. Ly g = 9,8 m/s$^2$.",
    "a) Tnh  cao ca ni th hn bi so vi mt t v vn tc lc chm t.",
    "b) Tnh qung ng ri c trong 0,5 s cui trc khi chm t.",
    "",
    "**? Cu hi:**",
    "1. Ti sao  dch chuyn v qung ng i c trong s ri t do c cng  ln?",
    "2. Hy nu cch o gn ng  su ca mt ci ging m cn. Coi vn tc truyn m trong khng kh l khng i v  bit.",
    "",
    "**EM  HC**",
    "- Chuyn ng ri ch chu tc dng ca trng lc gi l ri t do.",
    "- Chuyn ng ri t do l chuyn ng thng nhanh dn u theo phng thng ng, chiu t trn xung.",
    "- Ti mt ni nht nh trn Tri t v  gn mt t, mi vt u ri t do vi cng gia tc g. Gia tc ri t do  cc ni khc nhau trn Tri t th khc nhau.",
    "- Cc cng thc ca s ri t do:",
    "Gia tc a = g = hng s.",
    "Vn tc tc thi: $v_t = g.t$.",
    " ln ca  dch chuyn = Qung ng i c: $d = s = \\frac{1}{2}.g.t^2 = \\frac{v_t^2}{2.g}$.",
    "",
    "**EM C TH**",
    "- Vn dng c nhng kin thc v s ri t do vo mt s tnh hung thc t n gin.",
    "- Bit cch xc nh phng thng ng v phng nm ngang.",
    "",
    "46"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B11', 'Bài 11. Thực hành: Đo gia tốc rơi tự do', 48, 8, $JSON$
{
  "content": [
    "# Bi 11 THC HNH: O GIA TC RI T DO",
    "",
    "**Khi ng:**",
    "*Cc vt ri t do chuyn ng rt nhanh, lm th no o c gia tc ri t do ca vt?*",
    "",
    "## I. DNG C TH NGHIM",
    "- Mng ng, c gn dy di (1).",
    "- Vt bng thp hnh tr (2).",
    "- Nam chm in N, dng gi v th tr thp (3).",
    "- Cng quang in E (4).",
    "- Gi  c  ba chn, c vt chnh cn bng v tr thp (5).",
    "- ng h o thi gian hin s (6).",
    "- Cng tc kp (7).",
    "",
    "[Hnh 11.1. B dng c th nghim o gia tc ri t do, nh s t 1 n 7 cc b phn tng ng]",
    "",
    "## II. THIT K PHNG N TH NGHIM",
    "**Hot ng:** Tho lun v phng n th nghim da trn hot ng sau: Th tr thp ri qua cng quang in trn mng ng v tr li cu hi.",
    "1. Xc nh gia tc ri t do ca tr thp theo cng thc no?",
    "2.  xc nh gia tc ri t do ca tr thp cn o cc i lng no?",
    "3. Lm th no  tr thp ri qua cng quang in?",
    "4. Cn t ch  o ca ng h  v tr no  o c i lng cn o?",
    "",
    "## III. TIN HNH TH NGHIM",
    "1. Cm nam chm in vo  A v cng quang vo  B  mt sau ca ng h o thi gian hin s. (xem Hnh 6.2)",
    "2. t MODE ng h o thi gian hin s  ch  thch hp.",
    "3. t tr thp ti v tr tip xc vi nam chm in N v b gi li  .",
    "4. Nhn nt RESET ca ng h MC964  chuyn cc s hin th v gi tr ban u 0.000.",
    "5. Nhn nt ca hp cng tc kp  ngt in vo nam chm in: Tr thp ri xung v chuyn ng i qua cng quang in.",
    "6. Ghi li cc gi tr thi gian hin th trn ng h vo Bng 11.1.",
    "7. Dch chuyn cng quang in ra xa dn nam chm in, thc hin li cc thao tc 3, 4, 5, 6 bn ln na. Ghi cc gi tr thi gian t tng ng vi qung ng s vo Bng 11.1 trong bo co thc hnh.",
    "",
    "**! Ch :**  th ri tr thp theo mng ng c th thc hin nh sau:",
    "- t mng ng ln gi . Vn cht vt hm.",
    "- Ni cng tc in vi nam chm in v ni cng tc vo  cm A, ni cng quang in  cm B  mt sau ca ng h o thi gian.",
    "- Cm ngun in ca ng h v bt cng tc ngun. t tr thp ti v tr tip xc vi nam chm in N v b gi li  .",
    "- Nhn nt ca hp cng tc kp  ngt in vo nam chm in.",
    "",
    "47",
    "CHNG II  NG HC",
    "",
    "## IV. KT QU TH NGHIM",
    "**Bng 11.1**",
    "| Qung ng | Ln o thi gian |",
    "|---|---|---|---|---|---|",
    "| | Ln 1 | Ln 2 | Ln 3 | Ln 4 | Ln 5 |",
    "| $s_1$ | | | | | |",
    "| $s_2$ | | | | | |",
    "| $s_3$ | | | | | |",
    "| $s_4$ | | | | | |",
    "| $s_5$ | | | | | |",
    "$\\overline{g} = ...$; $\\Delta g = ...$; $g = ...$",
    "",
    "**Hot ng:** Nhn xt v nh gi kt qu th nghim",
    "1. Hy tnh gi tr trung bnh v sai s tuyt i ca php o gia tc ri t do.",
    "2. Ti sao li dng tr thp lm vt ri trong th nghim? C th dng vin bi thp c khng? Gii thch ti sao.",
    "3. V  th m t mi quan h s v $t^2$ trn h to  (s  $t^2$).",
    "4. Nhn xt chung v dng ca  th m t mi quan h s v $t^2$ ri rt ra kt lun v tnh cht ca chuyn ng ri t do.",
    "5. Hy  xut mt phng n th nghim khc  o gia tc ri t do ca tr thp.",
    "",
    "**EM  HC**",
    "- Ri t do l chuyn ng thng nhanh dn u nn c th xc nh gia tc ri t do theo cng thc xc nh gia tc ca chuyn ng nhanh dn u.",
    "- S dng ng h o thi gian hin s v cng quang o gia tc ri t do ca vin bi thp hoc tr thp.",
    "",
    "**EM C TH**",
    "S dng camera ca in thoi thng minh v phn mm phn tch video  xc nh c gia tc ri t do ca vt (Hnh 11.2).",
    "[Hnh 11.2. B tr o gia tc ri t do bng camera ca in thoi thng minh. C thc o, vt mu  ang ri, in thoi ghi hnh,  th phn tch]",
    "",
    "**EM C BIT?**",
    "Vo nm 1602, Galilei pht hin ra chuyn ng ca con lc v khong thi gian mt chu k t l vi cn bc hai chiu di con lc. Nh pht hin ny c th o gia tc ri t do bng con lc n.",
    "",
    "48"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B12', 'Bài 12. Chuyển động ném', 50, 9, $JSON$
{
  "content": [
    "# Bi 12 CHUYN NG NM",
    "",
    "**Khi ng:**",
    "*Nhy xa l mt v d v chuyn ng nm. Theo em, trong vic nhy xa th nhng yu t no c tnh quyt nh n thnh tch nhy ca vn ng vin?*",
    "[Hnh nh m phng cc t th ca mt vn ng vin nhy xa t lc gim nhy n lc tip t, to thnh mt qu o hnh parabol]",
    "",
    "## I. CHUYN NG NM NGANG",
    "**1. Khi nim chuyn ng nm ngang**",
    "Chuyn ng nm ngang l chuyn ng c vn tc ban u theo phng nm ngang v chuyn ng di tc dng ca trng lc.",
    "",
    "**2. Th nghim**",
    "Th nghim m t  Hnh 12.1 dng  tm hiu chuyn ng ca vt b nm theo phng nm ngang.",
    "Dng ba p nh vo thanh thp gi bi B, thanh thp chuyn ng th bi B ri t do ng thi y bi A theo phng nm ngang khi gi  vi vn tc $v_0$.",
    "[Hnh 12.1. Th nghim v chuyn ng nm ngang. Vt A nm ngang, vt B ri t do, ba p nh 2 vin bi]",
    "",
    "**? Cu hi:**",
    "Hai vin bi c chm t cng mt lc khng?",
    "",
    "Vic phn tch nh chp hot nghim th nghim trn (Hnh 12.2) gip ta so snh chuyn ng ri t do ca bi B (s thay i v tr ca bi B theo phng thng ng) vi vn tc ban u $v_{0y} = 0$ vi s thay i v tr theo phng thng ng ca vin bi A b nm ngang vi vn tc ban u theo phng nm ngang $v_{0x} = v_0$.",
    "[Hnh 12.2. nh chp hot nghim chuyn ng ca hai vin bi A v B. Cho thy v tr theo phng thng ng ca c 2 vin lun ngang nhau ti cng mt thi im]",
    "",
    "**? Cu hi:**",
    "Hy nhn xt v s thay i v tr theo phng thng ng ca hai vin bi sau nhng khong thi gian bng nhau.",
    "",
    "49",
    "CHNG II  NG HC",
    "",
    "**3. Phn tch kt qu th nghim**",
    "i vi chuyn ng nm ngang, ngi ta quan tm ti thi gian t khi vt c nm ti khi vt ri chm t v tm bay xa ca vt theo phng nm ngang.  xc nh cc i lng ny ngi ta phn tch chuyn ng ca vt b nm ngang thnh hai chuyn ng thnh phn: chuyn ng thnh phn theo phng thng ng v chuyn ng thnh phn theo phng nm ngang.",
    "Th nghim trn cho thy thnh phn chuyn ng theo phng thng ng ca vin bi A ging chuyn ng ri ca vin bi B. iu  chng t thnh phn chuyn ng theo phng nm ngang ca vin bi A khng nh hng n thnh phn chuyn ng theo phng thng ng ca n: Hai chuyn ng thnh phn ny c lp vi nhau.",
    "",
    "**a) Thnh phn chuyn ng theo phng thng ng**",
    "Nu b qua sc cn ca khng kh th chuyn ng thnh phn theo phng thng ng ca vt l chuyn ng ri t do vi vn tc ban u bng 0.",
    "Nu chn chiu dng l chiu t trn xung v gi H l  cao ca vt khi b nm ngang th:",
    "$H = \\frac{1}{2}.g.t^2 \\Rightarrow t = \\sqrt{\\frac{2.H}{g}}$ (12.1)",
    "Cng thc (12.1) cho thy:",
    "- Thi gian ri ca vt b nm ngang ch ph thuc  cao H ca vt khi b nm, khng ph thuc vn tc nm.",
    "- Nu t cng mt  cao, ng thi nm ngang cc vt khc nhau vi cc vn tc khc nhau th chng u ri xung t cng mt lc.",
    "",
    "**b) Thnh phn chuyn ng theo phng nm ngang**",
    "Nu chn chiu dng l chiu nm vin bi th  dch chuyn trong chuyn ng thnh phn nm ngang l:",
    "$d_x = v_x.t = v_0.t$.",
    "Gi tr cc i ca  dch chuyn trong chuyn ng thnh phn nm ngang c gi l tm xa L ca chuyn ng nm ngang (Hnh 12.4):",
    "$L = d_{x\\text{ max}} = v_0.t_{\\text{max}}$, vi $t_{\\text{max}}$ l thi gian ri ca vt.",
    "Do : $L = v_0.\\sqrt{\\frac{2.H}{g}}$ (12.2)",
    "Cng thc (12.2) cho thy:",
    "1. Tm xa ca vt b nm ngang ph thuc vo  cao H ca vt khi b nm v vn tc nm. Nu t cng mt  cao ng thi nm cc vt khc nhau vi vn tc khc nhau th vt no c vn tc nm ln hn s c tm xa ln hn.",
    "2. Nu t cc  cao khc nhau nm ngang cc vt vi cng vn tc th vt no c nm   cao ln hn s c tm xa ln hn.",
    "",
    "[Hnh 12.3. Phn tch chuyn ng nm ngang. Qu o ca vt M t O, phn tch thnh d_x theo trc Ox, d_y theo trc Oy]",
    "[Hnh 12.4.  th chuyn ng nm ngang. Qu o parabol t (0,H) trn Oy xung L trn Ox]",
    "",
    "**? Cu hi:**",
    "Hy quan st nh hot nghim  Hnh 12.2  chng t chuyn ng thnh phn theo phng nm ngang l chuyn ng thng u vi vn tc $v_x = v_0$.",
    "",
    "50",
    "CHNG II  NG HC",
    "",
    "**Hot ng:**",
    "1. Hy  xut phng n th nghim  kim tra nhng kt lun 2 v 3.",
    "2. Dng thc k gi ba vin bi (st, thu tinh v g) c cng kch thc, trn mt tm thu tinh t nghing trn mt bn ri nng thc ln (Hnh 12.5). Hy d on tm xa ca ba vin bi v lm th nghim kim tra.",
    "[Hnh 12.5. Th nghim v tm xa]",
    "",
    "*Bi tp v d:* Mt ngi ng t mt i quan st ven bin, nm mt hn  theo phng nm ngang hng ra bin vi vn tc 12 m/s. Bit  cao t v tr nm so vi mt bin l 40 m. B qua sc cn ca khng kh.",
    "a) Sau bao lu th hn  chm mt bin?",
    "b) Tm xa L ca hn  l bao nhiu mt?",
    "*Gii*",
    "$v_{0y} = 0$",
    "$v_{0x} = v = 12$ m/s",
    "H = 40 m",
    "g = 9,8 m/s$^2$",
    "a) t = ?",
    "b) L = ?",
    "",
    "a) $H = d_y = \\frac{1}{2}.g.t^2$",
    "Do : $t = \\sqrt{\\frac{2.H}{g}} = 2,86$ s.",
    "b) $L = d_{x\\text{ max}} = v.t = 34,3$ m.",
    "",
    "**? Cu hi:**",
    "1. Nu ng thi nm hai qu bng ging nhau vi nhng vn tc bng nhau theo phng nm ngang t hai  cao $h_1, h_2$ khc nhau ($h_1 < h_2$) th:",
    "a) Qu bng nm   cao no chm t trc?",
    "b) Qu bng nm   cao no c tm xa ln hn?",
    "2. Mt my bay ch hng ang bay ngang   cao 490 m vi vn tc 100 m/s th th mt gi hng cu tr xung mt lng ang b l lt. Ly g = 9,8 m/s$^2$ v b qua sc cn ca khng kh.",
    "a) Sau bao lu th gi hng chm t?",
    "b) Tm xa ca gi hng l bao nhiu?",
    "c) Xc nh vn tc ca gi hng khi chm t.",
    "",
    "## II. CHUYN NG NM XIN",
    "Khi nh mt qu bng tennis ln cao theo phng xin gc vi phng nm ngang, ngi ta thy qu bng bay ln ri ri xung theo mt qu o c dng hnh parabol (Hnh 12.6). Chuyn ng ca qu bng trong trng hp ny gi l chuyn ng ca vt b nm xin, gi tt l chuyn ng nm xin.",
    "[Hnh 12.6. nh chp hot nghim chuyn ng nm xin. Qu o parabol ca qu bng nm xin ln ri ri xung]",
    "",
    "**? Cu hi:**",
    "Hy tm thm v d v chuyn ng nm xin trong i sng.",
    "",
    "51",
    "CHNG II  NG HC",
    "",
    "**1. Phn tch chuyn ng nm xin**",
    "i vi chuyn ng nm xin, ngi ta cng quan tm n thi gian t khi vt c nm ln ti khi vt ri chm t v tm xa ca vt theo phng nm ngang.  xc nh cc i lng ny ngi ta cng thc hin nh  lm vi chuyn ng nm ngang, phn tch chuyn ng nm xin thnh hai chuyn ng thnh phn: chuyn ng thnh phn theo phng thng ng v chuyn ng thnh phn theo phng nm ngang (Hnh 12.7).",
    "[Hnh 12.7. Phn tch chuyn ng nm xin. H to  Oxy, vn tc $\\vec{v}_0$ hp vi Ox gc $\\alpha$, phn tch thnh $\\vec{v}_{0x}$ v $\\vec{v}_{0y}$]",
    "",
    "**2. Cng thc xc nh tm cao v tm xa ca chuyn ng nm xin**",
    "Bng cch lm tng t nh cch lm i vi chuyn ng nm ngang. B qua sc cn ca khng kh, c th thit lp c cng thc xc nh tm cao v tm xa ca chuyn ng nm xin:",
    "Tm cao: $H = d_{y\\text{ max}} = \\frac{v_0^2.\\sin^2\\alpha}{2.g}$",
    "Tm xa: $L = d_{x\\text{ max}} = \\frac{v_0^2.\\sin 2\\alpha}{g}$",
    "",
    "*Bi tp v d:* Mt ngi nhy xa vi vn tc ban u 7,5 m/s theo phng xin $30^\\circ$ vi phng nm ngang. Bit v tr dm nhy ngang vi h nhy. B qua sc cn ca khng kh v ly g = 9,8 m/s$^2$. Tnh:",
    "a) Vn tc ban u ca ngi nhy theo phng thng ng v theo phng nm ngang.",
    "b) Tm cao H.",
    "c) Thi gian t khi bt u nhy ti khi t tm cao.",
    "d) Thi gian t lc bt u nhy ln ti lc ri xung h nhy.",
    "e) Tm xa L.",
    "[Hnh 12.8. H to  Oxy cho bi tp vn dng. O l v tr trn mt t ngi  t chn]",
    "*Gii*",
    "Chn h to  Oxy vi O l v tr trn mt t m ngi  t chn vo  nhy ln, chiu dng l chiu t di ln (Oy) v chiu t tri sang phi (Ox), gc thi gian l thi im nhy (Hnh 12.8).",
    "a) Vn tc ban u:",
    "$v_{0y} = v_0.\\sin 30^\\circ = 3,75$ m/s (t di ln)",
    "$v_{0x} = v_0.\\cos 30^\\circ = 6,50$ m/s (tri sang phi)",
    "b) Khi t tm cao H th vn tc ca ngi nhy theo phng thng ng bng 0:",
    "$v_y = 0$",
    "$v_{0y} = 3,75$ m/s",
    "$a = - g$",
    "H = ?",
    "$v_y^2 - v_{0y}^2 = 2.a.H = -2.g.H$",
    "$H = \\frac{v_{0y}^2}{2.g} = 0,717$ m",
    "c) Thi gian t lc bt u nhy ti khi t tm cao:",
    "$v_y = v_{0y} - g.t \\Rightarrow t = \\frac{3,75}{9,8} = 0,383$ s",
    "",
    "52",
    "CHNG II  NG HC",
    "",
    "d) Thi gian t lc bt u nhy ln ti lc ri xung h nhy:",
    "$t' = 2.t = 2.0,383 = 0,766$ s",
    "e) Tm xa:",
    "$v_{0x} = 6,5$ m/s",
    "$t' = 0,766$ s",
    "L = ?",
    "$L = d_{x\\text{ max}} = v_{0x}.t' = 4,98$ m.",
    "",
    "**? Cu hi:**",
    "Ngi ta bn mt vin bi vi vn tc ban u 4 m/s hng ln theo phng xin $45^\\circ$ so vi phng nm ngang. Coi sc cn ca khng kh l khng ng k.",
    "1. Tnh vn tc ca vin bi theo phng nm ngang v phng thng ng ti cc thi im: bt u bn, sau 0,1 s v sau 0,2 s.",
    "2. a) Vin bi t tm cao H vo lc no?",
    "b) Tnh tm cao H.",
    "c) Gia tc ca vin bi  tm cao H c gi tr bng bao nhiu?",
    "3. a) Vn tc ca vin bi c  ln cc tiu  v tr no?",
    "b) Vin bi c vn tc cc tiu vo thi im no?",
    "4. a) Khi no vin bi chm sn?",
    "b) Xc nh vn tc ca vin bi khi chm sn.",
    "c) Xc nh tm xa L ca vin bi.",
    "",
    "**EM  HC**",
    "- Chuyn ng nm c th phn tch thnh hai chuyn ng thnh phn vung gc vi nhau: chuyn ng vi gia tc theo phng thng ng, chuyn ng thng u theo phng nm ngang.",
    "- Cc cng thc ca chuyn ng nm:",
    "+ Nm ngang:",
    "Tm xa: $L = v_0.t = v_0.\\sqrt{\\frac{2.H}{g}}$",
    "+ Nm xin:",
    "Tm cao: $H = \\frac{v_0^2.\\sin^2\\alpha}{2.g}$",
    "Tm xa: $L = \\frac{v_0^2.\\sin 2\\alpha}{g}$",
    "Ch : Cc cng thc trn ch ng khi lc cn ca khng kh khng ng k.",
    "",
    "53",
    "CHNG II  NG HC",
    "",
    "**EM C TH**",
    "1. S dng c cc cng thc ca chuyn ng nm ngang  gii thch cch th hng cu tr bng my bay.",
    "2. Vn dng c kin thc v chuyn ng nm xin  gii thch mt s tnh hung n gin trong cuc sng. V d: thnh tch nhy xa ca vn ng vin ph thuc vo gc nhy, vic iu chnh gc bn  c tm n bay xa nht ca cc pho th.",
    "",
    "## HOT NG TRI NGHIM",
    "**I. Mc ch**",
    "Nghin cu tm hiu iu kin  nm mt vt t tm bay xa ln nht.",
    "**II. Chun b**",
    "- Dng c c th dng  bn cc vin bi nh vi nhng lc c  ln khc nhau, theo cc phng khc nhau.",
    "- Thc o  di, thc o gc.",
    "- a im lm th nghim c cc  cao khc nhau, m bo an ton tuyt i khi tin hnh th nghim.",
    "**III. Cc bc tin hnh**",
    "1. Tm hiu bng l thuyt",
    "Vn dng nhng kin thc  hc v chuyn ng nm  d on v:",
    "  nm ngang mt vt t tm bay xa ln nht th phi chn  cao nh th no?",
    "  nm xin mt vt t tm bay xa ln nht th phi chn gc nm nh th no?",
    "2. Lp phng n lm th nghim kim tra d on.",
    "3. Thc hin th nghim, rt ra kt lun.",
    "4. Vit bo co v kt qu tm c.",
    "5. Trnh by bo co trc lp.",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B13', 'Bài 13. Tổng hợp và phân tích lực. Cân bằng lực', 57, 1, $JSON$
{
  "content": [
    "# Bi 13 TNG HP V PHN TCH LC. CN BNG LC",
    "",
    "**Khi ng:**",
    "*Hai tu ko ging nhau dng dy cp  ko mt tu ch hng b cht my vo cng bng hai lc $\\vec{F}_1$ v $\\vec{F}_2$ nh hnh di y.*",
    "* Tu ch hng s chuyn ng theo hng no?*",
    "* Lm th no  tnh c  ln ca lc ko tc dng ln tu ch hng?*",
    "[Hnh nh 2 chic tu ko nh ko 1 chic tu ch hng ln, tu ko 1 c lc $\\vec{F}_1$, tu ko 2 c lc $\\vec{F}_2$]",
    "",
    "## I. TNG HP LC  HP LC TC DNG",
    "*Tng hp lc* l php thay th cc lc tc dng ng thi vo cng mt vt bng mt lc c tc dng ging ht nh cc lc y.",
    "Lc thay th ny gi l *hp lc*.",
    "V mt ton hc, ta c th tm hp lc bng php cng vect:",
    "$\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots$ (13.1)",
    "",
    "**? Cu hi:**",
    "Ti sao lc y ca ngi b trong Hnh 13.1b c tc dng nh lc y ca hai anh em?",
    "a) Hai anh em y thng hng, lc $\\vec{F}_1, \\vec{F}_2$, xe nhch ln vi vn tc $\\vec{v}$.",
    "b) B y thng hng vi lc $\\vec{F}$ ln, xe nhch ln vi vn tc $\\vec{v}$. \"Thi, hai con  b y tip cho!\"",
    "[Hnh 13.1. V d v tng hp lc]",
    "",
    "56",
    "CHNG III  NG LC HC",
    "",
    "**1. Tng hp hai lc cng phng**",
    "**? Cu hi:**",
    "1. Da vo Hnh 13.2, hy nu cch xc nh  ln v chiu ca hp lc trong hai trng hp:",
    "a) Vt chu tc dng ca hai lc cng phng, cng chiu (Hnh 13.2a).",
    "b) Vt chu tc dng ca hai lc cng phng, ngc chiu (Hnh 13.2b).",
    "2. Nu quy tc tng hp hai lc cng phng.",
    "[Hnh 13.2. Tng hp hai lc cng phng.",
    "a) Hai lc $\\vec{F}_1$ (3N) v $\\vec{F}_2$ (2N) cng chiu. Hp lc $\\vec{F}$ (5N) bng tng hai lc.",
    "b) Hai lc $\\vec{F}_1$ (5N) v $\\vec{F}_2$ (3N) ngc chiu. Hp lc $\\vec{F}$ (2N) cng chiu vi lc ln hn]",
    "",
    "**2. Tng hp hai lc ng quy  Quy tc hnh bnh hnh**",
    "T cc th nghim v thc t, ngi ta thy rng php tng hp hai lc ng quy tun theo quy tc hnh bnh hnh sau y (Hnh 13.3):",
    "- Bc 1: V hai vect $\\vec{F}_1$ v $\\vec{F}_2$ ng quy ti O.",
    "- Bc 2: V mt hnh bnh hnh c hai cnh lin k trng vi hai vect $\\vec{F}_1$ v $\\vec{F}_2$.",
    "- Bc 3: V ng cho hnh bnh hnh c cng gc O. Vect hp lc $\\vec{F}$ trng vi ng cho ny.",
    "[Hnh 13.3. Tng hp lc theo quy tc hnh bnh hnh. Hai vect $\\vec{F}_1$ v $\\vec{F}_2$ to thnh hnh bnh hnh, ng cho l $\\vec{F} = \\vec{F}_1 + \\vec{F}_2$]",
    "",
    "**? Cu hi:**",
    "1. Cho hai lc ng quy c  ln $F_1 = 6$ N v $F_2 = 8$ N.",
    "Nu hp lc c  ln F = 10 N th gc gia hai lc $\\vec{F}_1$ v $\\vec{F}_2$ bng bao nhiu? V hnh minh ho.",
    "2. Gi s lc ko ca mi tu ko  u bi u c  ln bng 8000 N v gc gia hai dy cp bng $30^\\circ$.",
    "a) Biu din cc lc ko ca mi tu v hp lc tc dng vo tu ch hng.",
    "b) Tnh  ln ca hp lc ca hai lc ko.",
    "c) Xc nh phng v chiu ca hp lc.",
    "d) Nu gc gia hai dy cp bng $90^\\circ$ th hp lc ca hai lc ko c phng, chiu v  ln nh th no?",
    "",
    "57",
    "CHNG III  NG LC HC",
    "",
    "## II. CC LC CN BNG V KHNG CN BNG",
    "**1. Cc lc cn bng**",
    "Xt trng hp vt ng yn di tc dng ca nhiu lc. Khi  tng hp cc lc tc dng ln vt bng 0. Ta ni cc lc tc dng ln vt l *cc lc cn bng* v vt  trng thi *cn bng*.",
    "$\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots = \\vec{0}$ (13.2)",
    "[Hnh 13.4. Hai lc $\\vec{F}_1$ v $\\vec{F}_2$ cn bng nhau. $\\vec{F}_1$ v $\\vec{F}_2$ cng  ln 3N, ngc chiu. $F = F_1 - F_2 = 0$]",
    "",
    "**? Cu hi:**",
    "Quan st quyn sch ang nm yn trn mt bn (Hnh 13.5).",
    "a) C nhng lc no tc dng ln quyn sch?",
    "b) Cc lc ny c cn bng khng? V sao?",
    "[Hnh 13.5. Quyn sch nm yn trn mt bn]",
    "",
    "**2. Cc lc khng cn bng**",
    "Khi hp lc ca cc lc khc 0 th cc lc ny khng cn bng. Hp lc hay lc khng cn bng ny tc dng vo mt vt c th lm thay i vn tc ca vt.",
    "",
    "**? Cu hi:**",
    "1. Mt  t chu mt lc $F_1 = 400$ N hng v pha trc v mt lc $F_2 = 300$ N hng v pha sau (Hnh 13.6). Hi hp lc tc dng ln  t c  ln bng bao nhiu v hng v pha no?",
    "[Hnh 13.6. Chic  t vi $\\vec{F}_1$ hng ti v $\\vec{F}_2$ hng lui]",
    "2. Quan st mi cp tnh hung  Hnh 13.7.",
    "a) Tnh hung no c hp lc khc 0?",
    "b) M t s thay i vn tc ( ln, hng) ca mi vt trong hnh, nu c.",
    "[Hnh 13.7. Cc tnh hung:",
    "a) Bt ch nm yn trn mt bn.",
    "b) Dng tay y  bt ch chuyn ng nhanh dn.",
    "c) Qu bng ang nm yn  gn mp bn.",
    "d) Qu bng va ri khi mp bn.]",
    "",
    "58",
    "CHNG III  NG LC HC",
    "",
    "## III. PHN TCH LC",
    "Phn tch lc l php thay th mt lc thnh hai lc thnh phn c tc dng ging ht nh lc y.",
    "",
    "**1. Quy tc**",
    "a) Thng ngi ta phn tch lc thnh hai lc vung gc vi nhau  lc thnh phn ny khng c tc dng no theo phng ca lc thnh phn kia.",
    "b) Phn tch lc l php lm ngc li vi tng hp lc nhng ch c p dng vo trng hp ring nu  trn. Hnh 13.8 cho bit cch phn tch mt lc $\\vec{F}$ theo hai trc.",
    "[Hnh 13.8. Phn tch lc $\\vec{F}$ trn h trc Oxy thnh $\\vec{F}_x$ v $\\vec{F}_y$ vung gc]",
    "",
    "**2. Ch **",
    "Ch khi xc nh c mt lc c tc dng theo hai phng vung gc gc no th mi phn tch lc theo hai phng vung gc .",
    "",
    "**3. V d**",
    "Xt mt vt ang trt trn mt mt phng nghing nhn (Hnh 13.9). Trng lc $\\vec{P}$ c tc dng: mt mt n p vt vo mt phng nghing, mt khc n ko vt trt theo mt phng nghing xung di. V th ta phn tch trng lc $\\vec{P}$ theo hai phng vung gc nh Hnh 13.9.",
    "[Hnh 13.9. Phn tch trng lc $\\vec{P}$ trn mt phng nghing thnh $\\vec{P}_1$ (song song mt phng) v $\\vec{P}_2$ (vung gc mt phng)]",
    "",
    "**? Cu hi:**",
    "Mt vt c gi yn trn mt mt phng nghing nhn bi mt l xo (Hnh 13.10).",
    "1. C nhng lc no tc dng ln vt?",
    "2. Phn tch trng lc tc dng ln vt thnh hai lc thnh phn v nu r tc dng ca hai lc ny.",
    "[Hnh 13.10. Vt c gi trn mt phng nghing gc $\\alpha$ bi mt l xo]",
    "",
    "**EM  HC**",
    "- Tng hp lc l php thay th cc lc tc dng ng thi vo cng mt vt bng mt lc c tc dng ging ht nh cc lc y. Lc thay th ny gi l hp lc.",
    "- Tng hp hai lc cng phng v ng quy u tun theo quy tc cng vct.",
    "- Nu cc lc tc dng ln mt vt cn bng nhau th hp lc tc dng ln vt bng 0.",
    "- Nu cc lc tc dng ln mt vt khng cn bng th hp lc tc dng ln vt  khc 0. Khi , vn tc ca vt thay i ( ln, hng).",
    "- Phn tch lc l php thay th mt lc bng hai lc thnh phn c tc dng ging ht lc .",
    "",
    "**EM C TH**",
    "1. Vn dng quy tc hnh bnh hnh  tm hp lc ca hai lc ng quy.",
    "2. Phn tch c mt lc thnh hai lc thnh phn vung gc.",
    "",
    "59"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B14', 'Bài 14. Định luật 1 Newton', 61, 2, $JSON$
{
  "content": [
    "# Bi 14 NH LUT 1 NEWTON",
    "",
    "**Khi ng:**",
    "*Hnh bn cho thy mt trong hai con tu v tr Voyager ang lm nhim v thm d cc hnh tinh nm xa Tri t trong h Mt Tri. Chng c phng ln t Mi Canaveral, Florida (Hoa K) vo nm 1977 v hin nay c hai con tu  ra khi h Mt Tri, ang tip tc hot ng v gi thng tin v Tri t.",
    "iu g  gip cho tu Voyager tip tc chuyn ng ri xa Tri t, mc d thc t khng cn lc no tc dng ln chng na?*",
    "[Hnh nh con tu v tr Voyager trong khng gian. Ngun nh: NASA Voyager]",
    "",
    "## I. LC V CHUYN NG",
    "Lc c phi l nguyn nhn lm cho mt vt chuyn ng v duy tr chuyn ng  hay khng?",
    "",
    "**? Cu hi:**",
    "Mt quyn sch ang nm yn trn mt bn. Ta phi y n th n mi dch chuyn v khi ngng y th n dng li. Nu em t mnh vo thi ca nh khoa hc Hy Lp Aristotle (384  322 TCN), khi m mi ngi cn cha bit n ma st, th em s tr li cu hi nu ra nh th no?",
    "",
    "Galilei b tr th nghim nh Hnh 14.1, ri th hn bi cho ln xung theo mng nghing 1. ng nhn thy hn bi ln ngc ln mng 2 n mt  cao thp hn  cao ban u.",
    "Khi h thp  nghing ca mng 2, ng thy hn bi ln trn mng 2 c mt on di hn. ng cho rng hn bi khng ln c n  cao ban u l v c ma st. ng tin on rng nu khng c ma st v nu mng nghing 2 nm ngang th hn bi s ln mi mi vi vn tc khng i.",
    "[Hnh 14.1. Minh ho th nghim ca Galilei.",
    "a) Mng 2 nghing nhiu, bi ln ln gn ti  cao h.",
    "b) Mng 2 nghing t, bi ln ln xa hn nhng vn cha ti h.",
    "c) Mng 2 nm ngang, bi ln mi mi trn mng ngang]",
    "",
    "60",
    "CHNG III  NG LC HC",
    "",
    "## II. NH LUT 1 NEWTON",
    "Nm 1687, nh vt l ngi Anh Newton  khi qut kt qu nghin cu ca mnh, ng thi pht trin cc  tng ca Galilei thnh mt nh lut chuyn ng, sau ny c gi l nh lut 1 Newton:",
    "*Nu mt vt khng chu tc dng ca lc no hoc chu tc dng ca cc lc c hp lc bng khng, th vt ang ng yn s tip tc ng yn, ang chuyn ng s tip tc chuyn ng thng u.*",
    "",
    "**? Cu hi:**",
    "Quan st cc vt trong Hnh 14.2.",
    "1. Gii thch ti sao qu cu ng yn.",
    "2. Ti sao ngi trt vn c th gi nguyn vn tc ca mnh?",
    "[Hnh 14.2.",
    "a) Qu cu ng yn khi c treo vo mt si dy.",
    "b) Ngi trt vn chuyn ng vi vn tc khng i]",
    "",
    "## III. QUN TNH",
    "**1. Qun tnh**",
    "Tnh cht bo ton trng thi ng yn hay chuyn ng ca vt, gi l *qun tnh* ca vt.",
    "- Do c qun tnh m mi vt c xu hng bo ton vn tc c v hng v  ln.",
    "- nh lut 1 Newton cn c gi l nh lut qun tnh.",
    "",
    "**Hot ng:**",
    "Th nghim Hnh 14.3 gip minh ho qun tnh ca vt.",
    "- *Chun b:* Mt tm vn di khong 1 m lm mt phng nghing, xe ln, vt nh t trn xe ln, vt chn (c th dng quyn sch dy) (Hnh 14.3).",
    "[Hnh 14.3. Xe ln c ch vt mu xanh ang ln xung dc, ng sch dy chn ngang]",
    "- *Tin hnh:*",
    "- t cc vt nh ln xe ln. Gi cc vt v xe ng yn trn nh mt phng nghing.",
    "- Th cho xe trt xung dc, dc theo mt phng nghing.",
    "- Quan st hin tng xy ra i vi xe v cc vt trn xe.",
    "- *Tho lun:*",
    "1. Gii thch ti sao khi xe trt xung dc v b cn li  cui dc th vt nh b vng v pha trc.",
    "2. Lm th no  gi cho vt trn xe khng b vng i?",
    "",
    "**? Cu hi:**",
    "1. M t v gii thch iu g xy ra i vi mt hnh khch ngi trong  t  cc tnh hung sau:",
    "a) Xe t ngt tng tc.",
    "b) Xe phanh gp.",
    "c) Xe r nhanh sang tri.",
    "2. Mt vt ang chuyn ng vi vn tc 3 m/s di tc dng ca cc lc. Nu bng nhin cc lc ny mt i th:",
    "A. Vt dng li ngay.",
    "B. Vt i hng chuyn ng.",
    "C. Vt chuyn ng chm dn ri dng li.",
    "D. Vt tip tc chuyn ng theo hng c vi vn tc 3 m/s.",
    "3. Mt vt ang nm yn trn mt bn nm ngang. Ti sao ta c th khng nh rng bn  tc dng mt lc ln n?",
    "",
    "61",
    "CHNG III  NG LC HC",
    "",
    "**2. ng dng ca qun tnh trong i sng**",
    "**? Cu hi:**",
    "1. Khi ngi trn  t, tu ln cao tc hoc my bay, hnh khch lun c nhc tht dy an ton. Gii thch iu ny.",
    "2.  tra u ba vo cn, nn chn cch no di y? Gii thch ti sao.",
    "a) p mnh cn ba xung t nh Hnh 14.4a.",
    "b) p mnh u ba xung t nh Hnh 14.4b.",
    "[Hnh 14.4. Hai cch tra u ba vo cn. a) p ui cn xung. b) p u ba xung]",
    "",
    "**EM  HC**",
    "- nh lut 1 Newton: Nu mt vt khng chu tc dng ca lc no hoc chu tc dng ca cc lc c hp lc bng 0, th vt ang ng yn s tip tc ng yn, ang chuyn ng s tip tc chuyn ng thng u.",
    "- Qun tnh ca vt l tnh cht bo ton trng thi ng yn hay chuyn ng.",
    "",
    "**EM C TH**",
    "1. Dng khi nim qun tnh  gii thch hin tng trong Hnh 14.5: Khi dng tay ko t t t giy v khi git mnh t giy.",
    "[Hnh 14.5. Mt cc nc t trn t giy trn mt bn]",
    "2. Gii thch c nguyn nhn ca nhiu v tai nn giao thng lin quan n qun tnh. Chun b mt bi thuyt trnh (di khong 15 pht) v  ti sau y: Rt nhiu v tai nn giao thng c nguyn nhn t qun tnh. Em hy nu mt s v d v iu  v cch phng trnh nhng tai nn ny.",
    "",
    "62"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B15', 'Bài 15. Định luật 2 Newton', 64, 3, $JSON$
{
  "content": [
    "# Bi 15 NH LUT 2 NEWTON",
    "",
    "**Khi ng:**",
    "*y mt xe ch hng cho n chuyn ng v nhn xt xem gia tc ca xe tng hay gim, nu:*",
    "*a) Gi nguyn lc y nhng khi lng xe tng ln (Hnh a v b).*",
    "*b) Gi nguyn khi lng nhng lc y tng ln (Hnh b v c).*",
    "[Hnh nh ngi y xe.",
    "a) y xe trng.",
    "b) y xe c cht hng.",
    "c) 2 ngi y xe c cht hng]",
    "",
    "## I. NH LUT 2 NEWTON",
    "T nhng quan st v th nghim cho thy gia tc ca mt vt khng ch ph thuc vo lc tc dng m cn ph thuc vo khi lng ca vt.",
    "Mi lin h gia ba i lng: *gia tc, lc v khi lng*  c Newton khi qut trong mt phng trnh vct n gin gi l nh lut 2 Newton:",
    "*Gia tc ca mt vt cng hng vi lc tc dng ln vt.  ln ca gia tc t l thun vi  ln ca lc v t l nghch vi khi lng ca vt.*",
    "$\\vec{a} = \\frac{\\vec{F}}{m}$ (15.1)",
    "Xt v mt Ton hc, nh lut 2 Newton c th vit l:",
    "$\\vec{F} = m.\\vec{a}$",
    "Trong trng hp vt chu nhiu lc tc dng $\\vec{F}_1, \\vec{F}_2, \\vec{F}_3, \\dots$ th $\\vec{F}$ l hp lc ca cc lc :",
    "$\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots$",
    "",
    "**EM C BIT?**",
    "Da vo biu thc $\\vec{F} = m.\\vec{a}$, ta c mi lin h:",
    "1 N = 1kg . 1m/s$^2$",
    "1 N l  ln ca lc gy ra gia tc 1 m/s$^2$ cho vt khi lng 1 kg, theo hng ca lc.",
    "| i lng | K hiu | n v |",
    "|---|---|---|",
    "| Gia tc | a | m/s$^2$ |",
    "| Khi lng | m | kg |",
    "| Lc | F | N |",
    "",
    "## II. KHI LNG V QUN TNH",
    "Lc u, khi lng ch c hiu l mt i lng dng  ch lng ca cht cha trong vt. Nhng nh lut 2 Newton cn cho ta mt cch hiu mi v khi lng.",
    "Tht vy, theo nh lut 2 Newton, nu c nhiu vt khc nhau ln lt chu tc dng ca cng mt lc khng i, th vt no c khi lng ln hn s c gia tc nh hn. Vy, vt no c khi lng cng ln th cng kh thay i vn tc, tc l cng c *mc qun tnh ln hn*. T  ta c th ni: *Khi lng ca vt l i lng c trng cho mc qun tnh ca vt.*",
    "",
    "**! Ch :**",
    "- Khi lng trong nh lut 2 Newton cn c gi l khi lng qun tnh.",
    "- Khi lng l i lng v hng, dng, khng i vi mi vt v c tnh cht cng c.",
    "",
    "63",
    "CHNG III  NG LC HC",
    "",
    "iu  cho php ta so snh c khi lng ca nhng vt lm bng cc cht khc nhau. Mt xe ch ct v mt xe ch go c coi l c khi lng bng nhau nu di tc dng ca hp lc nh nhau, chng c gia tc nh nhau.",
    "",
    "## III. TH NGHIM MINH HO NH LUT 2 NEWTON",
    "",
    "**Hot ng:** Th nghim c thit lp nh Hnh 15.2.",
    "*Dng c:*",
    "- Mt xe trt c khi lng M = 200 g c buc vo mt si dy vt qua rnh ca rng rc. Coi dy khng dn v c khi lng khng ng k.",
    "- Mt hp ng 10 qu nng ging nhau, c cng khi lng m = 50 g.",
    "- Mt mng trt m kh vi cc l nh thi khng kh (nhm gim ti a ma st khi xe di chuyn trn mng trt).",
    "- B m thi gian gm: mt ng h in t, hai cng quang (t cch nhau 0,5 m) v tm chn sng di 10 cm.",
    "- Vt  th nghim ny phi c hiu l h vt gm xe trt v cc qu nng. Nh vy khi lng ca vt c th l (M + m), (M + 2.m),... cn lc ko F l trng lng ca cc qu nng, c th l $F_1 = m.g, F_2 = 2.m.g,...$",
    "",
    "**? Cu hi:**",
    "1. Nu mt s v d cho thy khi lng ca vt cng ln th mc qun tnh ca vt cng ln. iu ny c  ngha g trong thc tin?",
    "2. Cho  th biu din mi lin h gia cc lc tc dng ln mt vt v gia tc gy ra tng ng (Hnh 15.1). Khi lng ca vt l",
    "A. 1,0 kg. B. 2,0 kg.",
    "C. 0,5 kg. D. 1,5 kg.",
    "[Hnh 15.1.  th F-a. Trc tung F(N) t 0 n 2.0. Trc honh a(m/s^2) t 0 n 4.0. ng thng i qua (2.0, 1.0) v (4.0, 2.0).  dc m = F/a = 1.0/2.0 = 0.5 kg]",
    "",
    "[Hnh 15.2. Th nghim minh ho nh lut 2 Newton. Gm Mng trt m kh (2), tm chn sng (1), 2 cng quang in (3,4), rng rc (5), cc qu nng (6), ng h o thi gian hin s (7), cn in t (8), bm kh (9)]",
    "*Hnh 15.2. Th nghim minh ho nh lut 2 Newton*",
    "(1) Tm chn sng;",
    "(2) Mng trt m kh;",
    "(3) Cng quang in 1;",
    "(4) Cng quang in 2;",
    "(5) Rng rc;",
    "(6) Cc qu nng;",
    "(7) ng h o thi gian hin s;",
    "(8) Cn in t;",
    "(9) Bm kh.",
    "",
    "64",
    "CHNG III  NG LC HC",
    "",
    "*Tin hnh:*",
    "Bc 1: Lc ko F c  ln tng dn 1 N, 2 N v 3 N (bng cch mc thm cc qu nng vo u dy vt qua rng rc).",
    "Bc 2: Ghi vo Bng 15.1  ln lc ko F v tng khi lng ca h (gm xe trt v cc qu nng t vo xe), ng vi mi ln th nghim.",
    "Bc 3: o thi gian chuyn ng t ca xe; ng h bt u m t lc tm chn sng i qua cng quang in 1 v kt thc m khi tm chn vt qua cng quang in 2.",
    "Bc 4: Gia tc a c tnh t cng thc: $s = v_0.t + \\frac{1}{2}.a.t^2$ (t xe trt c gn tm chn sng sao cho tm chn ny st vi cng quang in 1  $v_0 = 0$; s = 0,5 m l khong cch gia hai cng quang in trong th nghim). o thi gian t ng vi mi ln th nghim, ta tnh c:",
    "$a = \\frac{2.s}{t^2} = \\frac{2.0,5}{t^2} = \\frac{1}{t^2}$ (m/s$^2$). Ghi gi tr ca gia tc a vo Bng 15.1.",
    "",
    "Kt qu th nghim ghi trong Bng 15.1.",
    "**Bng 15.1.** Bng ghi kt qu th nghim",
    "| Lc ko F (N) | 1 | 1 | 1 | 2 | 3 |",
    "|---|---|---|---|---|---|",
    "| Khi lng (M + m) (kg) | 0,3 | 0,4 | 0,5 | 0,5 | 0,5 |",
    "| Thi gian t (s) | 0,55 | 0,64 | 0,71 | 0,50 | 0,42 |",
    "| Gia tc $a = \\frac{2.s}{t^2}$ (m/s$^2$) | 3,31 | 2,44 | 1,99 | 4,03 | 5,67 |",
    "",
    "*Tho lun:*",
    "a) Da vo s liu trong Bng 15.1, hy v  th ch s ph thuc ca gia tc a:",
    " Vo F (ng vi m + M = 0,5 kg), (Hnh 15.3a).  th c phi l ng thng khng? Ti sao?",
    " Vo $\\frac{1}{m + M}$ (ng vi F = 1 N), (Hnh 15.3b).  th c phi l ng thng khng? Ti sao?",
    "b) Nu kt lun v s ph thuc ca gia tc vo  ln ca lc tc dng v khi lng ca vt.",
    "",
    "[Hnh 15.3.",
    "a) H trc a(m/s^2) theo F(N) vi m+M = 0,5kg",
    "b) H trc a(m/s^2) theo 1/(m+M) (1/kg) vi F = 1N]",
    "",
    "65",
    "CHNG III  NG LC HC",
    "",
    "**! Ch :**",
    " Khi thc hin o gia tc theo phng n th nghim trn cn lu :  ng h bt u m thi gian khi xe c vn tc ban u bng 0, cn t tm chn sng st cng quang in 1.",
    " C th xc nh gia tc theo cng thc $a = \\frac{v_2^2 - v_1^2}{2.s}$, trong  $v_1, v_2$ ln lt l vn tc tc thi qua hai cng quang in; $v_1, v_2$ c o bng cch thay tm chn sng c chiu di $\\ell = 1$ cm v t ng h o thi gian  ch  o thi gian chn cng quang in.",
    "",
    "**? Cu hi:**",
    "1. Trong cc cch vit h thc ca nh lut 2 Newton sau y, cch vit no ng?",
    "A. $\\vec{F} = m.a$",
    "B. $\\vec{F} = -m.\\vec{a}$",
    "C. $F = m.\\vec{a}$",
    "D. $-\\vec{F} = m.\\vec{a}$",
    "2. Mt qu bng khi lng 0,50 kg ang nm yn trn mt t. Mt cu th  bng vi mt lc 250 N. Thi gian chn tc dng vo bng l 0,02 s. Qu bng bay i vi tc :",
    "A. 0,01 m/s.",
    "B. 0,10 m/s.",
    "C. 2,50 m/s.",
    "D. 10,00 m/s.",
    "3. Di tc dng ca hp lc 20 N, mt chic xe  chi chuyn ng vi gia tc 0,4 m/s$^2$. Di tc dng ca hp lc 50 N, chic xe s chuyn ng vi gia tc bao nhiu?",
    "4. Ti sao my bay khi lng cng ln th ng bng phi cng di?",
    "",
    "**EM  HC**",
    "- nh lut 2 Newton: Gia tc ca mt vt cng hng vi lc tc dng ln vt.  ln ca gia tc t l thun vi  ln ca lc v t l nghch vi khi lng ca vt.",
    "$\\vec{a} = \\frac{\\vec{F}}{m}$",
    "Xt v mt Ton hc, nh lut 2 Newton c th vit l $\\vec{F} = m.\\vec{a}$.",
    "- Khi lng l i lng c trng cho mc qun tnh ca vt.",
    "",
    "**EM C TH**",
    "1.  xut c mt th nghim chng t gia tc m vt thu c ph thuc vo:",
    "a)  ln ca lc tc dng vo vt.",
    "b) Khi lng ca vt.",
    "2. Gii thch c khi lng ca vt cng ln th qun tnh ca vt cng ln.",
    "3. Gii thch ti sao trong tham gia giao thng, khi  t ch hng nng kh hm phanh hn khi  t khng ch hng.",
    "",
    "66"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B16', 'Bài 16. Định luật 3 Newton', 68, 4, $JSON$
{
  "content": [
    "# Bi 16 NH LUT 3 NEWTON",
    "",
    "**Khi ng:**",
    "*Mc hai lc k vo nhau ri ko mt trong hai lc k nh hnh sau.*",
    "*a) D on xem s ch ca hai lc k ging nhau hay khc nhau.*",
    "*b) Hy kim tra kt qu v nu kt lun.*",
    "*c) Nu c hai tip tc ko v hai pha ngc nhau vi  ln lc tng ln th s ch ca hai lc k s thay i th no?*",
    "[Hnh nh 2 lc k mc vo nhau v ko v 2 pha]",
    "",
    "## I. NH LUT 3 NEWTON",
    "**1. Lc tng tc gia hai vt**",
    "**Hot ng:** Quan st th nghim c m t trong Hnh 16.1.",
    "1. Mt thanh st v mt thanh nam chm c treo nh Hnh 16.1a. Trong th nghim ny, lc no lm cho thanh nam chm dch chuyn li gn thanh st?",
    "2. Xe ln 1 c khi lng $m_1$ v c gn mt l xo nh. Xe ln 2 c khi lng $m_2$. Ta cho hai xe p li gn nhau bng cch buc dy  nn l xo (Hnh 16.1b). Quan st hin tng xy ra khi t si dy buc. Tho lun  lm sng t  kin sau: *Lc khng tn ti ring l. Cc lc ht hoc y lun xut hin thnh tng cp gia hai vt.*",
    "[Hnh 16.1. Th nghim v s tng tc gia cc vt.",
    "a) Thanh st v thanh nam chm treo trn 2 si dy ht nhau.",
    "b) Xe ln 1 c l xo b nn p vo xe ln 2 bng si dy. Khi t dy, 2 xe y nhau ra]",
    "",
    "**2. nh lut 3 Newton**",
    "Trong mi trng hp, khi vt A tc dng ln vt B mt lc th vt B cng tc dng tr li vt A mt lc. Hai lc ny l hai lc trc i (Hnh 16.2).",
    "$\\vec{F}_{AB} = -\\vec{F}_{BA}$",
    "Hai lc trc i l hai lc tc dng theo cng mt ng thng, ngc chiu nhau, c  ln bng nhau v im t ln hai vt khc nhau.",
    "[Hnh 16.2. Cp lc v phn lc.",
    "a) 2 vt A, B ht nhau: $\\vec{F}_{BA}$ t trn A hng v B, $\\vec{F}_{AB}$ t trn B hng v A.",
    "b) 2 vt A, B y nhau: $\\vec{F}_{BA}$ t trn A hng ra xa B, $\\vec{F}_{AB}$ t trn B hng ra xa A]",
    "",
    "## II. CC C IM CA LC V PHN LC",
    "Theo nh lut 3 Newton, trong tng tc gia hai vt, mt lc gi l lc tc dng cn lc kia gi l phn lc.",
    "",
    "**? Cu hi:**",
    "1. Cp lc v phn lc c nhng c im g?",
    "2. Cp lc v phn lc c phi l hai lc cn bng hay khng? Ti sao?",
    "",
    "**? Cu hi:**",
    "Hy ch r im t ca mi lc trong mi cp lc  Hnh 16.2 a, b.",
    "",
    "67",
    "CHNG III  NG LC HC",
    "",
    "**? Cu hi:**",
    "1. Hy ch ra cc cp lc v phn lc trong hai trng hp sau:",
    "a) Quyn sch nm yn trn mt bn (Hnh 16.3a).",
    "b) Dng ba ng inh vo g (Hnh 16.3b).",
    "2. Quyn sch nm yn c phi l kt qu ca s cn bng gia lc v phn lc hay khng?",
    "3. Lc do ba tc dng vo inh v phn lc ca inh ln ba c cc c im g?",
    "[Hnh 16.3.",
    "a) Quyn sch trn bn.",
    "b) Ba ng inh vo ming g]",
    "",
    "**Hot ng:**",
    "1. Trong th nghim  phn m u bi hc, nu c hai ngi cng ko nhng  lc k di chuyn v pha mt ngi (v d cng di chuyn hai lc k sang phi) th s ch ca hai lc k s ging nhau hay khc nhau? Lm th nghim kim tra d on.",
    "2. Nu thm mt s v d trong thc t v tho lun  lm sng t cc c im sau y ca lc v phn lc:",
    "- Lc v phn lc lun xut hin thnh tng cp (xut hin hoc mt i ng thi).",
    "- Lc v phn lc cng tc dng theo mt ng thng, cng  ln nhng ngc chiu (hai lc nh vy l hai lc trc i).",
    "- Lc v phn lc khng cn bng nhau (v chng t vo hai vt khc nhau).",
    "- Cp lc v phn lc l hai lc cng loi.",
    "",
    "**? Cu hi:**",
    "Mt  t chuyn ng trn mt ng (Hnh 16.4), nu lc do  t tc dng ln mt ng c  ln bng lc m mt ng y  t th ti sao chng khng kh nhau?",
    "[Hnh 16.4. Xe  t mu xanh chy trn ng, c $\\vec{F}$ hng ra sau l lc do bnh xe y ng v $\\vec{F}'$ hng ti trc l lc ng y bnh xe]",
    "",
    "**EM  HC**",
    "nh lut 3 Newton: Trong mi trng hp, khi vt A tc dng ln vt B mt lc, th vt B cng tc dng tr li vt A mt lc. Hai lc ny tc dng theo cng mt phng, cng  ln, nhng ngc chiu, im t ln hai vt khc nhau: $\\vec{F}_{AB} = -\\vec{F}_{BA}$.",
    "",
    "**EM C TH**",
    "Gii thch ti sao cc vn ng vin khi bi ti mp h bi v quay li th dng chn y mnh vo vch h bi  di chuyn nhanh hn.",
    "",
    "68"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B17', 'Bài 17. Trọng lực và lực căng', 70, 5, $JSON$
{
  "content": [
    "# Bi 17 TRNG LC V LC CNG",
    "",
    "**Khi ng:**",
    "*Cc tnh hung  hnh di y lin quan n nhng loi lc no?*",
    "[Hnh nh cc tnh hung:",
    "a) Em b th diu.",
    "b) Em b ko hp  chi bng dy.",
    "c) Hai ngi cho thuyn trn mt nc.",
    "d) Ngi chi cu lng p qu cu]",
    "",
    "## I. TRNG LC",
    "**Hot ng:**",
    "Tho lun tnh hung c  cp trong Hnh 17.1: Ti sao khi c bung ra, cc vt quanh ta u ri xung t?",
    "[Hnh 17.1. Em b bung qu bng ri xung t]",
    "",
    "**1. Trng lc**",
    "Trng lc l lc hp dn do Tri t tc dng ln vt gy ra cho vt gia tc ri t do. Trng lc c k hiu l vect $\\vec{P}$.",
    "  gn Tri t trng lc c:",
    "+ Phng thng ng.",
    "+ Chiu t trn xung.",
    "+ im t gi l trng tm ca vt.",
    " Cng thc ca trng lc",
    "p dng nh lut 2 Newton vo trng hp vt ri t do, ta tm c cng thc ca trng lc: $\\vec{P} = m.\\vec{g}$",
    "",
    "**2. Trng lng**",
    "  ln ca trng lc tc dng ln mt vt gi l trng lng ca vt.",
    " Cng thc tnh trng lng: $P = m.g$",
    " Trng lng ca mt vt c th o bng lc k hoc cn l xo Hnh 17.2.",
    "[Hnh 17.2. o trng lng ca vt bng lc k]",
    "",
    "**? Cu hi:**",
    "Lc k trong Hnh 17.2 ang ch  vch 1 N.",
    "a) Tnh trng lng v khi lng ca vt bng lc k. Ly g $\\approx$ 9,8 m/s$^2$.",
    "b) Biu din cc lc tc dng ln vt (xem vt l cht im).",
    "",
    "69",
    "CHNG III  NG LC HC",
    "",
    "**3. Phn bit trng lng v khi lng**",
    "Trng lng ca mt vt thay i khi em n mt ni khc c gia tc ri t do thay i.",
    "Khi lng l s o lng cht ca vt. V vy, khi lng ca mt vt khng thay i khi ta chuyn n t ni ny n ni khc.",
    "",
    "**? Cu hi:**",
    "o trng lng ca mt vt  mt a im trn Tri t c gia tc ri t do l 9,80 m/s$^2$, ta c P = 9,80 N. Nu em vt ny ti mt a im khc c gia tc ri t do 9,78 m/s$^2$ th khi lng v trng lng ca n o c l bao nhiu?",
    "",
    "**Hot ng:**",
    "Xc nh trng tm ca mt vt phng, mng",
    "- *Chun b:* mt s tm ba cc-tng phng, mng; dy treo; thc thng; bt ch; ko.",
    "- *Tin hnh:*",
    "*Th nghim 1:* Hy xc nh trng tm ca tm ba cc-tng  Hnh 17.3 v gii thch r cch lm ca em.",
    "*Th nghim 2:* Ct mt s tm ba cc-tng thnh hnh trn, hnh vung, hnh tam gic u. Hy tin hnh th nghim  kim chng kt lun sau:",
    "*\"Trng tm ca cc vt phng, mng v c dng hnh hc i xng nm  tm i xng ca vt\"*.",
    "[Hnh 17.3. Tm ba cc tng treo bng si dy]",
    "",
    "## II. LC CNG",
    "Khi dng hai tay ko dn mt si dy cao su, ta thy dy cao su cng ko tr li hai tay. Khi mt si dy b ko th  ti mi im trn dy, k c hai u dy xut hin lc  chng li s ko (Hnh 17.4), lc ny gi l *lc cng*, k hiu l $\\vec{T}$.",
    "[Hnh 17.4. Lc cng dy xut hin khi tay ko dy cao su hoc treo vt nng]",
    "",
    "**Hot ng:**",
    "1. Da vo Hnh 17.4, hy tho lun v phn tch  lm sng t cc  sau y:",
    "- Nhng vt no chu lc cng ca dy?",
    "- Lc cng c phng, chiu th no?",
    "T , nu nhng c im (v phng, chiu, im t) ca lc cng.",
    "2. Hy ch ra im t, phng, chiu ca lc cng trong Hnh 17.5a v 17.5b.",
    "[Hnh 17.5.",
    "a) Hai ngi ko co bng si dy thng.",
    "b) Em b dng dy ko  chi trn xe trt]",
    "",
    "70",
    "CHNG III  NG LC HC",
    "",
    "**? Cu hi:**",
    "1. Mt bng n c khi lng 500 g c treo thng ng vo trn nh bng mt si dy v ang  trng thi cn bng.",
    "a) Biu din cc lc tc dng ln bng n.",
    "b) Tnh  ln ca lc cng.",
    "c) Nu dy treo ch chu c mt lc cng gii hn 5,5 N th n c b t khng?",
    "2. Mt con kh biu din xic. N dng tay nm vo dy  ng yn treo mnh nh Hnh 17.7. Hy cho bit trong hai lc cng xut hin trn dy ($\\vec{T}_1$ v $\\vec{T}_2$), lc no c  ln ln hn. Ti sao?",
    "[Hnh 17.7. Con kh u dy. Dy bn tri to gc $14^\\circ$ vi phng ngang, dy bn phi $20^\\circ$]",
    "",
    "**EM C BIT?**",
    "- Mi si dy ch chu c mt lc cng gii hn. Khi lc tc dng ln dy vt qu gi tr gii hn ny th dy s t.",
    "- Trong Hnh 17.6, nu khi lng ca rng rc v ca dy u rt nh so vi khi g (c th b qua) th lc cng  cc im trn dy c  ln bng nhau.",
    "$T_1 = T_1' = T_2 = T_2'$",
    "[Hnh 17.6. H thng rng rc. Vt nng trn bn, rng rc  mp bn, lc k ko thng ng xung. $\\vec{T}_1, \\vec{T}_1'$ nm ngang. $\\vec{T}_2, \\vec{T}_2'$ thng ng]",
    "",
    "**EM  HC**",
    "- Trng lc c k hiu l vect $\\vec{P}$, c:",
    " Phng thng ng.",
    " Chiu hng v pha tm Tri t.",
    " im t ca trng lc gi l trng tm ca vt.",
    "  ln: P = m.g.",
    "- Khi vt ng yn trn Tri t, trng lng ca vt bng  ln ca trng lc tc dng ln vt: P = m.g.",
    "- Lc cng do si dy tc dng vo vt, c phng trng vi phng ca si dy, c chiu ngc vi chiu ca lc do vt ko dn dy.",
    "",
    "**EM C TH**",
    "1. Gii thch c trng tm ca cc vt phng, ng cht, c dng hnh hc i xng nm  tm i xng ca vt.",
    "2. Gii thch c ti sao cc v tinh nhn to ca Tri t cui cng u ri xung Tri t.",
    "",
    "71"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B18', 'Bài 18. Lực ma sát', 73, 6, $JSON$
{
  "content": [
    "# Bi 18 LC MA ST",
    "",
    "**Khi ng:**",
    "*iu g ngn cn thng hng (Hnh a), khin n khng th di chuyn? Ti sao lc y tng ln (Hnh b) m vn khng lm cho thng hng di chuyn?*",
    "*C cch no lm thng hng di chuyn d dng hn khng?*",
    "[Hnh nh 2 ngi y thng hng.",
    "a) y nh, thng hng ng im.",
    "b) y mnh hn, thng hng vn ng im]",
    "",
    "## I. LC MA ST NGH",
    "Lc ma st ngh l lc ma st tc dng ln mt tip xc ca vt, khi vt c xu hng chuyn ng nhng cha chuyn ng (Hnh 18.1).",
    "[Hnh 18.1. Lc ma st ngh $\\vec{F}_{\\text{ms ngh}}$ tc dng ln vt, hp lc bng khng ($\\vec{v} = 0$)]",
    "",
    "**? Cu hi:**",
    "1. iu no sau y khng ng khi ni v lc ma st ngh?",
    "A. Lc ma st ngh lun xut hin  b mt tip xc gia hai vt.",
    "B. Lc ma st ngh gi cho cc im tip xc ca vt khng trt trn b mt.",
    "C. Mt vt c th ng yn trn mt phng nghing m khng cn n lc ma st ngh.",
    "D. Mt vt c th ng yn trn mt phng ngang m khng cn n lc ma st ngh.",
    "2. Cc tnh hung sau y lin quan n loi lc ma st no?",
    "a) Xoa hai bn tay vo nhau.",
    "b) t vali ln mt bng chuyn ang chuyn ng  sn bay.",
    "",
    "72",
    "CHNG III  NG LC HC",
    "",
    "**Hot ng:**",
    "Quan st Hnh 18.2 v tho lun cc tnh hung sau:",
    "t trn bn mt vt nng c dng hnh hp.",
    "- Lc u ta y vt bng mt lc c cng  nh, vt khng chuyn ng (Hnh 18.2a). Lc no  ngn khng cho vt chuyn ng?",
    "- Tng lc y n khi ln hn mt gi tr $F_0$ no  (Hnh 18.2b) th vt bt u trt. iu  chng t g?",
    "- Khi vt  trt, ta ch cn y vt bng mt lc nh hn gi tr $F_0$ vn duy tr c chuyn ng trt ca vt (Hnh 18.2c). iu  chng t g?",
    "[Hnh 18.2.",
    "a) Vt ng yn. Lc y $\\vec{F}$ nh.",
    "b) Vt bt u chuyn ng. Lc y $\\vec{F}_0$ ln hn.",
    "c) Vt tip tc chuyn ng. Lc y $\\vec{F} < \\vec{F}_0$]",
    "",
    "## II. LC MA ST TRT",
    " lp 6 ta  bit, lc ma st trt l lc ma st cn tr vt trt trn b mt tip xc (Hnh 18.3).",
    "[Hnh 18.3. Lc ma st trt $\\vec{F}_{\\text{ms}}$. Vt c vn tc $\\vec{v}$]",
    "Cc th nghim di y s gip cc em tm hiu thm mt s c im ca lc ma st trt.",
    "",
    "**1. c im ca lc ma st trt**",
    "*Th nghim 1: Kim chng  ln ca lc ma st ph thuc vo vt liu v tnh trng ca b mt tip xc, nhng khng ph thuc vo din tch tip xc.*",
    "*Chun b:* Lc k (c GH 1,0 N, CNN 0,01 N), khi g hnh hp ch nht, cc b mt: g, giy.",
    "*Tin hnh:*",
    "1. t mt c din tch ln ca khi g ln b mt tip xc.",
    "- Gn lc k vo gi th nghim  c nh lc k theo phng nm ngang.",
    "- Mc khi g vo lc k, ln lt ko cc mt tip xc (mt g, mt t giy) theo phng nm ngang  chng trt u di khi g (Hnh 18.4).",
    "- Ghi s ch ca lc k vo Bng 18.1. Ly gi tr trung bnh ca cc s ch lc k lm  ln ca lc ma st trt.",
    "[Hnh 18.4. Th nghim o lc ma st.",
    "a) Trt trn mt g.",
    "b) Trt trn mt giy]",
    "2. t mt c din tch nh ca khi g ln b mt tip xc v lp li th nghim nh trn.",
    "",
    "73",
    "CHNG III  NG LC HC",
    "",
    "**Bng 18.1**",
    "| B mt tip xc | Ln 1 |  ln lc ma st trt (N) | Ln 2 | Ln 3 | Trung bnh |",
    "|---|---|---|---|---|---|",
    "| Mt g | | | | | |",
    "| Mt giy | | | | | |",
    "",
    "*Tho lun v phn tch:*",
    "a) Nu cc lc tc dng ln khi g khi mt tip xc bn di n c ko trt u. Ti sao khi  s ch ca lc k bng  ln ca lc ma st trt?",
    "b) Sp xp th t theo mc tng dn lc ma st trn mi b mt.",
    "c) iu g xy ra i vi  ln ca lc ma st trt khi din tch tip xc thay i, khi vt liu v tnh trng ca b mt tip xc thay i?",
    "",
    "*Th nghim 2: Mi lin h gia  ln ca lc ma st trt vi  ln ca p lc ln b mt tip xc.*",
    "*Chun b:* Lc k (c GH 1,0 N, CNN 0,01 N), ba khi g hnh hp ch nht ging nhau, mt tip xc: g.",
    "*Tin hnh:*",
    "- o trng lng ca khi g bng lc k. Ghi vo Bng 18.2 (p lc ca khi g ln mt tip xc nm ngang c  ln bng trng lng ca khi g).",
    "- Gn lc k vo gi th nghim  c nh lc k theo phng nm ngang.",
    "- Mc khi g vo lc k, ko mt tip xc (mt g) theo phng nm ngang  n trt u di khi g. Ghi li s ch ca lc k trong 3 ln th nghim vo Bng 18.2. Ly gi tr trung bnh cc kt qu o.",
    "- Ln lt t thm 1, 2 khi g ln khi g u tin v lp li bc 3.",
    "",
    "**Bng 18.2**",
    "| p lc ca cc khi g (N) | Ln 1 |  ln lc ma st trt (N) | Ln 2 | Ln 3 | Trung bnh |",
    "|---|---|---|---|---|---|",
    "| 1 khi g: ... | | | | | |",
    "| 2 khi g: ... | | | | | |",
    "| 3 khi g: ... | | | | | |",
    "",
    "*Tho lun v phn tch:*",
    "a) iu g xy ra i vi  ln ca lc ma st trt khi tng p lc ln b mt tip xc?",
    "b) V  th cho thy s thay i  ln ca lc ma st trt khi tng dn  ln ca p lc.",
    "c) Nu kt lun v nhng c im ca lc ma st trt.",
    "",
    "74",
    "CHNG III  NG LC HC",
    "",
    "**3. Cng thc ca lc ma st trt**",
    "**a) H s ma st trt**",
    "T s gia  ln ca lc ma st trt $F_{\\text{ms}}$ v p lc N gi l h s ma st trt, k hiu l $\\mu$.",
    "H s $\\mu$ ph thuc vo vt liu v tnh trng ca hai mt tip xc (xem Bng 18.3).",
    "**Bng 18.3.** H s ma st trt (gn ng) ca mt s cp vt liu",
    "| Cp vt liu tip xc nhau | $\\mu$ |",
    "|---|---|",
    "| G trn g (kh) | 0,20 |",
    "| Thp trn thp (kh) | 0,57 |",
    "| Thp trn thp (trn) | 0,07 |",
    "| Cao su trn b tng (kh) | 0,70 |",
    "| Cao su trn b tng (t) | 0,50 |",
    "| Cao su trn bng | 0,10 |",
    "",
    "**b) Cng thc tnh lc ma st trt**",
    "$F_{\\text{ms}} = \\mu . N$",
    "",
    "**EM C BIT?**",
    "Trong cc iu kin cng p lc N th lc ma st ngh tc dng vo cc vt ln nh hn lc ma st trt tc dng ln cc vt trt rt nhiu.",
    "",
    "## III. BI TP V D",
    "Mt ngi i xe p c khi lng tng cng m = 86 kg ang chuyn ng trn ng nm ngang vi vn tc $v_0 = 4$ m/s. Nu ngi i xe ngng p v hm phanh  gi khng cho cc bnh xe quay, xe trt i mt on ng 2 m th dng li.",
    "1. Lc no  gy ra gia tc cho xe? Tnh  ln ca lc ny.",
    "2. Tnh h s ma st trt gia mt ng v lp xe? Ly g = 10 m/s$^2$.",
    "*Gii*",
    "Khi tnh lc v gia tc, ta coi ngi + xe l cht im. Chn chiu dng l chiu chuyn ng ca ngi v xe.",
    "1. Gia tc ca chuyn ng c tnh bng cng thc:",
    "$a = \\frac{v_t^2 - v_0^2}{2.s} = \\frac{0 - 16}{2.2} = -4$ m/s$^2$",
    "Lc gy ra gia tc ny l lc ma st trt ca mt ng tc dng ln lp xe:",
    "$F = m.a = 86.(-4) = -344$ N",
    "Du \"\" chng t lc ma st trt ngc chiu chuyn ng.",
    "2. H s ma st trt gia lp xe vi mt ng c tnh t cng thc:",
    "$F_{\\text{ms}} = \\mu . N \\Rightarrow \\mu = \\frac{F_{\\text{ms}}}{N}$, v  t chuyn ng trn ng nm ngang nn N = P = m.g.",
    "$\\Rightarrow \\mu = \\frac{344}{86.10} = 0,4$.",
    "",
    "**? Cu hi:**",
    "1. Cc lc tc dng ln xe ch hng c quy c v ti trng tm ca xe (Hnh 18.5):",
    "a) Cc lc ny c tn gi l g?",
    "b) Hy ch ra cc cp lc cn bng nhau.",
    "2.  y chic t, cn tc dng mt lc theo phng nm ngang c gi tr ti thiu 300 N  thng lc ma st ngh. Nu ngi ko t vi lc 35 N v ngi kia y t vi lc 260 N, c th lm dch chuyn t c khng? Biu din cc lc tc dng ln t.",
    "[Hnh 18.5. Xe ch hng c 4 lc tc dng t trng tm: $\\vec{F}_C$ hng li, $\\vec{F}_A$ hng ti, $\\vec{F}_D$ hng ln, $\\vec{F}_B$ hng xung]",
    "",
    "75",
    "CHNG III  NG LC HC",
    "",
    "## IV. LC MA ST TRONG I SNG",
    "**? Cu hi:**",
    "Nu vai tr ca lc ma st trong cc tnh hung sau:",
    "a) Ngi di chuyn trn ng.",
    "b) Vn ng vin th dc dng c xoa phn vo lng bn tay trc khi nng t.",
    "",
    "**Hot ng:**",
    "1. Tho lun  lm sng t nhng vn  sau y:",
    "- Trong thc t, c mt s trng hp lc ma st c tc dng cn tr chuyn ng, nhng cng c trng hp lc ma st thc y chuyn ng.",
    "- Vai tr ca ma st trong lnh vc th thao.",
    "2. Nu mt s cch lm gim ma st trong k thut v trong i sng.",
    "",
    "**EM  HC**",
    "- Lc ma st ngh v lc ma st trt u l nhng lc tip xc.",
    "- Lc ma st ngh c gi tr cc i $F_0$. Khi lc y (hay ko) vt $F > F_0$ th vt bt u trt.",
    "- Cng thc ca lc ma st trt: $F_{\\text{ms}} = \\mu.N$",
    "Trong  $\\mu$ l h s ma st trt, khng c n v;",
    "N l p lc ln b mt.",
    "",
    "**EM C BIT?**",
    "Trong i sng v trong k thut,  gim ma st ngi ta thay vt trt bng vt ln (hnh cu hoc hnh tr) (Hnh 18.6).",
    "[Hnh 18.6. Con ln hoc  bi t xen gia vo hai mt tip xc]",
    "",
    "**EM C TH**",
    "Thuyt trnh v ch li, tc hi ca ma st trong an ton giao thng ng b.",
    "",
    "76"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B19', 'Bài 19. Lực cản và lực nâng', 78, 7, $JSON$
{
  "content": [
    "# Bi 19 LC CN V LC NNG",
    "",
    "**Khi ng:**",
    "*Mt hng  t s dng cng loi ng c cho hai chic  t A v B c khi lng nh nhau. Khi cho hai  t ny chy th nghim trn cng qung ng 100 km, vi cng tc  72 km/h, cc k s thy rng  t A tiu th t nhin liu hn nhiu so vi  t B.*",
    "*Ti sao li c s khc bit nh vy?*",
    "[Hnh nh 2 chic  t ang chy.  t A thon di,  t B vung vn]",
    "",
    "## I. LC CN CA CHT LU",
    "**1. Lc cn**",
    "Thng thng thut ng *cht lu* c dng  ch cht lng v cht kh.",
    "Mi vt chuyn ng trong cht lu lun chu tc dng bi lc cn ca cht lu. Lc ny ngc hng chuyn ng v cn tr chuyn ng ca vt (Hnh 19.1).",
    "[Hnh 19.1. V d v lc cn ca cht lu.",
    "a) Tn la bay ln, lc cn khng kh hng xung.",
    "b) Ngi i xe p hng sang phi, lc cn khng kh hng tri.",
    "c) Nhy d, ngi ri xung, lc cn khng kh hng ln.",
    "d) Tu thu ang chy sang phi, lc cn ca nc hng tri]",
    "",
    "**2. Lc cn ph thuc vo nhng yu t no?**",
    "**Hot ng:**",
    "a) Bng cm nhn trc gic, em th on xem  ln ca lc cn ph thuc vo nhng yu t no?",
    "b) Em hy tm nhng th nghim  chng minh cho nhng d on ca em.",
    "",
    "**? Cu hi:**",
    "1. Trong hnh  phn m u bi hc,  t no chu lc cn nh hn?",
    "2. Nu thm mt s v d chng t lc cn ca khng kh lin quan n hnh dng v tc  ca vt.",
    "",
    "77",
    "CHNG III  NG LC HC",
    "",
    "**Hot ng:**",
    "Quan st Hnh 19.2 v tho lun  lm sng t v lc cn ca nc ph thuc vo hnh dng ca cc vt chuyn ng trong nc nh th no.",
    "[Hnh 19.2. Lc cn ca nc i vi cc vt chuyn ng.",
    "a) Tu cao tc.",
    "b) M t trn nc.",
    "c) Vn ng vin bi.",
    "d) C heo]",
    "",
    "Nhn xt: Lc cn ca cht lu (khng kh, nc) ph thuc vo *hnh dng* v *tc * ca vt.",
    "",
    "## II. LC NNG CA CHT LU",
    "Khi vt chuyn ng trong nc hay trong khng kh th ngoi lc cn (ca khng kh, ca nc), vt cn chu tc dng ca lc nng.",
    "Hnh 19.3 cho thy, nu cnh my bay nghing i mt cht, chch theo lung gi, th tng thm lc nng tc dng vung gc vi mt di ca cnh  nng my bay ln cao.",
    "[Hnh 19.3. Cc lc tc dng ln my bay. Trng lc $\\vec{P}$ hng xung, lc nng $\\vec{F}_n$ hng ln, lc y $\\vec{F}_d$ hng ti trc, lc cn $\\vec{F}_c$ hng ra sau]",
    "",
    "Sau y l mt s tnh hung trong thc tin, cho thy khi cc vt  trong cht lu, chng chu tc dng ca lc nng. Vic gii thch lc nng tc dng ln vt s trnh by  bi 35 ca chng VII.",
    "Nh c lc nng:",
    " My bay c th di chuyn trong khng kh (Hnh 19.3).",
    " Tu thuyn c th ni v di chuyn c trn mt nc (Hnh 19.4).",
    " Khinh kh cu l lng trn khng trung (Hnh 19.5a).",
    " Nhiu sinh vt bay ln d dng trong khng kh (Hnh 19.5b).",
    "[Hnh 19.4. Tu ni trn mt nc. Trng lc $\\vec{P}$ hng xung, lc nng $\\vec{F}_A$ hng ln]",
    "",
    "**! Ch :** Khi vt ri trong cht lu di tc dng ca trng lc v lc cn ca cht lu th n mt lc no  vt s t ti vn tc gii hn v s chuyn ng u vi vn tc ny.",
    "",
    "**! Lc y Archimedes**",
    "Lc y Archimedes hc  mn Khoa hc t nhin lp 8 l trng hp ring ca lc nng vt ng yn trong cht lu.",
    "Cng thc tnh lc y Archimedes:",
    "$F_A = \\rho . g . V$",
    "Trong :",
    "$F_A$: lc y Archimedes (N).",
    "$\\rho$: khi lng ring ca cht lng (kg/m$^3$).",
    "V: th tch phn cht lng b vt chim ch (m$^3$).",
    "",
    "78",
    "CHNG III  NG LC HC",
    "",
    "**? Cu hi:**",
    "1. Chun chun c th bay ln trong khng trung. Ti sao chng khng b ri xung t do trng lc (Hnh 19.5b)?",
    "2. Biu din cc lc tc dng ln mt kh cu ang l lng trong khng kh (Hnh 19.5a).",
    "3. Hnh 19.6 biu din cc vct lc tc dng ln mt my bay ang bay ngang   cao n nh vi tc  khng i. Nu khi lng tng cng ca my bay l 500 tn th lc nng c  ln bao nhiu?",
    "4. Nu nhng im khc bit gia lc cn v lc nng.",
    "[Hnh 19.5.",
    "a) Khinh kh cu l lng.",
    "b) Con chun chun ang bay]",
    "[Hnh 19.6. My bay ang bay, c 4 lc tc dng: Lc nng ca khng kh, Trng lc, Lc y ca ng c, Lc cn ca khng kh]",
    "",
    "**EM  HC**",
    "- Lc cn ca cht lu c tc dng tng t nh lc ma st, chng lm chuyn ng ca cc vt b chm li. Lc cn ph thuc vo hnh dng v tc  ca vt.",
    "- Lc nng ca cht lu gip khinh kh cu l lng trn khng trung, my bay di chuyn trong khng kh, cho php tu thuyn di chuyn trn mt nc,...",
    "",
    "**EM C TH**",
    "1. Gii thch ti sao cc phng tin giao thng tc  cao li cn c hnh con thoi.",
    "2. Ch ra c lc nng v lc cn khi my bay h cnh hoc ct cnh.",
    "",
    "**EM C BIT?**",
    "**Hnh dng kh ng hc l g?**",
    "Ngi u tin khi xng m hnh kh ng hc trn  t l nh thit k ni ting Eduard Rumpler, cha  ca ngnh hng khng c.",
    "Vo nhng nm 1930  1940, cc cuc ua  t bng nhin tr thnh phong tro rt c a chung. Cc k s  c gng sn xut nhng chic xe chuyn ng cng nhanh cng tt. Tuy nhin, ti ng ua Le Mans,  nc Php nm 1937, chic  t c dung tch ng c 1,7 lt  gy sc vi hai chin thng ngon mc trc nhng  t c dung tch ng c 2 lt. B quyt v sau c cng b: chic  t chin thng l nh ci tin cng ngh v hnh dng sao cho lc cn nh nht.",
    "[Hnh 19.7. Cc nh sn xut  t thng xuyn nghin cu v ci tin  xe c hnh dng kh ng hc sao cho lc cn nh nht]",
    "T  n nay, ngnh cng nghip  t  tin mt bc rt di. Hu ht cc kiu xe ngy nay u ch trng n bin php ti u hnh dng con thoi (trong khoa hc gi l hnh kh ng hc) v iu   gip cho xe t hao ph nhin liu hn xa.",
    "",
    "79"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B20', 'Bài 20. Một số ví dụ về cách giải các bài toán thuộc phần động lực học', 81, 8, $JSON$
{
  "content": [
    "# Bi 20 MT S V D V CCH GII CC BI TON THUC PHN NG LC HC",
    "",
    "## I. CC BC GII CHNH",
    "1. Chn vt kho st chuyn ng. Biu din cc lc tc dng ln vt, trong  lm r phng, chiu v im t ca tng lc.",
    "2. Chn hai trc vung gc Ox v Oy; trong  trc Ox cng hng vi chuyn ng ca vt hay cng hng vi lc ko khi vt ng yn. Phn tch cc lc theo hai trc ny. p dng nh lut 2 Newton theo hai trc to  Ox v Oy.",
    "$\\begin{cases} Ox: F_x = F_{1x} + F_{2x} + \\dots = m.a_x & (1) \\\\ Oy: F_y = F_{1y} + F_{2y} + \\dots = 0 & (2) \\end{cases}$",
    "3. Gii h phng trnh (1) v (2)  tm gia tc hay tm lc, tu tng bi ton.",
    "",
    "## II. CC LOI BI TON",
    "**1. Bi ton xc nh gia tc ca vt khi bit lc tc dng vo vt**",
    "*V d.* Mt ngi y mt thng hng, khi lng 50 kg, trt trn sn nh. Lc y c phng nm ngang vi  ln l 180 N. Tnh gia tc ca thng hng, bit h s ma st trt gia thng hng v sn nh l 0,25. Ly g = 9,8 m/s$^2$.",
    "*Gii*",
    "Thng hng chu tc dng ca bn lc: trng lc $\\vec{P}$, lc y $\\vec{F}$, phn lc $\\vec{N}$ v lc ma st trt $\\vec{F}_{\\text{ms}}$ ca sn (Hnh 20.1a).",
    "[Hnh 20.1.",
    "a) Biu din cc lc trn thng hng.",
    "b) Biu din cc lc trn cht im trong h to  Oxy]",
    "Coi thng hng nh mt cht im (Hnh 20.1b).",
    "p dng nh lut 2 Newton cho chuyn ng ca vt theo hai trc Ox, Oy:",
    "$\\begin{cases} Ox: F_x = F - F_{\\text{ms}} = m.a_x = m.a & (1) \\\\ Oy: F_y = N - P = 0 & (2) \\\\ F_{\\text{ms}} = \\mu.N & (3) \\end{cases}$",
    "",
    "Gii h phng trnh:",
    "T (2) $\\Rightarrow N = P = m.g = 50.9,8 = 490$ N",
    "$F_{\\text{ms}} = \\mu.N = 0,25.490 = 122,5$ N",
    "$a = \\frac{F - F_{\\text{ms}}}{m} = \\frac{180 - 122,5}{50} = 1,15$ m/s$^2$.",
    "Thng hng trt vi gia tc $a = 1,15$ m/s$^2$ cng chiu vi trc Ox.",
    "",
    "80",
    "CHNG III  NG LC HC",
    "",
    "**2. Bi ton xc nh lc tc dng vo vt khi bit gia tc**",
    "*V d 1.* Mt ngi dng dy buc  ko mt thng g theo phng nm ngang bng mt lc $\\vec{F}$ (Hnh 20.2). Khi lng ca thng l 35 kg. H s ma st gia sn v y thng l 0,3. Ly g = 9,8 m/s$^2$.",
    "[Hnh 20.2. Ngi ko thng g bng dy theo phng ngang]",
    "Tnh  ln ca lc ko trong hai trng hp:",
    "a) Thng trt vi gia tc 0,2 m/s$^2$.",
    "b) Thng trt u.",
    "*Gii*",
    "Thng chu tc dng ca bn lc: trng lc $\\vec{P} = m.\\vec{g}$, lc ko $\\vec{F}$, phn lc $\\vec{N}$ v lc ma st trt $\\vec{F}_{\\text{ms}}$ ca mt sn (Hnh 20.3a).",
    "[Hnh 20.3.",
    "a) Biu din cc lc trn thng g.",
    "b) Biu din cc lc trn cht im trong h to  Oxy]",
    "",
    "Coi thng nh mt cht im (Hnh 20.3b) v p dng nh lut 2 Newton cho cc lc thnh phn theo cc phng Ox, Oy.",
    "$\\begin{cases} Ox: F_x = F - F_{\\text{ms}} = m.a_x = m.a & (1) \\\\ Oy: F_y = N - P = 0 & (2) \\\\ F_{\\text{ms}} = \\mu.N \\end{cases}$",
    "",
    "Gii h phng trnh:",
    "T (2) $\\Rightarrow N = m.g$",
    "Suy ra: $F_{\\text{ms}} = \\mu.N = \\mu.m.g$",
    "Thay vo (1), ta c:",
    "$F = m.a + \\mu.m.g$",
    "$F = m(a + \\mu.g)$",
    "a) Thng trt vi gia tc a = 0,2 m/s$^2$",
    "$F = m(a + \\mu.g) = 35(0,2 + 0,3.9,8) = 109,9$ N.",
    "b) Thng trt u (a = 0)",
    "$F = \\mu.m.g = 0,3.35.9,8 = 102,9$ N.",
    "",
    "81",
    "CHNG III  NG LC HC",
    "",
    "*V d 2.* Mt chic hp g c th trt khng vn tc ban u t u trn ca mt tm g di L = 2 m. Tm g t nghing $30^\\circ$ so vi phng ngang. H s ma st gia y hp v mt g l 0,2. Ly g = 9,8 m/s$^2$. Hi sau bao lu th hp trt xung n u di ca tm g?",
    "*Gii*",
    "Hp (coi l cht im) chu tc dng ca ba lc: trng lc $\\vec{P}$, phn lc $\\vec{N}$ v lc ma st trt $\\vec{F}_{\\text{ms}}$ (Hnh 20.4a).",
    "[Hnh 20.4.",
    "a) Biu din cc lc trn hp g trn mt phng nghing.",
    "b) Biu din v phn tch cc lc trn h trc Oxy, Ox song song mt phng nghing]",
    "Phn tch trng lc $\\vec{P}$ thnh hai lc thnh phn $\\vec{P}_x, \\vec{P}_y$ (Hnh 20.4b) v p dng nh lut 2 Newton theo hai trc Ox, Oy:",
    "$\\begin{cases} Ox: F_x = m.g.\\sin\\alpha - F_{\\text{ms}} = m.a_x = m.a & (1) \\\\ Oy: F_y = N - m.g.\\cos\\alpha = 0 & (2) \\\\ F_{\\text{ms}} = \\mu.N \\end{cases}$",
    "",
    "Gii h phng trnh: $a = g(\\sin\\alpha - \\mu\\cos\\alpha)$",
    "Thay s, ta c: $a = g(\\sin 30^\\circ - 0,2\\cos 30^\\circ) \\approx 3,2$ m/s$^2$",
    "Hp trt xung vi gia tc $a = 0,64$ m/s$^2$ (! Li sch in, s ng l 3,2), cng chiu vi trc Ox.",
    "p dng cng thc:",
    "$L = \\frac{1}{2}at^2 \\Rightarrow t = \\sqrt{\\frac{2L}{a}} = \\sqrt{\\frac{2.2}{3,2}} \\approx 1,1$ s.",
    "",
    "## III. BI TP T GII",
    "1. Ngi ta y mt ci thng c khi lng 55 kg theo phng ngang vi lc 220 N lm thng chuyn ng trn mt phng ngang. H s ma st trt gia thng v mt phng l 0,35. Tnh gia tc ca thng. Ly g = 9,8 m/s$^2$.",
    "2. Mt quyn sch t trn mt bn nghing v c th cho trt xung. Cho bit gc nghing $\\alpha = 30^\\circ$ so vi phng ngang v h s ma st gia quyn sch v mt bn l $\\mu = 0,3$. Ly g = 9,8 m/s$^2$. Tnh gia tc ca quyn sch v qung ng i c ca n sau 2 s.",
    "3. Mt hc sinh dng dy ko mt thng sch nng 10 kg chuyn ng trn mt sn nm ngang. Dy nghing mt gc chch ln trn $30^\\circ$ so vi phng ngang. H s ma st trt gia y thng v mt sn l $\\mu = 0,2$ (ly g = 9,8 m/s$^2$). Hy xc nh  ln ca lc ko  thng sch chuyn ng thng u.",
    "4. Hai vt c khi lng ln lt l $m_1 = 5$ kg v $m_2 = 10$ kg c ni vi nhau bng mt si dy khng dn v c t trn mt mt sn nm ngang. Ko vt 1 bng mt lc $\\vec{F}$ nm ngang c  ln F = 45 N. H s ma st gia mi vt v mt sn l $\\mu = 0,2$. Ly g = 9,8 m/s$^2$. Tnh gia tc ca mi vt v lc cng ca dy ni.",
    "",
    "82"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B21', 'Bài 21. Moment lực. Cân bằng của vật rắn', 84, 9, $JSON$
{
  "content": [
    "# Bi 21 MOMENT LC. CN BNG CA VT RN",
    "",
    "**Khi ng:**",
    "*Nu dng tay  sit cht mt ai c th vic  rt kh, tuy nhin vi dng c thch hp nh c l th vic sit cht ai c tr nn d dng.*",
    "*Tc dng ca dng c ny thay i th no nu ta tng  ln ca lc hoc s dng c l di hn?*",
    "[Hnh nh dng c l vn ai c]",
    "",
    "## I. MOMENT LC",
    "**1. Tc dng lm quay ca lc**",
    " lp 8 cc em  hc trong mn KHTN v tc dng lm quay ca lc. Mun m t chnh xc tc dng ca ba khi dng  nh inh (Hnh 21.1a), ta phi a vo khi nim mi l *cnh tay n* ca lc.",
    "Cnh tay n ca lc l khong cch t trc quay n gi ca lc, k hiu l d (Hnh 21.1b).",
    "[Hnh 21.1. Dng ba nh inh.",
    "a) Ngi cm ba nh inh.",
    "b) Biu din lc $\\vec{F}$ v cnh tay n d t trc quay O n gi ca lc]",
    "",
    "**? Cu hi:**",
    "1. M t thao tc dng ba  nh inh.",
    "2. Lc $\\vec{F}$ nn t vo u trn cn ba  nh inh c d dng? Khi  cnh tay n (d) ca lc ln hay nh?",
    "3. Tc dng lm quay ca lc ph thuc nhng yu t no?",
    "",
    "**2. Moment lc**",
    "V d trn cho php ta ly tch F.d lm i lng c trng cho tc dng lm quay ca lc v gi l *moment lc*, k hiu l M.",
    "*Moment lc i vi trc quay l i lng c trng cho tc dng lm quay ca lc v c o bng tch ca lc vi cnh tay n ca n.*",
    "M = F.d",
    "n v ca moment lc l niutn mt (N.m).",
    "",
    "**? Cu hi:**",
    "Hnh 21.2 m t mt chic thc mnh OA, ng cht, di 50 cm, c th quay quanh trc quay c nh  u O.",
    "1. Trong cc tnh hung  Hnh 21.2a, b, thc OA quay theo chiu kim ng h hay ngc chiu kim ng h?",
    "2. Tnh moment lc ng vi mi tnh hung trong Hnh 21.2.",
    "[Hnh 21.2. Thc OA quay quanh O.",
    "a) Lc 4N tc dng  im A thng ng xung di.",
    "b) Lc 2N tc dng  im A nghing gc $20^\\circ$ so vi OA]",
    "",
    "83",
    "CHNG III  NG LC HC",
    "",
    "## II. QUY TC MOMENT LC",
    "**1. Th nghim**",
    "Dng mt a trn c trc quay i qua tm O, trn mt a c nhng l dng  treo nhng qu cn. Tc dng vo a nhng lc $\\vec{F}_1$ v $\\vec{F}_2$ nm trong mt phng ca a sao cho a ng yn (Hnh 21.3). Khi  moment ca lc $\\vec{F}_1$  cn bng vi moment ca lc $\\vec{F}_2$.",
    "V  ln ta c: $F_1.d_1 = F_2.d_2$",
    "[Hnh 21.3. Th nghim v quy tc moment lc vi a trn quay quanh tm]",
    "",
    "**? Cu hi:**",
    "1. Nu b lc $\\vec{F}_1$ th a quay theo chiu no?",
    "2. Nu b lc $\\vec{F}_2$ th a quay theo chiu no?",
    "3. Khi a cn bng lp tch $F_1.d_1$ v $F_2.d_2$ ri so snh.",
    "",
    "**2. Quy tc moment lc (hay iu kin cn bng ca mt vt c trc quay c nh)**",
    "Mun cho mt vt c trc quay c nh  trng thi cn bng, th tng cc moment lc c xu hng lm vt quay theo chiu kim ng h phi bng tng cc moment lc c xu hng lm vt quay ngc chiu kim ng h.",
    "*Nu chn mt chiu quay lm chiu dng th iu kin cn bng ca vt c trc quay c nh l: Tng cc moment lc tc dng ln vt (i vi mt im bt k) bng 0.*",
    "$\\Sigma M = 0$",
    "",
    "**? Cu hi:**",
    "a) S dng kin thc v moment lc gii thch v sao chic bp bnh ng cn bng.",
    "b) Cho bit ngi ch (bn phi) c trng lng $P_2 = 300$ N, khong cch $d_2 = 1$ m, cn ngi em c trng lng $P_1 = 200$ N. Hi khong cch $d_1$ phi bng bao nhiu  bp bnh cn bng nm ngang?",
    "[Hnh 21.4. Bp bnh vi 2 tr em ngi  2 bn trc quay]",
    "",
    "## III. NGU LC",
    "**1. Ngu lc l g?**",
    "Ngu lc l h hai lc song song, ngc chiu, c  ln bng nhau v cng t vo mt vt.",
    "Ngu lc tc dng ln mt vt ch lm cho vt quay ch khng tnh tin.",
    "Cc Hnh 21.5a, b l nhng v d v ngu lc.",
    "[Hnh 21.5. Dng tay vn vi nc, iu khin tay li  t, ta tc dng vo vt mt ngu lc.",
    "a) Vn vi nc.",
    "b) V lng  t]",
    "",
    "**2. Moment ca ngu lc**",
    "V hai lc $\\vec{F}_1$ v $\\vec{F}_2$ u lm cho vt quay theo mt chiu nn moment ca ngu lc M c xc nh:",
    "$M = F_1.d_1 + F_2.d_2$ hay $M = F.d$",
    "Trong  F l  ln ca mi lc, d l khong cch gia hai gi ca lc, gi l cnh tay n ca ngu lc (Hnh 21.6).",
    "[Hnh 21.6. M hnh ngu lc. $\\vec{F}_1$ v $\\vec{F}_2$ ngc chiu, khong cch d]",
    "",
    "84",
    "CHNG III  NG LC HC",
    "",
    "## IV. IU KIN CN BNG TNG QUT CA VT RN",
    "**Hot ng:**",
    "1. t mt chic thc di trn bn. Cho mt bn nng mt u thc ln v gi yn (Hnh 21.7). Hi:",
    " Khi thay i lc nng $\\vec{F}$ ta thy thc quay quanh trc no?",
    " Khi thc ang ng yn  v tr nh Hnh 21.7, ta c th p dng quy tc moment lc c khng v p dng nh th no?",
    "[Hnh 21.7. Nng mt u thc trn mt bn, lc $\\vec{F}$ hng ln  B, trng lc $\\vec{P}$  gia, im ta  A]",
    "2. Khi mt vt khng c im ta c nh. V d, thanh cng ta vo bc tng nhn, u di ca thanh t trn mt bn nhm (Hnh 21.8). Khi  ta c th p dng c quy tc moment lc c khng v p dng nh th no?",
    "*Gi :* Chn u A ca thanh  vit quy tc moment.",
    "[Hnh 21.8. Thanh AB ta vo tng nhn thng ng, gc A trn sn nhm. Cc lc: phn lc tng $\\vec{N}_B$  B, phn lc sn $\\vec{N}_A$, lc ma st $\\vec{F}_{\\text{msn}}$  A, trng lc $\\vec{P}$  trng tm G]",
    "",
    "Ta  bit, vt ng yn th trng lc phi cn bng vi cc lc khc tc dng ln vt. Nh vy, iu kin cn bng ca mt vt rn l:",
    " Tng cc lc tc dng ln vt bng 0.",
    " Tng cc moment lc tc dng ln vt i vi mt im bt k chn lm trc quay bng 0 (nu chn mt chiu quay lm chiu dng).",
    "",
    "**? Cu hi:**",
    "p dng iu kin cn bng tng qut vo thanh cng ta tng (Hnh 21.8).",
    "a) Vit iu kin cn bng th nht.",
    "b) Vit iu kin cn bng th hai i vi trc quay A.",
    "",
    "**EM  HC**",
    "- Moment lc i vi trc quay l i lng c trng cho tc dng lm quay ca lc v c o bng tch ca lc vi cnh tay n ca n: M = F.d",
    "- n v ca moment lc l niutn mt (N.m).",
    "- Tc dng ca ngu lc ln vt ch lm quay vt.",
    "- Moment ngu lc: M = F.d = F($d_1$ + $d_2$).",
    "- iu kin cn bng ca mt vt rn: Tng cc lc tc dng ln vt bng 0 v tng moment lc tc dng ln vt (i vi mt im bt k chn lm trc quay) bng 0.",
    "",
    "**EM C TH**",
    "Gii thch c s cn bng moment trong Hnh 21.9.",
    "[Hnh 21.9. Bn tay nng t. Lc c bp $\\vec{F}$ nng ln, trng lng qu t $\\vec{P}$ hng xung, im ta  khuu tay O]",
    "",
    "85"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B22', 'Bài 22. Thực hành: Tổng hợp lực', 87, 10, $JSON$
{
  "content": [
    "# Bi 22 THC HNH: TNG HP LC",
    "",
    "**Khi ng:**",
    "*Hai lc $\\vec{F}_1$ v $\\vec{F}_2$ tc dng ln mt vt. Lm th no xc nh hp lc ca hai lc ny bng dng c th nghim?*",
    "",
    "## I. TNG HP HAI LC NG QUY",
    "**1. Dng c th nghim (Hnh 22.1)**",
    " Bng thp (1).",
    " Hai lc k ng 5 N, c  nam chm (2).",
    " Thc o gc c  chia nh nht $1^\\circ$ c in trn tm mica trong sut (3).",
    " Mt  nam chm c mc  buc dy cao su (4).",
    " Dy ch bn v mt dy cao su (5).",
    " Gi  c trc $\\Phi$10 mm, cm ln  ba chn (6).",
    " Bt dng  nh du.",
    "[Hnh 22.1. B th nghim tng hp hai lc ng quy. nh s t 1 n 6 cc b phn]",
    "",
    "**2. Thit k phng n th nghim**",
    "Xc nh lc tng hp ca hai lc ng quy.",
    "",
    "**? Cu hi:**",
    "Gn  nam chm ln bng thp, mc si dy cao su vo  nam chm, t hai lc k ln bng thp v mc hai lc k vo u cn li ca dy cao su. Dch chuyn hai lc k  ko si dy cao su lm dy dn ra mt khong v tho lun:",
    "1. Lm th no  hai lc $\\vec{F}_1$ v $\\vec{F}_2$ ng quy?",
    "2. Lm th no thay th tc dng ca hai lc $\\vec{F}_1$ v $\\vec{F}_2$ bng mt lc $\\vec{F}$ m dy cao su vn dn mt on v hng nh ban u?",
    "3. Lm th no xc nh lc tng hp ca hai lc $\\vec{F}_1$ v $\\vec{F}_2$?",
    "",
    "**3. Tin hnh th nghim**",
    "*A  Xc nh hai lc thnh phn $F_1, F_2$*",
    "1. t bng thp ln gi . Gn  nam chm c mc buc si dy cao su vo mc. Buc si dy ch vo dy cao su. Mc hai lc k vo u cn li ca si ch v gn hai lc k ln bng.",
    "",
    "86",
    "CHNG III  NG LC HC",
    "",
    "2. Gn thc o gc ln bng bng nam chm (Hnh 22.2a).",
    "3. Di chuyn hai lc k sao cho dy cao su v cc on dy ch song song vi mt phng v tm O ca thc trng vi giao im ca si dy v dy cao su.",
    "4. nh du ln bng st im $A_1$ ca u dy cao su, phng ca hai lc $\\vec{F}_1$ v $\\vec{F}_2$ do hai lc k tc dng vo dy.",
    "5. Ghi cc s liu $F_1, F_2$ t s ch ca hai lc k v gc $\\alpha$ gia hai lc vo Bng 22.1.",
    "6. Lp li cc bc th nghim 3, 4, 5 hai ln na. Ghi s liu vo Bng 22.1.",
    "",
    "*B  Xc nh lc tng hp $F_{tn}$ ca hai lc $F_1, F_2$ bng th nghim*",
    "7. Tho mt lc k v b tr th nghim nh Hnh 22.2b.",
    "8. Di chuyn lc k sao cho u dy cao su trng im $A_1$  nh du v ghi gi tr ca lc $F_{tn}$ vo Bng 22.1.",
    "9. Lp li bc 8 hai ln na.",
    "",
    "*C  Xc nh lc tng hp theo l thuyt $F_{lt}$*",
    "10. Tnh gi tr ca $F_{lt}$ theo nh l hm s cosin v ghi vo Bng 22.1.",
    "",
    "[Hnh 22.2. Th nghim tng hp hai lc ng quy.",
    "a) o lc $\\vec{F}_1$ v $\\vec{F}_2$ cng tc dng.",
    "b) o lc tng hp bng 1 lc k]",
    "",
    "**4. Kt qu th nghim**",
    "**Bng 22.1.** Tng hp hai lc ng quy",
    "| Ln | $F_1$ (N) | $F_2$ (N) | Gc $\\alpha$ | $F_{tn}$ (N) | $F_{lt}$ (N) |",
    "|---|---|---|---|---|---|",
    "| 1 | | | | | |",
    "| 2 | | | | | |",
    "| 3 | | | | | |",
    "",
    "*X l kt qu th nghim*",
    "Tnh gi tr trung bnh v sai s:",
    "$\\overline{F}_{\\text{tn}} = \\dots; \\Delta\\overline{F}_{\\text{tn}} = \\dots; \\overline{F}_{\\text{lt}} = \\dots; \\Delta\\overline{F}_{\\text{lt}} = \\dots$",
    "",
    "**! Ch :** Khi di chuyn lc k lun m bo cc on si dy v dy cao su lun nm trn cng mt phng.",
    "",
    "**Hot ng:** Nhn xt v nh gi kt qu th nghim",
    "1. So snh cc kt qu hp lc thu c bng l thuyt v bng th nghim, rt ra kt lun.",
    "2. Em c th  xut mt phng n th nghim khc  tin hnh th nghim tng hp hai lc ng quy.",
    "",
    "87",
    "CHNG III  NG LC HC",
    "",
    "## II. TNG HP HAI LC SONG SONG",
    "**1. Dng c th nghim (Hnh 22.3)**",
    " Bng thp (1).",
    " Hai l xo xon chu c lc ko ti a l 5 N, di khong 60 mm (2).",
    " Thanh treo nh, cng, di 400 mm. Trn thanh c gn thc v ba con trt c gn mc treo (3).",
    " Cc qu nng c khi lng bng nhau 50 g (4).",
    " Hai  nam chm  gn l xo (5).",
    " Gi  c trc $\\Phi$10 mm, cm ln  ba chn (6).",
    " Bt dng  nh du.",
    "[Hnh 22.3. B th nghim tng hp hai lc song song cng chiu. nh s 1 n 6 cc b phn]",
    "",
    "**2. Thit k phng n th nghim**",
    "Xc nh lc tng hp ca hai lc m gi ca cc lc  song song.",
    "",
    "**Hot ng:**",
    "Gn hai  nam chm ln bng thp, treo thanh kim loi ln hai  nam chm bng hai l xo, treo cc qu nng vo hai u thanh, lm l xo dn ra mt khong v tho lun:",
    "1. Lm th no thay th hai lc $\\vec{F}_1$ v $\\vec{F}_2$ bng mt lc $\\vec{F}$ m thanh vn  v tr nh khi chu tc dng ca hai lc $\\vec{F}_1$ v $\\vec{F}_2$?",
    "2. Lm th no  hai lc $\\vec{F}_1$ v $\\vec{F}_2$ song song.",
    "3. Lm th no xc nh lc tng hp ca hai lc $\\vec{F}_1, \\vec{F}_2$.",
    "",
    "**3. Tin hnh th nghim**",
    "1. Gn hai  nam chm ln bng thp, sau  treo thanh kim loi ln hai  nam chm bng hai l xo.",
    "2. Treo cc qu nng vo hai con trt c gn mc treo ln thanh kim loi.",
    "3. Dng bt d nh du v tr thanh v v tr A, B ln bng thp. Ghi li gi tr trng lng $F_1$ v $F_2$ v  di AB vo Bng 22.2.",
    "4. Tho cc qu nng v mc tt c qu nng  dng vo mt mc treo trn thanh kim loi.",
    "5. iu chnh con trt sao cho v tr ca thanh kim loi trng vi v tr ban u  c nh du.",
    "6. Ghi cc gi tr F tng ng vi trng lng cc qu nng vo Bng 22.2.",
    "7. o v ghi gi tr  di $OA_{tn}$ t im O treo cc qu nng ti A vo Bng 22.2.",
    "8. Lp li cc bc th nghim 2, 3, 4, 5, 6, 7 thm hai ln na.",
    "9. Tnh gi tr $OA_{lt}$ theo l thuyt bng cng thc",
    "$\\frac{F_1}{F_2} = \\frac{d_2}{d_1} = \\frac{OB}{OA_{lt}} = \\frac{AB - OA_{lt}}{OA_{lt}}$ v in vo Bng 22.2.",
    "",
    "[Hnh 22.4. Th nghim tng hp hai lc song song.",
    "a) Treo qu nng vo 2 mc  A v B.",
    "b) Treo tt c qu nng vo 1 mc  O sao cho thanh  v tr c]",
    "",
    "88",
    "CHNG III  NG LC HC",
    "",
    "**! Ch :**",
    " Nn chn s qu nng hai bn khng nh nhau.",
    " V tr A v B nn chn trng vi cc vch chia ca thc  trnh sai s khi o.",
    "",
    "**4. Kt qu th nghim**",
    "**Bng 22.2.** Tng hp hai lc song song cng chiu",
    "| Ln | $F_1$ (N) | $F_2$ (N) | AB | F | $OA_{tn}$ | $OA_{lt}$ |",
    "|---|---|---|---|---|---|---|",
    "| 1 | | | | | | |",
    "| 2 | | | | | | |",
    "| 3 | | | | | | |",
    "",
    "X l kt qu th nghim: $\\overline{OA}_{\\text{tn}} = \\dots; \\Delta\\overline{OA}_{\\text{tn}} = \\dots$",
    "",
    "**Hot ng:** Nhn xt v nh gi kt qu th nghim",
    "1. So snh cc kt qu hp lc tng hp thu c bng tnh ton v bng th nghim, rt ra kt lun.",
    "2. Em c th  xut mt phng n th nghim khc  tin hnh th nghim tng hp hai lc song song cng chiu.",
    "",
    "**EM  HC**",
    "- Tin hnh th nghim tng hp hai lc ng quy, hai lc song song  nghim li cc quy tc tng hp lc.",
    "",
    "**EM C TH**",
    "Ch to mt chic cn thng bng n gin bng cc vt liu d tm (Hnh 22.5):",
    "1. Mt thanh thc g c vch chia.",
    "2. Mt chai nc 500 mL.",
    "3. Cc dy treo.",
    "4. Vt cn cn.",
    "[Hnh 22.5. Thit k ch to chic cn n gin. Thanh g (1) treo vt (4) v chai nc (2) qua cc dy treo (3)]",
    "",
    "**EM C BIT?**",
    "n by l loi my c n gin c s dng nhiu trong i sng  bin i lc tc dng ln vt nh s dng x beng  nng vt, n gnh  gnh cc vt.",
    "",
    "89"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B23', 'Bài 23. Năng lượng. Công cơ học', 92, 1, $JSON$
{
  "content": [
    "# Bi 23 NNG LNG. CNG C HC",
    "",
    "**Khi ng:**",
    "[Hnh nh vn ng vin nng t t v tr 1 n v tr 4]",
    "*Trong cc ng tc nng t t v tr (1) sang v tr (2), t v tr (2) sang v tr (3), t v tr (3) sang v tr (4)  hnh trn:*",
    "*- C nhng qu trnh truyn v chuyn ho nng lng no?*",
    "*- ng tc no c thc hin cng, khng thc hin cng?*",
    "",
    "## I. NNG LNG",
    " trng THCS cc em  bit:",
    " Mi hin tng xy ra trong t nhin u cn c nng lng di cc dng khc nhau nh: c nng, ho nng, nhit nng, in nng, nng lng nh sng, nng lng m thanh, nng lng nguyn t.",
    " Nng lng c th chuyn ho t dng ny sang dng khc hoc truyn t vt ny sang vt khc.",
    " Nng lng khng t sinh ra hoc t mt i m ch chuyn ho t dng ny sang dng khc hoc truyn t vt ny sang vt khc.",
    "",
    "**? Cu hi:**",
    "1. Khi un nc bng m in th c nhng qu trnh truyn v chuyn ho nng lng no xy ra?",
    "2. Khi xoa hai tay vo nhau cho nng th c nhng qu trnh truyn v chuyn ho nng lng no xy ra?",
    "3. Mt qu bng cao su c nm t  cao h xung t cng v b ny ln. Sau mi ln ny ln,  cao gim dn, ngha l c nng gim dn. iu  c tri vi nh lut bo ton nng lng khng? Ti sao? Hy d on xem cn c hin tng g na xy ra vi qu bng ngoi hin tng b ny ln v ri xung.",
    "4. C s truyn v chuyn ho nng lng no trong qu trnh bn pho hoa?",
    "",
    "**EM C BIT?**",
    "C th phn nng lng thnh hai loi l ng nng (nng lng ca vt do chuyn ng m c) v th nng (nng lng lu tr ca vt). V d, nhit nng l nng lng chuyn ng hn lon ca cc phn t; in nng l nng lng ca chuyn ng c hng ca cc in tch di tc dng ca in trng; nng lng vt c khi  mt  cao so vi mt t l th nng trng trng,...",
    "",
    "91",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "*Th nghim ca Joule v s truyn, chuyn ho v bo ton nng lng*",
    "Th nghim mang tnh lch s c James Joule thc hin vo nhng nm 1844  1854 nhm minh ho nh lut bo ton nng lng. S  th nghim c m t trong Hnh 23.1. Khi cho vt nng chuyn ng i xung, dy ni s lm cho trc quay v cnh qut quay theo. Ma st gia cnh qut v nc lm cho nc nng ln.",
    " y c s truyn nng lng t vt nng sang nc, c th l s chuyn ho t c nng sang nhit nng.",
    "Th nghim  cho thy c nng ca vt nng gim i bao nhiu th nhit nng ca nc tng ln by nhiu. iu  chng t, *trong qu trnh truyn nng lng t vt ny sang vt khc, chuyn ho nng lng t dng ny sang dng khc, nng lng lun c bo ton.*",
    "[Hnh 23.1. S  th nghim minh ho nh lut bo ton nng lng. nh s cc b phn t 1 n 5: (1) Vt nng, (2) Dy ni, (3) Trc quay, (4) Cnh qut, (5) Nhit k]",
    "",
    "**Hot ng:**",
    "Hy tho lun nhm  tm thm v d minh ho cho cc qu trnh chuyn ho nng lng sau y:",
    "a) in nng chuyn ho thnh nhit nng.",
    "b) Nhit nng chuyn ho thnh in nng.",
    "c) Quang nng chuyn ho thnh in nng.",
    "d) Quang nng chuyn ho thnh ho nng.",
    "",
    "## II. CNG C HC",
    "**1. Thc hin cng**",
    "Nng lng c th truyn t vt ny sang vt khc.",
    "V d: Khi y cun sch, ta tc dng lc vo n lm n chuyn t trng thi ng yn (v = 0; W$_d$ = 0) sang trng thi chuyn ng nhanh dn (vn tc tng, ng nng tng). ng nng ca sch tng l do sch  nhn c nng lng t tay ta truyn sang (Hnh 23.2).",
    "Vic truyn nng lng cho vt bng cch tc dng lc ln vt lm vt thay i trng thi chuyn ng nh trn c gi l *thc hin cng c hc* (gi tt l *thc hin cng*).",
    "[Hnh 23.2. y cun sch]",
    "",
    "92",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "**Hot ng:**",
    "Hy trao i vi bn  chng minh rng trong cc v d m t  Hnh 23.3 c s truyn nng lng bng cch thc hin cng.",
    "[Hnh 23.3.",
    "a) ng c in a vt nng chuyn ng t di t ln cao.",
    "b) Hn hp xng v khng kh trong xilanh b t chy y pittng chuyn ng]",
    "",
    "**? Cu hi:**",
    "1. Hy tr li cu hi  phn khi ng.",
    "2. Khi cho mt ming ng tip xc vi ngn la th ngn la truyn nng lng cho ming ng lm cho n nng ln. Qu trnh truyn nng lng ny c phi l thc hin cng hay khng? Ti sao?",
    "",
    "**2. Cng thc tnh cng**",
    "**a) Khi lc khng i v cng hng vi chuyn ng**",
    " lp 9, chng ta  hc cng thc tnh cng ca lc khi lc khng i v cng hng vi chuyn ng:",
    "A = F.s (23.1)",
    "trong  A l cng ca lc $\\vec{F}$, c n v cng vi n v nng lng l jun (J): 1 J = 1 N.1 m; F l cng  ca lc tc dng ln vt lm vt bin i chuyn ng, n v l niutn (N), s l qung ng i c ca vt, n v l mt (m).",
    "Khi lc cng hng vi chuyn ng th  dch chuyn d c  ln bng qung ng i c s, nn cng thc tnh cng cng c th vit di dng:",
    "A = F.d (23.2)",
    "",
    "**b) Khi lc khng i v khng cng phng vi chuyn ng**",
    "Khi ngi y xe hng  n chuyn ng theo chiu dng ca trc Ox, lc y $\\vec{F}$ lm vi hng chuyn ng mt gc $\\alpha$ bt k (Hnh 23.4). Ta phn tch lc $\\vec{F}$ ra hai lc thnh phn vung gc vi nhau: $\\vec{F}_s$ cng hng vi chuyn ng v $\\vec{F}_n$ vung gc vi $\\vec{F}_s$ (Hnh 23.5).",
    "Trong trng hp ny ch c thnh phn $\\vec{F}_s$ lm vt chuyn ng, nn cng thc tnh cng ca lc trong trng hp ny l:",
    "$A = F_s.s = (F.\\cos\\alpha).s = F.s.\\cos\\alpha$",
    "[Hnh 23.4. Lc khng cng phng vi phng chuyn ng. Ngi y my ct c bng lc $\\vec{F}$ nghing gc $\\alpha$ so vi mt t]",
    "",
    "93",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "Tu thuc vo gc $\\alpha$ m c th xy ra cc trng hp sau:",
    "- $0 \\le \\alpha < 90^\\circ$: thnh phn $\\vec{F}_s$ ca $\\vec{F}$ ln phng chuyn ng cng chiu vi chiu chuyn ng. Cng ca lc c gi l *cng pht ng* (A > 0) (Hnh 23.5a).",
    "- $\\alpha = 90^\\circ$: lc vung gc vi phng chuyn ng, khi  *lc khng sinh cng* (A = 0) (Hnh 23.5b).",
    "- $90^\\circ < \\alpha \\le 180^\\circ$: thnh phn $\\vec{F}_s$ ca $\\vec{F}$ ln phng chuyn ng ngc chiu vi chiu chuyn ng, lc lm cn tr chuyn ng ca vt. Cng ca lc c gi l *cng cn* (A < 0) (Hnh 23.5c).",
    "[Hnh 23.5. Cc trng hp cng.",
    "a) Cng pht ng. $\\alpha$ nhn.",
    "b) Lc khng sinh cng. $\\alpha = 90^\\circ$.",
    "c) Cng cn. $\\alpha$ t]",
    "",
    "**3. Bi tp v d**",
    "*Bi tp v d 1*",
    "Khi ra gm xe  t (Hnh 23.6), ngi ta s dng my nng  nng  t ln  cao h = 160 cm so vi mt sn. Cho bit khi lng  t l m = 1,5 tn v gia tc trng trng l g = 10 m/s$^2$. Tnh cng ti thiu m my nng  thc hin.",
    "*Gii*",
    " nng c  t ln th my nng phi tc dng vo  t lc ti thiu:",
    "$\\vec{F}_{\\text{min}} = -\\vec{P}$",
    "$\\Rightarrow F_{\\text{min}} = P = m.g = 1,5.10^3.10 = 1,5.10^4$ N.",
    "Cng ti thiu m my nng  thc hin l:",
    "$A = P.h = 24000$ J = 24 kJ.",
    "[Hnh 23.6. My nng  t]",
    "",
    "*Bi tp v d 2*",
    "Mt bn hc sinh c khi lng 50 kg i ln mt cu thang gm 20 bc, mi bc cao 15 cm, di 20 cm (Hnh 23.7). Tnh cng ti thiu m bn y phi thc hin. Coi lc m hc sinh tc dng ln mi bc thang l khng i trong qu trnh di chuyn. Ly gia tc trng trng l g = 10 m/s$^2$.",
    "*Gii*",
    " Mun ln cu thang ny bn hc sinh phi c lc nng ti thiu nh Hnh 23.8:",
    "$\\vec{F}_{\\text{min}} = -\\vec{P}$",
    "$\\Rightarrow F_{\\text{min}} = P = m.g$",
    " dch chuyn ca bn hc sinh l: $\\vec{d} = \\vec{AB}$.",
    " Cng ti thiu m bn y phi thc hin l:",
    "$A_{\\text{min}} = F_{\\text{min}}.d.\\cos\\alpha = F_{\\text{min}}.d.\\sin\\beta$",
    "$= m.g.d.\\sin\\beta = m.g.h$",
    "= 50.10.20.0,15 = 1500 J.",
    "[Hnh 23.7. Hc sinh i ln cu thang]",
    "[Hnh 23.8. Biu din lc v  dch chuyn ca hc sinh i cu thang. $\\vec{F}_{\\text{min}}$ hng ln, $\\vec{P}$ hng xung. $\\vec{AB}$ l vect dch chuyn, gc $\\alpha$ gia $\\vec{F}_{\\text{min}}$ v $\\vec{AB}$, gc $\\beta$ gia phng ngang v $\\vec{AB}$]",
    "",
    "94",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "Nhn xt:  ln ti thiu ca cng dng  a vt ln cao lun l: A = P.h.",
    "Vi h l  cao vt c nng ln khng ph thuc vo vic c a ln cao theo ng thng ng hay nm nghing.",
    "",
    "**? Cu hi:**",
    "1. Trng hp no sau y trng lc tc dng ln  t thc hin cng pht ng, cng cn v khng thc hin cng?",
    "a)  t ang xung dc.",
    "b)  t ang ln dc.",
    "c)  t chy trn ng nm ngang.",
    "2. Mt ngi ko mt thng hng khi lng 80 kg trt trn sn nh bng mt dy c phng hp gc $30^\\circ$ so vi phng nm ngang. Bit lc tc dng ln dy bng 150 N. Tnh cng ca lc  khi hm trt i c 29 m.",
    "",
    "**EM  HC**",
    "- Nng lng c th chuyn ho t dng ny sang dng khc, hoc truyn t vt ny sang vt khc v lun c bo ton.",
    "- Cng l s o phn nng lng c truyn hoc chuyn ho trong qu trnh thc hin cng.",
    "- Cng c n v l jun (J): 1 J = 1 N.1 m.",
    "- Cng thc tnh cng: $A = F.d.\\cos\\alpha$.",
    "",
    "**EM C TH**",
    "- Ch to c m hnh n gin minh ho nh lut bo ton nng lng.",
    "- Gii thch c nu mt vt chuyn ng ln dc, xung dc hoc trn mt phng ngang th cng ca trng lc ng vai tr g.",
    "",
    "**EM C BIT?**",
    "Trng hp tng qut, cng do lc thc hin ph thuc vo ba yu t:  ln ca lc, gc hp bi vct lc vi chiu chuyn ng v  dch chuyn ca vt. Tuy nhin, c nhng lc m cng do n thc hin khng ph thuc vo hnh dng ng i m ch ph thuc vo v tr ca im u v im cui ca qu o. Nhng lc c c im ny c gi l lc th (hay lc bo ton).",
    "Trong chng trnh ph thng, cc em s hc mt s lc th gm: lc hp dn, lc n hi, lc in.",
    "",
    "95"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B24', 'Bài 24. Công suất', 97, 2, $JSON$
{
  "content": [
    "# Bi 24 CNG SUT",
    "",
    "**Khi ng:**",
    "* nh gi vic thc hin cng ca ngi hay thit b sinh cng, ngi ta khng ch quan tm n  ln ca cng thc hin c m cn quan tm n vic cng ny c thc hin nhanh hay chm.*",
    "*Theo em, lm th no  xc nh c s nhanh chm ca vic thc hin cng?*",
    "[Hnh nh hai ngi khing  ln cu thang. Ngi i trc ni: \"T thc hin cng nhanh hn cu v t leo ln cao hn cu\". Ngi i sau ni: \"Cha chc u v cu leo trc t\"]",
    "",
    "## I. KHI NIM CNG SUT",
    "**Hot ng:**",
    "Hai anh cng nhn dng rng rc  ko x va ln cc tng cao ca mt cng trnh xy dng. Da vo bng s liu di y, hy xc nh xem ai l ngi thc hin cng nhanh hn. Ly g = 10 m/s$^2$.",
    "**Bng 24.1**",
    "| Cng nhn | Khi lng x va: m (kg) |  cao cng trnh: h (m) | Cng thc hin: A (J) | Thi gian thc hin cng: t (s) |",
    "|---|---|---|---|---|",
    "| Cng nhn 1 | $m_1$ = 20 kg | $h_1$ = 10 m | $A_1 = \\dots ?$ | $t_1$ = 10 s |",
    "| Cng nhn 2 | $m_2$ = 21 kg | $h_2$ = 11 m | $A_2 = \\dots ?$ | $t_2$ = 20 s |",
    "",
    "i lng c trng cho kh nng thc hin cng nhanh hay chm ca ngi hoc thit b sinh cng, c gi l *cng sut* hay *tc  sinh cng*.",
    "",
    "## II. CNG THC TNH CNG SUT",
    "Nu trong thi gian t, cng thc hin c l A th tc  sinh cng, tc cng sut l:",
    "$\\mathcal{P} = \\frac{A}{t}$ (24.1)",
    "Nu A tnh bng jun (J), t tnh bng giy (s) th $\\mathcal{P}$ tnh bng ot (W):",
    "$1 \\text{ W} = \\frac{1 \\text{ J}}{1 \\text{ s}}$",
    "Cc bi ca ot (W) l:",
    "1 kilot = 1 kW = 10$^3$ W",
    "1 mgaot = 1 MW = 10$^6$ W",
    "",
    "**! Ch :** Kilot gi (kW.h) khng phi l n v cng sut m l n v cng. *1 kW.h l cng ca mt thit b sinh cng c cng sut l 1 kW thc hin trong 1 gi.*",
    "",
    "**? Cu hi:**",
    "Coi cng sut trung bnh ca tri tim l 3 W.",
    "a) Trong mt ngy  m trung bnh tri tim thc hin mt cng l bao nhiu?",
    "b) Nu mt ngi sng 70 tui th cng ca tri tim thc hin l bao nhiu? Mt  t ti mun thc hin c cng ny phi thc hin trong thi gian bao lu? Coi cng sut ca xe  t ti l 3.10$^5$ W.",
    "",
    "96",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "## III. LIN H GIA CNG SUT VI LC V TC ",
    "Khi vt chuyn ng cng hng vi lc v lc khng i th:",
    "$\\mathcal{P} = \\frac{A}{t} = \\frac{F.s}{t} = F.v$ (24.2)",
    "Cng thc (24.2) l cng thc tnh cng sut trung bnh. Cng thc tnh cng sut tc thi l:",
    "$\\mathcal{P}_t = F.v_t$ (24.3)",
    "Nu $v$ l tc  trung bnh ca vt th $\\mathcal{P}$ l cng sut trung bnh ca lc lm vt chuyn ng.",
    "Nu $v_t$ l tc  tc thi ca vt th $\\mathcal{P}_t$ l cng sut tc thi ca lc lm vt chuyn ng.",
    "*Bi tp v d*",
    "Mt ngi ko mt thng nc 15 kg t ging su 8 m ln trong 10 s. Hy tnh cng sut ca ngi ko. Bit thng nc chuyn ng u v ly g = 10 m/s$^2$.",
    "*Gii*",
    "V vt chuyn ng thng u nn tc  ca vt l:",
    "$v = \\frac{s}{t} = \\frac{8}{10} = 0,8$ m/s",
    "v lc ko vt ln bng trng lng ca vt:",
    "F = P = m.g = 15.10 = 150 N",
    "Cng sut ca ngi ko bng:",
    "$\\mathcal{P} = F.v = 150.0,8 = 120$ W.",
    "",
    "**? Cu hi:**",
    "1. Hy gii thch tc dng ca lp nhiu tng trong xe p th thao (Hnh 24.1).",
    "2. Hnh 24.2 m t hp s xe my. Hy gii thch ti sao khi i xe my trn nhng on ng dc hoc c ma st ln ta thng i  s nh.",
    "3. ng c ca mt thang my tc dng lc ko 20 000 N  thang my chuyn ng thng ln trn trong 10 s v qung ng i c tng ng l 18 m. Cng sut trung bnh ca ng c l",
    "A. 36 kW. B. 3,6 kW.",
    "C. 11 kW. D. 1,1 kW.",
    "4. Mt  t khi lng 1 tn ang hot ng vi cng sut 5 kW v chuyn ng thng u vi vn tc 54 km/h th ln dc. Hi ng c  t phi hot ng vi cng sut bng bao nhiu  c th ln dc vi tc  nh c? Bit h s ma st gia bnh xe v mt ng khng i, dc nghing gc $2,3^\\circ$ so vi mt ng nm ngang v g = 10 m/s$^2$.",
    "[Hnh 24.1. Lp xe p th thao]",
    "[Hnh 24.2. Hp s xe my]",
    "",
    "97",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "**Hot ng:** Thi xem ai l ngi c cng sut ln hn",
    "1. Hy nu tn dng c cn dng v cch tin hnh vic o thi gian ln cu thang",
    "2. Tho lun trong nhm v k hoch hot ng  xc nh cng sut khi ln thang gc ca 5 ngi i din cc t c trng lng khc nhau, trong  ghi r:",
    "a) Mc ch ca hot ng.",
    "b) Dng c cn s dng.",
    "c) Cc bc tin hnh hot ng.",
    "d) Bng ghi kt qu.",
    "**Bng 24.2.** Mu bng ghi kt qu",
    "| Tn ngi | Trng lng (N) |  cao (m) | Cng (J) | Thi gian (s) | Cng sut (W) |",
    "|---|---|---|---|---|---|",
    "| 1. \\dots | $P_1 = \\dots$ | $h = \\dots$ | $A_1 = \\dots$ | $t_1 = \\dots$ | $\\mathcal{P}_1 = \\dots$ |",
    "| 2. \\dots | $P_2 = \\dots$ | $h = \\dots$ | $A_2 = \\dots$ | $t_2 = \\dots$ | $\\mathcal{P}_2 = \\dots$ |",
    "| 3. \\dots | $P_3 = \\dots$ | $h = \\dots$ | $A_3 = \\dots$ | $t_3 = \\dots$ | $\\mathcal{P}_3 = \\dots$ |",
    "| 4. \\dots | $P_4 = \\dots$ | $h = \\dots$ | $A_4 = \\dots$ | $t_4 = \\dots$ | $\\mathcal{P}_4 = \\dots$ |",
    "| 5. \\dots | $P_5 = \\dots$ | $h = \\dots$ | $A_5 = \\dots$ | $t_5 = \\dots$ | $\\mathcal{P}_5 = \\dots$ |",
    "",
    "**EM  HC**",
    "- Cng sut l i lng c trng cho tc  sinh cng, c o bng cng sinh ra trong mt giy v c n v l ot (W):",
    "$\\mathcal{P} = \\frac{A}{t}$",
    "- Lin h gia cng sut vi lc v tc : $\\mathcal{P} = F.v$",
    "Cng sut trung bnh: $\\mathcal{P} = \\frac{A}{t} = \\frac{F.s}{t} = F.v$",
    "Cng sut tc thi: $\\mathcal{P}_t = F.v_t$",
    "",
    "**EM C TH**",
    "1. Tnh c cng sut ca cc qu trnh sinh cng.",
    "2. Vn dng khi nim cng sut  gii thch nguyn tc hot ng ca mt s thit b my mc.",
    "",
    "98"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B25', 'Bài 25. Động năng, thế năng', 100, 3, $JSON$
{
  "content": [
    "# Bi 25 NG NNG, TH NNG",
    "",
    "**Khi ng:**",
    "[Hnh nh tu ln siu tc ang lao xung]",
    "*Hy m t hot ng ca tu ln.*",
    "*Ti sao khi tu ln  v tr cao nht ca ng ray th tc  ca n li chm nht v ngc li?*",
    "",
    "## I. NG NNG",
    "**1. Khi nim ng nng**",
    "Chng ta  bit ng nng ca mt vt l nng lng m vt c c do chuyn ng.",
    "Mt vt c khi lng m ang chuyn ng vi tc  v th ng nng l:",
    "$W_d = \\frac{1}{2}m.v^2$ (25.1)",
    "Trong h n v SI, n v ng nng l jun (J).",
    "Qua cc v d v nng lng sng, chuyn ng ca thin thch, chuyn ng ca mi tn trong phn cu hi bn, ta thy vt ang chuyn ng c kh nng thc hin cng. Ta ni rng vt  mang nng lng di dng ng nng.",
    "*Bi tp v d 1:* Mt vn ng vin qun vt thc hin c giao bng k lc, qu bng t ti tc  196 km/h. Bit khi lng qu bng l 60 g. Tnh ng nng ca qu bng.",
    "*Gii*",
    "ng nng ca qu bng c tnh theo cng thc:",
    "$W_d = \\frac{1}{2}m.v^2$",
    "Thay s:",
    "$W_d = \\frac{1}{2}.0,06.\\left(196.1000.\\frac{1}{3600}\\right)^2 \\approx 89$ J.",
    "",
    "**? Cu hi:**",
    "1. Nng lng ca cc con sng trong Hnh 25.1 tn ti di dng no?",
    "- Ti sao sng thn li c sc tn ph mnh hn rt nhiu so vi sng thng thng?",
    "- Ti sao sng thn ch gy ra s tn ph khi x vo vt cn?",
    "2. Khi ang bay, nng lng ca thin thch tn ti di dng no?",
    "- Ti sao nng lng ca thin thch li rt ln so vi nng lng ca cc vt thng gp?",
    "- Khi va vo Tri t (Hnh 25.2), nng lng ca thin thch c chuyn ho thnh nhng dng nng lng no?",
    "3. Khi sng  vo b n sinh cng v c th x  cc vt trn b. Tuy nhin, vi vn ng vin lt sng th khng b nh hng. Ti sao?",
    "4. Mt mi tn nng 48 g ang chuyn ng vi tc  10 m/s. Tm ng nng ca mi tn.",
    "[Hnh 25.1. Sng thn]",
    "[Hnh 25.2. H lm do thin thch gy ra khi va vo Tri t]",
    "",
    "99",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "**2. Lin h gia ng nng v cng ca lc**",
    "Xt mt vt khi lng m chuyn ng thng bin i u vi gia tc a t trng thi ng yn di tc dng ca lc khng i F. Sau khi i c qung ng s, vt t tc  v th: $v^2 = 2.a.s$.",
    "V $a = \\frac{F}{m}$ nn $v^2 = \\frac{2.F.s}{m}$",
    "v $\\frac{1}{2}.m.v^2 = F.s \\Rightarrow W_d = A$ (25.2)",
    "*Nh vy, nu ban u vt ng yn th ng nng ca vt c gi tr bng cng ca lc tc dng ln vt.*",
    "",
    "## II. TH NNG",
    "**1. Khi nim th nng trng trng**",
    "Chng ta  bit mt vt t   cao h so vi mt t th lu tr nng lng di dng th nng. V th nng ny lin quan n trng lc nn c gi l *th nng trng trng* (thng c gi tt l *th nng*), vi  ln c tnh bng cng thc: $W_t = P.h = m.g.h$.",
    "n v th nng trng trng l jun (J).",
    "**! Ch :**  ln ca th nng trng trng ph thuc vo vic chn mc tnh  cao. Thng ngi ta tnh  cao ca cc vt so vi mt t c coi l c  cao bng 0.",
    "",
    "**? Cu hi:**",
    "My ng cc (Hnh 25.3) hot ng nh sau: Ba my c nng ln n mt  cao nht nh ri th cho ri xung cc cn ng.",
    "1. Khi ba ang  mt  cao nht nh th nng lng ca n tn ti di dng no? Nng lng  do u m c?",
    "2. Trong qu trnh ri, nng lng ca ba chuyn t dng no sang dng no?",
    "3. Khi chm vo u cc th ba sinh cng  lm g?",
    "[Hnh 25.3. My ng cc]",
    "",
    "*Bi tp v d 2:* My ng cc c u ba nng 0,5 tn, c nng ln  cao 10 m so vi mt t. Tnh th nng ca u ba. Ly g = 9,8 m/s$^2$.",
    "*Gii*",
    "Th nng ca u ba c tnh theo cng thc:",
    "$W_t = m.g.h = 500.9,8.10 = 49 000 \\text{ J} = 49 \\text{ kJ}$",
    "",
    "**? Cu hi:**",
    "1. Th mt qu bng t  cao h xung sn nh. ng nng ca qu bng c chuyn ho thnh nhng dng nng lng no ngay khi qu bng chm vo sn nh?",
    "2. Mt vt c khi lng 10 kg ang chuyn ng vi tc  5 km/h trn mt bn nm ngang. Do c ma st, vt chuyn ng chm dn u v i c 1 m th dng li. Tnh h s ma st gia vt v mt bn. Ly gia tc trng trng g = 9,8 m/s$^2$.",
    "",
    "**EM C BIT?**",
    "Ngoi th nng trng trng cn c nhiu loi th nng khc, di y l mt v d (Hnh 25.4).",
    "[Hnh 25.4. Ngi ging cung]",
    "Khi ging cung th cnh cung b bin dng n hi. Nu ngi  bung tay th mi tn s b dy cung y i xa. iu ny chng t khi ging cung th cnh cung b bin dng  c nng lng d tr  thc hin cng y mi tn i. Nng lng d tr ny c gi l th nng n hi.",
    "",
    "101",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "V  cao h ph thuc vo v tr c chn lm mc nn th nng cng ph thuc vo v tr c chn lm mc.",
    "Trong trng trng, hiu th nng gia hai im ch ph thuc vo chnh lch  cao theo phng thng ng m khng ph thuc vo khong cch gia hai im.",
    "",
    "**2. Lin h gia th nng v cng ca lc th**",
    "Mun a mt vt c khi lng m t mt t ln mt  cao h, ta phi tc dng vo vt lc nng F c  ln ti thiu bng trng lng P ca vt.",
    "Cng m lc nng F thc hin l:",
    "$A = F.s = P.h = m.g.h = W_t$",
    "*Vy th nng ca vt   cao h c  ln bng cng ca lc dng  nng u vt ln  cao ny.*",
    "Cng trong trng hp ny c gi l cng ca lc th, n khng ph thuc vo  ln qung ng i c m ch ph thuc vo s chnh lch  cao ca v tr u v v tr cui.",
    "",
    "**? Cu hi:**",
    "1. Mt chic cn cu xy dng cu mt khi vt liu nng 500 kg t v tr A  mt t n v tr B ca mt to nh cao tng vi cc thng s cho trn Hnh 25.6. Ly gia tc trng trng g = 9,8 m/s$^2$. Tnh th nng ca khi vt liu ti B v cng m cn cu  thc hin.",
    "2. Hy chng minh c th dng mt mt phng nghing  a mt vt ln cao vi mt lc nh hn trng lng ca vt (Hnh 25.7). Coi ma st khng ng k.",
    "",
    "**? Cu hi:**",
    "[Hnh 25.5. Sch trn gi v sch trn gh]",
    "Hnh 25.5 m t mt cun sch c t trn gi sch. Hy so snh th nng ca cun sch trong hai trng hp: gc th nng l sn nh v gc th nng l mt bn.",
    "[Hnh 25.6. Cn cu ko vt t A (mt t) ln B (tng cao) vi  cao 40m, theo ng xin 50m. im chiu ca B xung t cch A 30m]",
    "[Hnh 25.7. Ko vt ln mt phng nghing di $l$, cao h bng lc $\\vec{F}$]",
    "",
    "**EM  HC**",
    "- ng nng l nng lng m vt c c do chuyn ng: $W_d = \\frac{1}{2}m.v^2$ c gi tr bng cng ca lc lm cho vt chuyn ng t trng thi ng yn n khi t c tc  .",
    "- Th nng ca vt trong trng trng lc l nng lng lu tr trong vt do  cao ca vt so vi gc th nng: $W_t = m.g.h$, c gi tr bng cng ca lc  a vt t gc th nng n  cao .",
    "",
    "**EM C TH**",
    "Gii thch c hot ng ca my ng cc da trn s chuyn ho ng nng v th nng ca vt.",
    "",
    "102"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B26', 'Bài 26. Cơ năng và định luật bảo toàn cơ năng', 103, 4, $JSON$
{
  "content": [
    "# Bi 26 C NNG V NH LUT BO TON C NNG",
    "",
    "**Khi ng:**",
    "*K lc nhy so th gii hin nay l 6,17 m do vn ng vin ngi Thu in Amand Duplantis lp nm 2020, k lc nhy cao th gii hin nay l 2,45 m do vn ng vin ngi Cuba Javier Sotomayor lp nm 1993. Ti sao vn ng vin nhy so c th nhy cao hn vn ng vin nhy cao nhiu n th?*",
    "[Hnh nh vn ng vin nhy so]",
    "",
    "## I. S CHUYN HO GIA NG NNG V TH NNG",
    "Chng ta  bit  Trung hc c s:",
    " C nng ca mt vt l tng ng nng v th nng ca n. Khi vt chuyn ng trong trng trng lc th c nng c dng:",
    "$W_c = W_d + W_t = \\frac{1}{2}m.v^2 + m.g.h$ (26.1)",
    " ng nng v th nng c th chuyn ho qua li ln nhau.",
    "[Hnh 26.1. Tu ln siu tc vi cc im A (thp nht), B (cao nht), C, D, E]",
    "",
    "**? Cu hi:**",
    "1. Khi nc chy t thc xung:",
    "a) Lc no lm cho nc chy t nh thc xung di?",
    "b) Lc no sinh cng trong qu trnh ny?",
    "c) ng nng v th nng ca n thay i nh th no?",
    "d) Hy d on v mi lin h gia  tng ng nng v  gim th nng.",
    "2. T mt im   cao h so vi mt t, nm mt vt c khi lng m ln cao vi vn tc ban u $v_0$.",
    "a) Khi vt i ln c nhng lc no tc dng ln vt, lc  sinh cng cn hay cng pht ng?",
    "b) Trong qu trnh vt i ln ri ri xung th dng nng lng no tng, dng nng lng no gim? Hy d on v mi lin h gia  tng ca ng nng v  gim ca th nng.",
    "",
    "**? Cu hi:**",
    "1. Trn Hnh 26.1 l mt phn ng i ca tu ln siu tc. Em hy phn tch s chuyn ho gia ng nng v th nng ca tu ln trn tng on ng.",
    "2. Trong cc qu trnh hot ng ca tu ln, ngoi ng nng v th nng cn c dng nng lng no khc tham gia vo qu trnh chuyn ho?",
    "",
    "103",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "Nh vy ng nng v th nng c th chuyn ho qua li ln nhau. Nu th nng chuyn thnh ng nng th lc s sinh cng pht ng, ngc li, khi ng nng chuyn thnh th nng th lc sinh cng cn.",
    "Nhng  gim ca ng nng c bng  tng ca th nng, hay c nng khng i khng?",
    "",
    "## II. NH LUT BO TON C NNG",
    "**1. Th nghim v con lc ng h**",
    "By gi ta hy xt qu trnh chuyn ho gia ng nng v th nng trong dao ng ca con lc ng h (Hnh 26.2a).",
    "M hnh n gin ca con lc ng h gm mt thanh nh, khng dn, mt u c gi c nh, u cn li ni vi mt vt nng (Hnh 26.2b).",
    "a vt nng ln im A c  cao xc nh h so vi im O ri th cho vt chuyn ng t do. Ta thy vt chuyn ng nhanh dn t A xung O, tip tc chuyn ng chm dn t O ln B, ri li chuyn ng nhanh dn t B xung O, chm dn t O ln A,...",
    "[Hnh 26.2. Con lc ng h qu lc.",
    "a) ng h qu lc thc t.",
    "b) S  dao ng t A n O n B]",
    "",
    "**? Cu hi:**",
    "1. Khi vt chuyn ng trn cung AO th:",
    "a) Nhng lc no sinh cng? Cng no l cng pht ng, cng no l cng cn?",
    "b) ng nng v th nng ca vt thay i nh th no?",
    "2. Tr li nhng cu hi trn cho qu trnh vt chuyn ng trn cung OB.",
    "3. Nu b qua ma st th A v B lun nm trn cng mt  cao. Hin tng ny chng t iu g?",
    "",
    "**2. nh lut bo ton c nng**",
    "Th nghim trn cho thy  tng/gim ca ng nng bng  gim/tng ca th nng, ngha l c nng lun khng i. T , ta c th pht biu nh lut bo ton c nng nh sau:",
    "*Khi mt vt chuyn ng trong trng trng ch chu tc dng ca trng lc th c nng ca vt c bo ton.*",
    "[Hnh 26.3. Vn ng vin trt vn trong mng]",
    "Hnh 26.3 m t vn ng vin tham gia trt vn trong mng. B qua mi ma st, hy phn tch s bo ton c nng ca vn ng vin ny.",
    "",
    "104",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "*Bi tp v d:*",
    "Mt con lc n (Hnh 26.4), bit  di dy treo l $\\ell$ = 0,6 m. a vt ln v tr A hp vi phng thng ng OC mt gc $\\alpha = 30^\\circ$ ri th nh nhng, vt s i xung O (v tr thp nht) ri i n B, sau  quay li v dao ng c th tip din. B qua tc dng ca cc lc cn, lc ma st, ly g = 9,8 m/s$^2$. Hy tnh  ln vn tc ca vt ti v tr O.",
    "[Hnh 26.4. Con lc n dao ng t A qua O n B]",
    "*Gii*",
    "Chn mc tnh th nng ti v tr thp nht O.",
    "Gi c nng ti v tr A, O ln lt l W$_A$ v W$_O$.",
    "Th nng ti v tr A v O l:",
    "W$_{tA}$ = m.g.h$_A$. T Hnh 26.4 ta c:",
    "h$_A$ = OC  CE = $\\ell - \\ell.\\cos\\alpha$ = $\\ell.(1 - \\cos\\alpha)$",
    "$\\Rightarrow$ W$_{tA}$ = $m.g.\\ell(1 - \\cos\\alpha)$;",
    "W$_{tO}$ = m.g.h$_O$, v h$_O$ = 0 $\\Rightarrow$ W$_{tO}$ = 0",
    "ng nng ti v tr A v O l:",
    "W$_{dA}$ = 0; W$_{dO}$ = $\\frac{1}{2}m.v_O^2$",
    "p dng nh lut bo ton c nng ta c:",
    "W$_A$ = W$_O \\Leftrightarrow$ W$_{tA}$ + W$_{dA}$ = W$_{tO}$ + W$_{dO}$",
    "$\\Leftrightarrow m.g.\\ell.(1 - \\cos\\alpha) = \\frac{1}{2}m.v_O^2$",
    "$\\Leftrightarrow v_O = \\sqrt{2.g.\\ell(1 - \\cos\\alpha)}$",
    "Thay s ta c:",
    "$v_O = \\sqrt{2.9,8.0,6(1 - \\cos30^\\circ)} \\approx 1,26$ m/s.",
    "",
    "**EM C BIT?**",
    "Chng ta cng c th dng cc kin thc ca bi trc  chng minh rng khi mt vt chuyn ng trong trng trng ch chu tc dng ca trng lc th c nng ca n c bo ton.",
    "V d: Xt s thay i ng nng v th nng ca mt vt c khi lng m ri t do t v tr A ( cao h$_1$) xung v tr B ( cao h$_2$) (Hnh 26.5).",
    "[Hnh 26.5. Vt ri t do t A  cao h1 xung B  cao h2]",
    "Trong qu trnh chuyn ng , cng A$_{AB}$ ca trng lc c xc nh bi hiu th nng ti A v B:",
    "A$_{AB}$ = W$_{tA}$  W$_{tB}$ = m.g.h$_1$  m.g.h$_2$ (1)",
    "Nu trong qu trnh , vt ch chu tc dng ca trng lc th cng ca trng lc cng c tnh bng  bin thin ng nng t A n B:",
    "A$_{AB}$ = W$_{dB}$  W$_{dA}$ = $\\frac{1}{2}m.v_B^2 - \\frac{1}{2}m.v_A^2$ (2)",
    "T (1) v (2) ta c:",
    "W$_{tA}$  W$_{tB}$ = W$_{dB}$  W$_{dA}$",
    "$\\Leftrightarrow$ W$_{tA}$ + W$_{dA}$ = W$_{tB}$ + W$_{dB}$",
    "$\\Leftrightarrow$ W$_A$ = W$_B$",
    "Vi W$_A$, W$_B$ ln lt l c nng ca vt ti A v B.",
    "",
    "105",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "**Hot ng:**",
    "Ch to m hnh minh ho nh lut bo ton nng lng.",
    "*Dng c:* mt vin bi, hai thanh kim loi nhn, hai gi  c vt iu chnh  cao.",
    "*Ch to:* Dng hai thanh kim loi un thnh ng ray v gn ln gi   to c m hnh nh Hnh 26.6.",
    "[Hnh 26.6. M hnh minh ho nh lut bo ton nng lng. ng ray kim loi cong un ln c im A cao, im B thp, C cao, D cao. Vin bi ri t A qua B vng qua vng cung C]",
    "*Th nghim:*",
    "- Th vin bi t im A trn ng ray.",
    "- Vin bi c th chuyn ng ti im D khng? Ti sao? Lm th nghim  kim tra.",
    "",
    "**? Cu hi:**",
    "1. Mt vt c th cho ri t do t  cao h = 10 m so vi mt t. B qua mi ma st.   cao no th vt c ng nng bng th nng?",
    "2. Th mt vt c khi lng m = 0,5 kg t  cao h$_1$ = 0,8 m so vi mt t. Xc nh ng nng v th nng ca vt   cao h$_2$ = 0,6 m. Ly g = 9,8 m/s$^2$.",
    "",
    "**EM  HC**",
    "- ng nng v th nng ca vt c th chuyn ho qua li ln nhau.",
    "- C nng ca mt vt l tng ca ng nng v th nng. Nu vt chuyn ng trong trng trng ch chu tc dng bi trng lc th c nng ca n c bo ton.",
    "",
    "**EM C TH**",
    "1. Vn dng nh lut bo ton c nng  gii thch mt s tnh hung trong i sng, k thut.",
    "2. Gii thch c v sao vn ng vin nhy so c th nhy ln c ti hn 6 m, trong khi  vn ng vin nhy cao ch nhy c ti hn 2 m.",
    "",
    "106"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B27', 'Bài 27. Hiệu suất', 107, 5, $JSON$
{
  "content": [
    "# Bi 27 HIU SUT",
    "",
    "**Khi ng:**",
    "*Theo em th c th c bao nhiu phn trm ng nng ca thc nc c nh my thu in chuyn ho thnh in nng?*",
    "[Hnh nh p nc ca nh my thu in]",
    "",
    "## I. NNG LNG C CH V NNG LNG HAO PH",
    "Chng ta  bit khi nng lng c chuyn t dng ny sang dng khc, t vt ny sang vt khc, th lun c mt phn b hao ph.",
    "Trong cc ng c nhit thng thng c khong t 60% n 70% nng lng b hao ph, trong cc ng c in nng lng hao ph thp hn, ch vo khong 10%, nhng trong cc pin mt tri th ngc li, ch c khong 10% nng lng ca nh sng mt tri c chuyn ho thnh in nng, cn li l nng lng hao ph.",
    "",
    "**Hot ng:**",
    "Hy tho lun v cc vn  sau:",
    "1. Xc nh nng lng c ch v nng lng hao ph khi chi th thao.",
    "2. Nu chi th thao trong thi tit lnh th nhit nng m c th to ra c c xem l nng lng c ch khng? V sao?",
    "",
    "**? Cu hi:**",
    "1. Trong ng c  t chy bng xng v trong qut in:",
    "a) C nhng s chuyn ho nng lng no?",
    "b) Trong s nhng dng nng lng to thnh, dng nng lng no l c ch, dng nng lng no l hao ph?",
    "2. Xc nh nng lng c ch v nng lng hao ph trong cc trng hp di y:",
    "a) cquy khi np in.",
    "b) cquy khi phng in.",
    "c) S dng rng rc  ko vt nng ln cao.",
    "d) Bp t khi ang hot ng.",
    "",
    "## II. HIU SUT",
    " nh gi t l gia nng lng c ch v nng lng ton phn, ngi ta dng khi nim hiu sut.",
    "Hiu sut = $\\frac{\\text{Nng lng c ch}}{\\text{Nng lng ton phn}}$",
    "$H = \\frac{W_{ci}}{W_{tp}} . 100\\%$ (27.1)",
    "hoc $H = \\frac{\\mathcal{P}_{ci}}{\\mathcal{P}_{tp}} . 100\\%$ vi $\\mathcal{P}_{ci}$ l cng sut c ch, $\\mathcal{P}_{tp}$ l cng sut ton phn.",
    "[Hnh 27.1. S  dng nng lng: Nng lng ton phn i vo, chia thnh nng lng c ch v nng lng hao ph i ra]",
    "",
    "107",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    "T cng thc tnh hiu sut chung  trn ngi ta c th vit cng thc tnh hiu sut cho tng trng hp c th.",
    "V d, hiu sut ca ng c nhit c vit di dng:",
    "$H = \\frac{A}{Q} . 100\\%$ (27.2)",
    "Trong , A l cng c hc m ng c thc hin c, Q l nhit lng m ng c nhn c t nhin liu b t chy.",
    "**Bng 27.1.** Hiu sut ca mt s thit b in",
    "| Thit b | Nng lng u vo | Nng lng u ra c ch | Hiu sut |",
    "|---|---|---|---|",
    "| My pht in | C nng | in nng | 96% |",
    "| Tuabin nc | C nng | C nng | 90% |",
    "| My hi nc | Ho nng | C nng | 15% |",
    "| ng c xng | Ho nng | C nng | 35% |",
    "| Tuabin hi nc | Ho nng | C nng | 28% |",
    "| ng c in | in nng | C nng | 96% |",
    "| n dy tc | in nng | Quang nng | 7% |",
    "| n LED | in nng | Quang nng | 95% |",
    "| Bp in | in nng | Nhit nng | 90% |",
    "",
    "*Bi tp v d:* Mt em b nng 20 kg chi cu trt t trng thi ng yn  nh cu trt di 4 m, nghing gc $40^\\circ$ so vi phng nm ngang (Hnh 27.2). Khi n chn cu trt, tc  ca em b ny l 3,2 m/s. Ly gia tc trng trng l 10 m/s$^2$.",
    "a) Tnh  ln lc ma st tc dng vo em b ny.",
    "b) Tnh hiu sut ca qu trnh chuyn th nng thnh ng nng ca em b ny.",
    "[Hnh 27.2. Cu trt. Gc nghing $\\alpha$,  di $l$, chiu cao h]",
    "*Gii*",
    "a)  ln lc ma st",
    " cao ca nh cu trt so vi mt t:",
    "$h = \\ell.\\sin\\alpha = 4.\\sin 40^\\circ \\approx 2,57$ m",
    "Do c ma st nn khi trt, mt phn th nng ca em b c chuyn ho thnh ng nng, mt phn thng cng cn A ca lc ma st:",
    "$m.g.h = \\frac{m.v^2}{2} + A$",
    " ln cng cn ca lc ma st:",
    "$A = m.g.h - \\frac{m.v^2}{2} \\approx 411,6$ J",
    "T biu thc tnh cng: $A = F.s.\\cos\\alpha$",
    "Ta c  ln lc ma st: $F = \\frac{A}{\\ell} \\approx 102,9$ N.",
    "b) Hiu sut",
    " Nng lng ton phn bng th nng ca em b  nh cu trt:",
    "$W_{tp} = m.g.h = 514$ J.",
    "",
    "108",
    "CHNG IV  NNG LNG, CNG, CNG SUT",
    "",
    " Nng lng hao ph bng  ln cng ca lc ma st nn nng lng c ch l:",
    "$W_{ci} = W_{tp} - A = 102,4$ J",
    " Hiu sut ca qu trnh bin i th nng thnh ng nng:",
    "$H = \\frac{W_{ci}}{W_{tp}} . 100\\% = \\frac{102,4}{514} . 100\\% \\approx 20\\%$.",
    "",
    "**? Cu hi:**",
    "1. Phn tch s tiu hao nng lng  ng c t trong dng trong  t (Hnh 27.3).",
    "[Hnh 27.3. S  phn b s chuyn ho nng lng (cho ng c xng ca  t).",
    "Tng nng lng do nhin liu b t chy cung cp (100%):",
    "- 30% -> Ra ngoi theo kh thi (24%), Truyn cho h thng lm mt (6%)",
    "- 35% -> Nhit sinh cng trong hot ng. (Trong  41% (ca 35%) -> n cc bnh xe)",
    "- Cc tiu hao khc: Bc x nhit ra ngoi 5%]",
    "*(Ghi ch: Lc  trong sch c v cc con s phn trm khng cng li thnh 100% mt cch r rng theo s )*",
    "",
    "2. Hiu sut ca nh my in dng nng lng mt tri khng bng 1/3 hiu sut ca nh my nhit in. Ti sao ngi ta vn khuyn khch xy dng nh my in dng nng lng mt tri?",
    "3. Mt  t chuyn ng vi vn tc 54 km/h c th i c on ng di bao nhiu khi tiu th ht 60 lt xng? Bit ng c ca  t c cng sut 45 kW; hiu sut 25%; 1 kg xng t chy hon ton to ra nhit lng bng $46.10^6$ J/kg v khi lng ring ca xng l 700 kg/m$^3$.",
    "",
    "**EM  HC**",
    "- Lun tn ti nng lng hao ph trong cc qu trnh chuyn ho nng lng.",
    "- Hiu sut c nh ngha theo cng thc: $H = \\frac{W_{ci}}{W_{tp}} . 100\\% = \\frac{\\mathcal{P}_{ci}}{\\mathcal{P}_{tp}} . 100\\%$",
    "",
    "**EM C TH**",
    "1. Vn dng khi nim hiu sut  tnh c phn nng lng c ch v phn nng lng hao ph trong qu trnh hot ng ca cc thit b ph bin trong i sng v k thut.",
    "2. Tm phng n gim nng lng hao ph khi s dng cc thit b in trong gia nh hoc ng c  t, xe my.",
    "",
    "109"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B28', 'Bài 28. Động lượng', 111, 1, $JSON$
{
  "content": [
    "# Bi 28 NG LNG",
    "",
    "**Khi ng:**",
    "*Quan st hnh di y.*",
    "*- Hnh a: Xe ti v xe con ang chy cnh nhau vi cng vn tc. Khi n tn hiu mu  bt sng, xe no mun dng li th cn phi c mt lc hm ln hn. Ti sao?*",
    "*- Hnh b: Cu th  bng st pht 11 m. Th mn kh bt bng hn khi bng bay ti c tc  ln hay nh? Ti sao?*",
    "[Hnh a: Xe ti v xe con chy ti n . Hnh b: Cu th st pht n, th mn c bt bng]",
    "",
    "## I. NG LNG",
    "**Hot ng:**",
    "Thc hin cc th nghim sau  tm hiu v s truyn chuyn ng trong tng tc gia cc vt.",
    "*Chun b:*",
    " Ba vin bi A, B, C (chn bi B nng hn A v C).",
    " Mng trt (c th dng ng nha ct dc).",
    " Mt vi vt (hp giy, quyn sch)  to  dc ca mng trt.",
    " t vin bi C ngay di chn mng trt nh Hnh 28.1.",
    "[Hnh 28.1. Th nghim tm hiu v s truyn chuyn ng trong tng tc. Vin bi A trn mng nghing ln xung va chm vin bi C  chn mng]",
    "*Tin hnh:*",
    " *Th nghim 1:* Ln lt th hai vin bi: A, B (bi B nng hn bi A) chuyn ng trn mng trt. Quan st v o qung ng dch chuyn ca vin bi C sau va chm ng vi mi ln th.",
    " *Th nghim 2:* By gi ch th vin bi A ln xung mng trt nhng tng  dc ca mng trt. Quan st v o qung ng dch chuyn ca vin bi C sau va chm ng vi mi ln th.",
    "*Tho lun:*",
    " Trong th nghim 1, vn tc ca hai vin bi A v B khi n chn dc c ging nhau khng? Vin bi no y vin bi C ln xa hn? Ti sao?",
    " Trong th nghim 2, ng vi  dc no th vin bi A c vn tc ln hn khi va chm vi bi C?  trng hp no, vin bi C ln xa hn? Ti sao?",
    "",
    "T hai th nghim trn, ta thy vt c khi lng v vn tc cng ln th s truyn chuyn ng trong tng tc vi cc vt khc cng mnh. i lng c trng cho kh nng truyn chuyn ng ca mt vt khi tng tc vi vt khc gi l *ng lng* ca vt.",
    "",
    "110",
    "CHNG V  NG LNG",
    "",
    "ng lng ca mt vt khi lng m ang chuyn ng vi vn tc $\\vec{v}$ l i lng c xc nh bi cng thc:",
    "$\\vec{p} = m.\\vec{v}$ (28.1)",
    "ng lng l mt i lng vect c cng hng vi vn tc ca vt.",
    "n v ng lng l: kg.m/s.",
    "",
    "**? Cu hi:**",
    "1. Tm thm v d minh ho cho  ngha vt l trn ca ng lng.",
    "2. a) ng lng ca xe ti hay  t trong hnh  u bi ln hn?",
    "b) Trong trng hp st pht 11 m, ti sao th mn kh bt bng hn nu bng c ng lng tng?",
    "",
    "## II. XUNG LNG CA LC",
    "**1. Xung lng**",
    "Khi mt lc $\\vec{F}$ tc dng ln mt vt trong khong thi gian ngn $\\Delta t$ th tch $\\vec{F}.\\Delta t$ c nh ngha l xung lng ca lc $\\vec{F}$ trong khong thi gian $\\Delta t$ y (Lc $\\vec{F}$ c xem l khng i trong khong thi gian tc dng ngn $\\Delta t$).",
    "n v xung lng ca lc l N.s.",
    "",
    "**? Cu hi:**",
    "1. Trong cc v d sau, cc vt  chu tc dng ca cc lc no trong thi gian rt ngn?",
    " Cu th thc hin mt c  v l  a c bng vo li i phng.",
    " Trong mn bi-a, qu bi-a ang chuyn ng th va chm vo thnh bn nn n b i hng.",
    " Trong mn chi gn, mt qu bng gn ang nm yn. Sau mt c nh, qu bng bay i rt nhanh.",
    "2. Hy ch ra s bin i trng thi chuyn ng ca vt trong cc v d trn nh th no? Ti sao lc tc dng ln vt trong mt khong thi gian ngn li c th gy ra bin i ng k trng thi chuyn ng ca vt ?",
    "",
    "**? Cu hi:**",
    "1. a) Nu nh ngha v n v ca ng lng.",
    "b) V vect ng lng ca mt qu bng tennis va bt khi mt vt (Hnh 28.2).",
    "[Hnh 28.2. Vt tennis nh qu bng]",
    "2. Pht biu no sau y **khng ng** khi ni v ng lng?",
    "A. ng lng ca mt vt c trng cho trng thi chuyn ng ca vt .",
    "B. ng lng l i lng vect.",
    "C. ng lng c n v l kg.m/s.",
    "D. ng lng ca mt vt ch ph thuc vo vn tc ca vt .",
    "3. Tnh  ln ng lng trong cc trng hp sau:",
    "a) Mt xe but khi lng 3 tn ang chuyn ng vi tc  72 km/h.",
    "b) Mt hn  khi lng 500 g chuyn ng vi tc  10 m/s.",
    "c) Mt electron chuyn ng vi tc  $2.10^7$ m/s. Bit khi lng electron bng $9,1.10^{-31}$ kg.",
    "4. Mt xe ti c khi lng 1,5 tn chuyn ng vi tc  36 km/h v mt  t c khi lng 750 kg chuyn ng ngc chiu vi tc  54 km/h. So snh ng lng ca hai xe.",
    "5. Ti sao n v ca ng lng cn c th vit l N.s?",
    "",
    "111",
    "CHNG V  NG LNG",
    "",
    "**2. Lin h gia xung lng ca lc v  bin thin ng lng**",
    "Gi s c mt lc $\\vec{F}$ (khng i) tc dng ln mt vt khi lng m ang chuyn ng vi vn tc $\\vec{v}_1$. Trong khong thi gian tc dng $\\Delta t$, vn tc ca vt bin i thnh $\\vec{v}_2$, ngha l vt  c gia tc:",
    "$\\vec{a} = \\frac{\\vec{v}_2 - \\vec{v}_1}{\\Delta t}$",
    "Theo nh lut 2 Newton:",
    "$\\vec{F} = m.\\vec{a} = m\\frac{\\vec{v}_2 - \\vec{v}_1}{\\Delta t}$",
    "Suy ra:",
    "$\\vec{F}.\\Delta t = m.\\vec{v}_2 - m.\\vec{v}_1 = \\vec{p}_2 - \\vec{p}_1$ (28.2)",
    "V tri ca (28.2) chnh l xung lng ca lc trong khong thi gian $\\Delta t$, cn v phi l  bin thin ng lng ca vt.",
    "T (28.2), ta c th vit: $\\vec{F}.\\Delta t = \\Delta\\vec{p}$ (28.3)",
    "Cng thc (28.3) cho thy:",
    "Xung lng ca lc tc dng ln vt trong mt khong thi gian bng  bin thin ng lng ca vt trong khong thi gian .",
    "",
    "**3. Dng tng qut ca nh lut 2 Newton**",
    "T (28.3), ta c th vit: $\\vec{F} = \\frac{\\Delta\\vec{p}}{\\Delta t}$ (28.4)",
    "Cng thc (28.4) cho thy: *Lc tng hp tc dng ln vt bng tc  thay i ng lng ca vt.*",
    "Pht biu trn c xem nh mt cch din t khc ca nh lut 2 Newton.",
    "",
    "**? Cu hi:**",
    "1. a) Xung lng ca lc gy ra tc dng g?",
    "b) Mt qu bng khi lng m ang bay ngang vi tc  v th p vo mt bc tng v bt tr li vi cng tc . Xung lng ca lc gy ra bi tng ln qu bng l",
    "A. mv. B. mv. C. 2mv. D. 2mv.",
    "2. Th mn khi bt bng mun khng au tay v khi ng th phi co tay li v li ngi mt cht theo hng i ca qu bng. Th mn lm th ",
    "A. lm gim ng lng ca qu bng.",
    "B. lm gim  bin thin ng lng ca qu bng.",
    "C. lm tng xung lng ca lc qu bng tc dng ln tay.",
    "D. lm gim cng  ca lc qu bng tc dng ln tay.",
    "3. Mt qu bng gn c khi lng 46 g ang nm yn, sau mt c nh qu bng bay ln vi tc  70 m/s. Tnh xung lng ca lc v  ln trung bnh ca lc tc dng vo qu bng. Bit thi gian tc dng l $0,5.10^{-3}$ s.",
    "4. Hai vt c khi lng ln lt l $m_1$ = 1 kg v $m_2$ = 2 kg, chuyn ng vi vn tc c  ln ln lt l $v_1$ = 3 m/s v $v_2$ = 2 m/s.",
    "a) Tnh ng lng ca mi vt.",
    "b) Vt no kh dng li hn? V sao?",
    "",
    "**EM  HC**",
    "- ng lng ca mt vt khi lng m ang chuyn ng vi vn tc $\\vec{v}$ l i lng c xc nh bi cng thc: $\\vec{p} = m.\\vec{v}$.",
    "- ng lng l i lng c trng cho s truyn tng tc gia cc vt.",
    "- Tch $\\vec{F}.\\Delta t$ c gi l xung lng ca lc tc dng trong khong thi gian ngn $\\Delta t$ v bng  bin thin ng lng ca vt trong thi gian : $\\vec{F}.\\Delta t = \\Delta\\vec{p}$.",
    "",
    "**EM C TH**",
    "1. M t v tnh  ln ng lng ca Tri t trong chuyn ng quanh Mt Tri, khi bit khi lng Tri t v bn knh qu o.",
    "2. Tnh ng lng ca h tn la + kh ngay trc v sau khi pht kh, khi  bit khi lng, vn tc ca tn la v ca kh pht ra.",
    "",
    "112"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B29', 'Bài 29. Định luật bảo toàn động lượng', 114, 2, $JSON$
{
  "content": [
    "# Bi 29 NH LUT BO TON NG LNG",
    "",
    "**Khi ng:**",
    "*Mt ngi ang  trong mt chic thuyn nh ng yn, ti sao thuyn b li li khi ngi  bc ln b?*",
    "[Hnh nh ngi bc t thuyn nh ln b, thuyn b y ra xa]",
    "",
    "## I. NH LUT BO TON NG LNG",
    "**1. H kn (hay h c lp)**",
    "a) *Mt h nhiu vt c gi l h kn khi khng c ngoi lc tc dng ln h hoc nu c th cc lc y cn bng nhau.* Trong mt h kn, ch c cc *ni lc* (cc lc tc dng gia cc vt trong h) tng tc gia cc vt. Cc ni lc ny theo nh lut 3 Newton trc i nhau tng i mt.",
    "b) Nu trong qu trnh tng tc, cc ni lc xut hin ln hn cc ngoi lc rt nhiu th c th b qua cc ngoi lc v coi h l kn. V d nh: va chm, n n, pho n,...",
    "",
    "**? Cu hi:**",
    "Hy cho v d v h kn.",
    "",
    "**2. nh lut bo ton ng lng**",
    "Xt mt h kn gm hai vt trt trn mt m kh n va chm vi nhau.",
    "V cc lc $\\vec{F}_1$ v $\\vec{F}_2$ l cp ni lc trc i nhau, nn theo nh lut 3 Newton, ta vit:",
    "$\\vec{F}_1 = -\\vec{F}_2$ (29.1)",
    "Di tc dng ca cc lc $\\vec{F}_1$ v $\\vec{F}_2$, trong khong thi gian $\\Delta t$, ng lng ca mi vt c  bin thin ln lt l $\\Delta\\vec{p}_1$ v $\\Delta\\vec{p}_2$.",
    "p dng cng thc $\\vec{F}.\\Delta t = \\Delta\\vec{p}$ cho tng vt, ta c:",
    "$\\begin{cases} \\vec{F}_1.\\Delta t = \\Delta\\vec{p}_1 \\\\ \\vec{F}_2.\\Delta t = \\Delta\\vec{p}_2 \\end{cases}$ (29.2)",
    "T (29.1) v (29.2), suy ra:",
    "$\\Delta\\vec{p}_1 = -\\Delta\\vec{p}_2$ hay $\\Delta\\vec{p}_1 + \\Delta\\vec{p}_2 = \\vec{0}$",
    "Gi $\\vec{p} = \\vec{p}_1 + \\vec{p}_2$ l ng lng ton phn ca h. Ta c bin thin ng lng ton phn ca h bng tng cc bin thin ng lng ca mi vt: $\\Delta\\vec{p} = \\Delta\\vec{p}_1 + \\Delta\\vec{p}_2 = \\vec{0}$",
    "Bin thin ng lng ca h bng khng, ngha l ng lng ton phn ca h khng i.",
    "$\\vec{p} = \\vec{p}_1 + \\vec{p}_2$ (khng i)",
    "Kt qu ny c th m rng cho h kn gm nhiu vt.",
    "",
    "113",
    "CHNG V  NG LNG",
    "",
    "T , ta c th pht biu: *ng lng ton phn ca h kn l mt i lng bo ton.*",
    "Pht biu trn c gi l nh lut bo ton ng lng.",
    "nh lut bo ton ng lng c nhiu ng dng thc t: gii cc bi ton va chm, lm c s cho nguyn tc chuyn ng phn lc.",
    "",
    "**? Cu hi:**",
    "Mt h gm hai vt c khi lng ln lt l $m_1$ v $m_2$, chuyn ng vi vn tc c  ln ln lt l $v_1$ v $v_2$ hng vo nhau. B qua mi ma st v lc cn ca khng kh. Vit biu thc ca nh lut bo ton ng lng cho h ny.",
    "",
    "## II. VA CHM N HI V VA CHM MM",
    "C hai kiu va chm thng gp l va chm n hi v va chm mm.",
    "",
    "**1. Va chm n hi**",
    "Hnh 29.1 m t mt th nghim v va chm n hi.",
    "[Hnh 29.1. Va chm n hi. Hai xe A v B gn cu kim loi.",
    "Trc va chm: $v_A = v$, $v_B = 0$",
    "Sau va chm: $v'_A = 0$, $v'_B = v$ (Trng hp 2 xe cng khi lng)]",
    "Dng hai xe A v B ging nhau,  u mi xe c gn mt qu cu kim loi nh, cho xe A chuyn ng vi vn tc $v_A = v$ ti va chm vi xe B ang ng yn. Kt qu ca va chm lm xe A ang chuyn ng th dng li, cn xe B ang ng yn th chuyn ng vi ng vn tc $v'_B = v$ (Hnh 29.1). Cn nu xe A chuyn ng n va chm trc din vi xe B c vn tc $v_B = -v$, th sau va chm c hai xe i chiu vn tc: $v'_A = -v$ v $v'_B = v$.  l hai v d v kiu va chm n hi.",
    "Va chm nh th gi l va chm n hi.",
    "",
    "**? Cu hi:**",
    "1. Hy tnh ng lng v ng nng ca h trc v sau va chm n hi. (Hnh 29.1)",
    "2. T kt qu tnh c rt ra nhn xt g?",
    "",
    "**2. Va chm mm**",
    "Hnh 29.2 m t mt th nghim v va chm mm.",
    "[Hnh 29.2. Va chm mm. Hai xe A v B gn ming nha dnh.",
    "Trc va chm: $v_A = v$, $v_B = 0$",
    "Sau va chm: 2 xe dnh vo nhau $v_{AB} = \\frac{v}{2}$]",
    "Dng hai xe A v B ging nhau,  u mi xe c gn mt ming nha dnh. Cho xe A chuyn ng vi vn tc $v_A = v$ ti va chm vi xe kia ang ng yn. Sau va chm, c hai xe dnh vo nhau v chuyn ng vi vn tc bng $v_{AB} = \\frac{v}{2}$. Kiu va chm dnh ny gi l va chm mm.",
    "",
    "114",
    "CHNG V  NG LNG",
    "",
    "**? Cu hi:**",
    "1. Hy tnh ng lng v ng nng ca h trong Hnh 29.2 trc v sau va chm.",
    "2. T kt qu tnh c rt ra nhn xt g?",
    "3. Trong Hnh 29.3, nu ko bi (1) ln thm mt  cao h ri th ra. Con lc s ri xung v va chm vi hai con lc cn li. Hy d on xem va chm l va chm g. Con lc (2), (3) ln ti  cao no? Lm th nghim  kim tra.",
    "[Hnh 29.3. Con lc Newton gm 3 qu cu kim loi. Qu (1) ko ln mt gc, (2) v (3) ng yn]",
    "",
    "**EM  HC**",
    "- Mt h nhiu vt tc dng ln nhau c gi l h kn (hay h c lp) khi khng c ngoi lc tc dng vo h hoc khi cc ngoi lc cn bng nhau.",
    "- nh lut bo ton ng lng: ng lng ton phn ca h kn l mt i lng bo ton.",
    "- C hai kiu va chm thng gp l va chm n hi v va chm mm.",
    "",
    "**EM C TH**",
    "Vn dng nh lut bo ton ng lng  gii thch:",
    "1. Ti sao hai ngi ang ng yn trn sn bng b li ra xa nhau khi h dng tay y vo nhau (Hnh 29.4).",
    "2. Ti sao tc  li ca mi ngi c khi lng khc nhau th khc nhau.",
    "[Hnh 29.4. Hai ngi ng trn sn bng y nhau ri li li vi vn tc $V_1, V_2$]",
    "",
    "115"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B30', 'Bài 30. Thực hành: Xác định động lượng của vật trước và sau va chạm', 117, 3, $JSON$
{
  "content": [
    "# Bi 30 THC HNH: XC NH NG LNG CA VT TRC V SAU VA CHM",
    "",
    "**Khi ng:**",
    "*C hai xe chuyn ng va chm vo nhau th ng lng cc xe thay i. Em hy nu cc trng hp c th xy ra v d on sau va chm hai xe chuyn ng nh th no. Lm th no xc nh c ng lng ca hai xe trc v sau va chm bng dng c th nghim, t  kim nghim nh lut bo ton ng lng?*",
    "",
    "## I. DNG C TH NGHIM",
    " Bng m kh (1).",
    " ng h o thi gian hin s (2).",
    " Hai cng quang in (3).",
    " Bm nn kh (4).",
    " Hai xe trt (5).",
    " Hai tm cn quang (6).",
    " Cn in t (7).",
    " Mt s qu nng (8).",
    " L xo hoc thanh nha hnh ch U  mc dy cao su n hi (9).",
    " Cht ghim (10).",
    " Cc dy ni (11).",
    "[Hnh 30.1. B dng c th nghim xc nh ng lng trc v sau va chm. Cc chi tit nh s t 1 n 11]",
    "",
    "## II. THIT K PHNG N TH NGHIM",
    " hai xe va chm trn m kh, c th thc hin nh sau:",
    " iu chnh cho bng m kh nm ngang v lp ng dn kh t bm nn kh vo bng m kh.",
    " Lp hai cng quang in vo hai gi  t cch nhau mt khong.",
    " Ni dy t hai cng quang in vo ng h o thi gian hin s.",
    " Lp tm cn quang v cc cht cm thch hp ln mi xe v t hai xe ln bng m kh.",
    " Cp in cho bm nn kh v ng h o thi gian hin s.",
    "",
    "**Hot ng:**",
    "y cho hai xe chuyn ng va chm vo nhau trn m kh v tho lun:",
    "1. Khi hai xe chuyn ng trn m kh nm ngang, h hai xe chuyn ng c phi l h kn khng? V sao?",
    "2.  xc nh ng lng ca hai xe trc v sau va chm cn o cc i lng no?",
    "3. Hy th cc trng hp m em  d on v suy ngh lm th no o c cc i lng  xc nh ng lng ca hai xe trc v sau va chm.",
    "4. Thit k phng n th nghim  xc nh ng lng ca hai xe trc v sau va chm tng ng vi cc trng hp va chm c th xy ra.",
    "",
    "116",
    "CHNG V  NG LNG",
    "",
    "## III. TIN HNH TH NGHIM",
    "*Th nghim 1: Va chm mm*",
    "Hai xe chuyn ng va chm vo nhau, sau va chm hai xe dnh vo nhau v chuyn ng vi cng vn tc.",
    "1. B tr th nghim nh Hnh 30.2.",
    "2. Lp tm cn quang vo xe v cc cht cm thch hp ln hai xe, sau  cn khi lng xe v ghi vo Bng 30.1.",
    "3. Cp in cho bm nn kh v ng h o thi gian, iu chnh tc  ca bm nn kh thch hp, cho ng h o thi gian hot ng  ch  o thi gian vt chn cng quang in.",
    "4. n nt Reset trn mt ng h  a s ch ca ng h v 0.000.",
    "5. t xe 2 ln bng m kh gia hai cng quang in, t xe 1  khong bn ngoi hai cng quang in.",
    "6. y xe 1 va chm vo xe 2.",
    "7. Ln lt c trn ng h cc khong thi gian $t_1, t_2$ v ghi vo Bng 30.1.",
    "8. Gn thm vo xe cc gia trng, lp li cc bc 4, 5, 6, 7 hai ln.",
    "[Hnh 30.2. B tr th nghim xc nh ng lng trong trng hp va chm mm]",
    "",
    "**! Ch :** Gn tm chn cng quang in v iu chnh cho song song vi bng m kh.",
    "",
    "*Th nghim 2: Va chm n hi*",
    "Hai xe chuyn ng va chm vo nhau, sau va chm hai xe chuyn ng v hai pha ngc nhau (Hnh 30.3).",
    "1. B tr th nghim nh Hnh 30.3.",
    "2. Gn l xo (hoc thanh nha hnh ch U c dy cao su n hi vo 1 xe). Cn hai xe v ghi vo Bng 30.2.",
    "3. t hai xe ln bng m kh  v tr gia hai cng quang. Ly si dy nh buc hai xe  nn l xo li. n nt Reset trn mt ng h.",
    "4. Ct si dy  l xo bung ra, y hai xe v hai pha.",
    "5. Ln lt c trn ng h cc khong thi gian $t_1, t_2$ v ghi vo Bng 30.2.",
    "6. Gn thm vo hai xe cc gia trng, lp li cc bc 3, 4, 5 hai ln na.",
    "[Hnh 30.3. Th nghim xc nh ng lng trong trng hp va chm n hi]",
    "",
    "117",
    "CHNG V  NG LNG",
    "",
    "## IV. KT QU TH NGHIM",
    "**Bng 30.1.** Th nghim va chm mm",
    " di tm cn quang: $\\dots\\dots\\dots$ (m)",
    "| | | | Trc va chm | | | Sau va chm | | |",
    "|---|---|---|---|---|---|---|---|---|",
    "| Ln | $m_1$ | $m_2$ | $t_1$ | $v_1$ | $p_1$ | $p_2$ | p | $t'_1$ | $V_1 = V_2$ | p' |",
    "| 1 | | | | | | | | | | |",
    "| 2 | | | | | | | | | | |",
    "| 3 | | | | | | | | | | |",
    "",
    "**Bng 30.2.** Th nghim va chm n hi",
    "| | | | Trc va chm | | | | Sau va chm | | | |",
    "|---|---|---|---|---|---|---|---|---|---|---|",
    "| Ln | $m_1$ | $m_2$ | $p_1$ | $p_2$ | $t'_1$ | $t'_2$ | $v'_1$ | $v'_2$ | $p'_1$ | $p'_2$ |",
    "| 1 | | | | | | | | | | |",
    "| 2 | | | | | | | | | | |",
    "| 3 | | | | | | | | | | |",
    "",
    "**Hot ng:** Nhn xt v nh gi kt qu th nghim",
    "1. T Bng 30.1 v Bng 30.2, hy so snh cc kt qu xc nh ng lng ca hai xe trc v sau va chm trong hai th nghim.",
    "2. Em c th  xut mt phng n th nghim khc  xc nh ng lng ca hai xe trc v sau va chm.",
    "",
    "**EM  HC**",
    "- S dng bng m kh, cng quang v ng h o thi gian hin s c th tin hnh th nghim xc nh ng lng ca vt trc v sau va chm i vi va chm mm, va chm n hi.",
    "-  tin hnh th nghim chnh xc, cn t mng ngang v gim ma st t nht c th.",
    "",
    "**EM C TH**",
    "S dng in thoi thng minh v phn mm phn tch video  xc nh c vn tc v ng lng trc v sau va chm ca hai vin bi c khi lng xc nh.",
    "[Hnh 30.4. Thit k th nghim xc nh ng lng ca hai vin bi trc v sau va chm bng in thoi thng minh]",
    "",
    "**EM C BIT?**",
    "Trong thit k  t, ngoi ti kh v dy an ton trn  t, nh sn xut cn to ra vng hp th xung lng ca lc   l phn khung thp mm hn cc vng khc.",
    "Khi c va chm,  bin thin ng lng ca xe trong mt khong thi gian bng xung ca lc tc dng ln xe trong khong thi gian : $\\Delta\\vec{p} = \\vec{F}.\\Delta t$. Vng hp th xung lng ca lc s bin dng gip xe gim tc  chm hn, ko di thi gian va chm  gim lc tc dng, gip gim chn thng cho ngi ngi trong xe.",
    "",
    "118"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B31', 'Bài 31. Động học của chuyển động tròn đều', 121, 1, $JSON$
{
  "content": [
    "# Bi 31 NG HC CA CHUYN NG TRN U",
    "",
    "**Khi ng:**",
    "*Khi xe m t ua vo khc cua th c nhng b phn no ca xe chuyn ng trn?*",
    "[Hnh nh ngi i xe m t th thao ang vo cua nghing xe]",
    "",
    "## I. M T CHUYN NG TRN",
    "Trong cuc sng hng ngy ta gp nhiu vt chuyn ng trn nh: cnh qut, kim ng h, u quay,...",
    " xc nh v tr ca vt chuyn ng trn ta c th da vo qung ng i s ( di cung trn) hoc  dch chuyn gc $\\theta$ tnh t v tr ban u.",
    "Khi vt chuyn ng trn trong thi gian t t A n B th  dch chuyn gc ca vt trong thi gian ny l gc  tm $\\theta$ chn cung AB c  di s bng qung ng i c cng trong thi gian  (Hnh 31.1).",
    "[Hnh 31.1. Qung ng s v  dch chuyn gc $\\theta$. ng trn tm O bn knh r. im A v B trn ng trn, cung AB l s, gc  tm l $\\theta$]",
    "",
    "Trong Ton hc, ta  bit mi quan h gia  di cung vi gc chn tm v bn knh ng trn:",
    "$\\theta = \\frac{s}{r}$ (31.1)",
    "Trong Vt l ngi ta thng dng n v gc l raian (k hiu rad). C th d dng chuyn n v  sang rad. V d, khi vt chuyn ng c 1 vng trn, ta c:",
    "$\\theta = \\frac{2.\\pi.r}{r} = 2.\\pi$",
    "Do : $360^\\circ = 2.\\pi \\text{ (rad)}$",
    "Tng t, ta c: $180^\\circ = \\pi \\text{ (rad)}$.",
    "",
    "**? Cu hi:**",
    "1. Chng minh rng mt raian l gc  tm chn cung c  di bng bn knh ng trn.",
    "2. Tnh qung ng i c khi vt chuyn ng trn c  dch chuyn gc 1 rad, bit bn knh ng trn l 2 m.",
    "3. Xt chuyn ng ca kim gi ng h. Tm  dch chuyn gc ca n (theo  v raian):",
    "a) Trong mi gi.",
    "b) Trong khong thi gian t 12 gi n 15 gi 30 pht.",
    "",
    "120",
    "CHNG VI  CHUYN NG TRN U",
    "",
    "## II. CHUYN NG TRN U. TC  V TC  GC",
    "**1. Tc **",
    "Trong chuyn ng trn,  c trng cho s nhanh hay chm ta cng dng khi nim tc  nh trong chuyn ng thng.",
    "Chuyn ng trn u l chuyn ng theo qu o trn c tc  khng thay i:",
    "$v = \\frac{s}{t} = \\text{hng s}$ (31.2)",
    "",
    "**? Cu hi:**",
    "Da vo vic quan st chuyn ng ca kim giy quay u trong ng h :",
    "1. So snh tc  ca cc im khc nhau trn kim;",
    "2. So snh  dch chuyn gc trong cng khong thi gian ca cc im khc nhau trn kim.",
    "",
    "**2. Tc  gc**",
    "Tc  gc trong chuyn ng trn u bng  dch chuyn gc chia cho thi gian dch chuyn.",
    "$\\omega = \\frac{\\theta}{t}$ (31.3)",
    "n v thng dng ca tc  gc l rad/s.",
    "T cng thc (31.1) v (31.2), suy ra:",
    "$v = \\omega.r$ (31.4)",
    "",
    "**EM C BIT?**",
    "Ngoi tc , tc  gc, trong chuyn ng trn u ngi ta cn quan tm n cc i lng nh chu k v tn s.",
    "*Chu k (k hiu l T)* trong chuyn ng trn u l thi gian  vt quay ht mt vng trn.",
    "*Tn s (k hiu l f)* l s vng vt i c trong mt giy. n v tn s l hc (Hz).",
    "T cc cng thc trn ta c cng thc tnh T v f:",
    "$T = \\frac{1}{f} = \\frac{2.\\pi}{\\omega}$",
    "",
    "**? Cu hi:**",
    "1. Hy tnh tc  gc ca kim gi v kim pht ca ng h.",
    "2. Roto trong mt t my ca nh my thu in Ho Bnh quay 125 vng mi pht. Hy tnh tc  gc ca roto ny theo n v rad/s.",
    "",
    "## III. VN TC TRONG CHUYN NG TRN U",
    "Ta  bit trong chuyn ng thng vn tc tc thi $\\vec{v}_t$ ti mt thi im cho bi:",
    "$\\vec{v}_t = \\frac{\\Delta\\vec{d}}{\\Delta t}$",
    "Khi $\\Delta t$ rt nh, vect  dch chuyn $\\Delta\\vec{d}$ s tin ti trng vi tip tuyn vi ng trn. Do , ti mi thi im vect vn tc tc thi s c phng trng vi tip tuyn ca ng trn (Hnh 31.2).",
    "",
    "**? Cu hi:**",
    "1. Bit chiu di kim pht v kim giy ca mt chic ng h ln lt l 4 cm v 5 cm. Hy tnh:",
    "a) T s chu k quay ca hai kim.",
    "b) T s tc  ca u kim pht v u kim giy.",
    "2. Xt mt im nm trn ng xch o trong chuyn ng t quay ca Tri t. Bit bn knh Tri t ti xch o l 6 400 km. Hy tnh:",
    "a) Chu k chuyn ng ca im .",
    "b) Tc  v tc  gc ca im .",
    "",
    "121",
    "CHNG VI  CHUYN NG TRN U",
    "",
    "Trong chuyn ng trn u,  ln ca vn tc tc thi khng i nhng hng lun thay i.",
    "[Hnh 31.2. Vect vn tc trong chuyn ng trn. Ti im M, vect vn tc $\\vec{v}_M$ tip tuyn vi ng trn. Ti im N, vect vn tc $\\vec{v}_N$ tip tuyn vi ng trn]",
    "",
    "**? Cu hi:**",
    "1. Phn bit tc  v vn tc tc thi trong chuyn ng trn u.",
    "2. Nu mi quan h gia tc  $v$, chu k T v bn knh r ca mt vt chuyn ng trn u.",
    "3. Mt xe  chi chy vi tc  khng i 0,2 m/s trn mt ng ray trn tm O, ng knh AB theo chiu kim ng h. (Hnh 31.3). Xc nh s thay i ca vn tc khi xe i t A n B.",
    "[Hnh 31.3. ng ray xe la  chi hnh trn c ng knh AB]",
    "",
    "**EM  HC**",
    "- Chuyn ng ca mt vt theo qu o trn vi tc  khng i gi l chuyn ng trn u.",
    "- Mt raian l gc  tm chn cung c  di bng bn knh ng trn.",
    "- Tc , tc  gc v bn knh qu o lin h vi nhau theo cng thc: $v = \\omega.r$.",
    "- Trong chuyn ng trn u,  ln vn tc khng i nhng hng lun thay i.",
    "",
    "**EM C TH**",
    "1. Biu din c  dch chuyn gc theo raian.",
    "2. Vn dng khi nim tc  gc  gii c mt s bi tp lin quan.",
    "",
    "122"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B32', 'Bài 32. Lực hướng tâm và gia tốc hướng tâm', 124, 2, $JSON$
{
  "content": [
    "# Bi 32 LC HNG TM V GIA TC HNG TM",
    "",
    "**Khi ng:**",
    "*Ti sao Tri t chuyn ng quanh Mt Tri? Ti sao trn nhng on ng vng thng phi hn ch tc  ca xe v mt ng thng phi hi nghing v pha tm?*",
    "[Hnh nh minh ha qu o Tri t quanh Mt Tri. C vn tc v hng tip tuyn v Lc hp dn ca Mt Tri ln Tri t hng vo tm]",
    "",
    "## I. LC HNG TM",
    "Dng mt si dy nh khng dn buc vo mt ci ty. Quay dy sao cho ci ty chuyn ng trn trong mt phng nm ngang c tm l u dy m tay gi (Hnh 32.1).",
    "[Hnh 32.1. Bn nam dng si dy quay ci ty chuyn ng trn, c lc cng dy ko vo tm]",
    "",
    "**? Cu hi:**",
    "1. Lc no sau y lm ci ty chuyn ng trn?",
    " Trng lc tc dng ln ci ty.",
    " Lc cn ca khng kh.",
    " Lc cng dy hng vo tm qu o ca ci ty.",
    "2. Nu ci ty ang chuyn ng m ta bung tay ra th:",
    " Ci ty tip tc chuyn ng trn.",
    " Ci ty s ri xung t theo phng thng ng.",
    " Ci ty vng ra theo phng tip tuyn vi qu o theo hng vn tc ti im .",
    "3. Lc no duy tr chuyn ng trn ca Tri t xung quanh Mt Tri?",
    "",
    "*Lc (hay hp lc) tc dng ln vt chuyn ng trn u hng vo tm qu o gi l lc hng tm.*",
    "",
    "**? Cu hi:**",
    "Tm thm v d v lc hng tm.",
    "",
    "## II. GIA TC HNG TM",
    "Trong chuyn ng trn u, lc hng tm gy gia tc hng vo tm nn gia tc ny c gi l gia tc hng tm, k hiu l $a_{ht}$:",
    "$a_{ht} = \\frac{v^2}{r} = \\omega^2.r$ (32.1)",
    "",
    "123",
    "CHNG VI  CHUYN NG TRN U",
    "",
    "**EM C BIT?**",
    " tnh  ln ca gia tc hng tm ta s dng cng thc gia tc:",
    "$\\vec{a} = \\frac{\\Delta\\vec{v}}{\\Delta t}$",
    "Khi vt chuyn ng trn u t A n B trong thi gian $\\Delta t$ th  dch chuyn ca vt l vect $\\vec{AB}$ (Hnh 32.2a), c  ln l: $d = v.\\Delta t$.",
    "Gi $\\vec{v}_A$ v $\\vec{v}_B$ l cc vect vn tc tc thi ti A v B. V chuyn ng l trn u nn cc vect ny c  ln khng i, ch thay i v hng. S thay i v hng c biu din bng vect $\\Delta\\vec{v} = \\vec{v}_B - \\vec{v}_A$ (Hnh 32.2b).",
    "Tam gic AOB  Hnh 32.2a v tam gic EAC  Hnh 32.2b l hai tam gic cn ng dng nn:",
    "$\\frac{\\Delta v}{v} = \\frac{AB}{r} = \\frac{\\Delta v}{v} = \\frac{v.\\Delta t}{r}$",
    "Suy ra: $a_{ht} = \\frac{\\Delta v}{\\Delta t} = \\frac{v^2}{r}$. V $v = \\omega.r$ nn: $a_{ht} = \\frac{v^2}{r} = \\omega^2.r$",
    "[Hnh 32.2.",
    "a) Chuyn ng ca vt trn cung trn t A n B, bn knh r, tm O. Vn tc tip tuyn $\\vec{v}_A, \\vec{v}_B$.",
    "b) Tam gic vect vn tc. $\\vec{v}_B$ v $-\\vec{v}_A$ to ra  bin thin $\\Delta\\vec{v}$ hng vo tm]",
    "",
    "**? Cu hi:**",
    "1. Tnh gia tc hng tm ca mt v tinh nhn to chuyn ng trn u quanh Tri t vi bn knh qu o l 7 000 km v tc  7,57 km/s.",
    "2. Tnh gia tc hng tm ca Mt Trng trong chuyn ng quay quanh Tri t (coi Mt Trng chuyn ng trn u quanh Tri t). Bit khong cch t Mt Trng n tm Tri t l $3,84.10^8$ m v chu k quay l 27,2 ngy.",
    "3. Kim pht ca mt chic ng h di 8 cm. Tnh gia tc hng tm ca u kim.",
    "",
    "## III. CNG THC  LN LC HNG TM",
    "Theo nh lut 2 Newton v cng thc tnh  ln ca gia tc hng tm  trn ta c cng thc tnh  ln lc hng tm:",
    "$F_{ht} = m.a_{ht} = \\frac{m.v^2}{r} = m.\\omega^2.r$ (32.2)",
    "*V d v lc hng tm:* Mt vt nh buc vo u mt si dy, nu quay u v nhanh, si dy gn nh quay trong mt phng nm ngang (Hnh 32.3). Nu quay u v chm, si dy qut thnh mt mt nn (Hnh 32.4).",
    "",
    "124",
    "CHNG VI  CHUYN NG TRN U",
    "",
    "**EM  HC**",
    "- Gia tc trong chuyn ng trn u lun hng vo tm qu o v c  ln l:",
    "$a_{ht} = \\frac{v^2}{r} = \\omega^2.r$",
    "- Lc (hay hp lc ca cc lc) tc dng vo mt vt chuyn ng trn u v gy ra cho vt gia tc hng tm gi l lc hng tm.",
    "Biu thc ca lc hng tm:",
    "$F_{ht} = m.a_{ht} = \\frac{m.v^2}{r} = m.\\omega^2.r$.",
    "",
    "**EM C TH**",
    "1. Gii thch l do v sao trong thc t ngi ta ch lm cu vng ln ch khng lm cu vng xung?",
    "2. Gii thch v sao trong mn xic m t bay, din vin xic c th i m t trong thnh ca mt ci lng quay trn m khng b ri (Hnh 32.7).",
    "[Hnh 32.7. Xic m t bay]",
    "",
    "**EM C BIT?**",
    "**Chuyn ng li tm**",
    "Mt vt t trn mt chic bn quay. Nu tng tc  gc $\\omega$ ca bn quay n mt gi tr no  th lc ma st ngh cc i nh hn lc hng tm cn thit ($F_{ht} = m.\\omega^2.r$)  gi cho vt chuyn ng trn. Khi y vt trt trn bn ra xa tm quay, ri vng ra khi bn theo phng tip tuyn vi qu o. Chuyn ng nh vy ca vt c gi l chuyn ng li tm (Hnh 32.8).",
    "Gii thch ti sao thng git qun o ca my git c nhiu l thng  thnh xung quanh.",
    "[Hnh 32.8. Lc li tm lm vt vng ra khi lc ma st ngh cc i khng  gi: $F_{\\text{msn(max)}} < m.\\omega^2.r$]",
    "",
    "126"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B33', 'Bài 33. Biến dạng của vật rắn', 128, 1, $JSON$
{
  "content": [
    "# Bi 33 BIN DNG CA VT RN",
    "",
    "**Khi ng:**",
    "*Bungee l mt tr chi mo him c nhiu ngi yu thch. Em c bit tr chi ny c thc hin da trn hin tng vt l no khng?*",
    "[Hnh nh ngi chi Bungee nhy t vch ni xung h nc bng dy chun n hi. Nhy bungee  Interlaken, Thu S]",
    "",
    "## I. BIN DNG N HI. BIN DNG KO V BIN DNG NN",
    "Khi khng c ngoi lc tc dng, vt rn c kch thc v hnh dng xc nh. Khi c ngoi lc tc dng, vt rn thay i hnh dng v kch thc, ta ni vt rn b bin dng.",
    "",
    "**Hot ng:**",
    "Hy lm cc th nghim v bin dng sau y:",
    " p qu bng cao su vo bc tng (Hnh 33.1a).",
    " Nn l xo dc theo trc ca n (Hnh 33.1b).",
    " Ko hai u l xo dc theo trc ca n (Hnh 33.1c).",
    " Ko cho vng dy cao su dn ra (Hnh 33.1d).",
    "1. Trong mi th nghim trn, em hy cho bit:",
    " Lc no lm vt bin dng?",
    " Bin dng no l bin dng ko? Bin dng no l bin dng nn?",
    " Mc  bin dng ph thuc vo yu t no?",
    "2. Trong th nghim vi l xo v vng dy cao su, nu lc ko qu ln th khi thi tc dng lc, chng c tr v hnh dng, kch thc ban u c khng?",
    "[Hnh 33.1. Cc kiu bin dng.",
    "a) p qu bng cao su vo tng.",
    "b) Nn l xo.",
    "c) Ko l xo.",
    "d) Ko vng dy cao su]",
    "",
    "Nh vy, khi c tc dng ca ngoi lc, vt rn s b bin dng.",
    "Mc  bin dng ph thuc vo  ln ca ngoi lc.",
    "Khi khng cn tc dng ca ngoi lc, nu vt rn ly li c hnh dng v kch thc ban u th bin dng ca vt l *bin dng n hi*.",
    "",
    "128",
    "CHNG VII  BIN DNG CA VT RN, P SUT CHT LNG",
    "",
    "Gii hn m trong  vt rn cn gi c tnh n hi c gi l gii hn n hi ca vt rn.",
    "Khi vt chu tc dng ca cp lc nn ngc chiu nhau, vung gc vi b mt ca vt v hng vo pha trong vt, ta c bin dng nn (Hnh 33.2b).",
    "Khi vt chu tc dng ca cp lc ko ngc chiu nhau, vung gc vi b mt ca vt v hng ra pha ngoi vt, ta c bin dng ko (Hnh 33.2c).",
    "[Hnh 33.2. Mt s hnh dng ca vt rn.",
    "a) Khi cha b bin dng.",
    "b) Khi b bin dng nn.",
    "c) Khi b bin dng ko]",
    "",
    "## II. LC N HI. NH LUT HOOKE",
    "**1. Lc n hi ca l xo**",
    "Khi ta nn hoc ko hai u l xo, tay ta cng chu tc dng cc lc t pha l xo. Cc lc ny ngc chiu vi lc tay tc dng vo l xo v c gi l lc n hi ca l xo. Lc n hi ca l xo chng li nguyn nhn lm n bin dng v c xu hng a n v hnh dng v kch thc ban u.",
    "",
    "**Hot ng:**",
    "Vi cc dng c sau y: gi  th nghim; cc l xo; hp qu cn; thc o.",
    " Thit k v thc hin phng n th nghim tm mi quan h gia  ln ca lc n hi v  bin dng ca l xo.",
    " Hy th hin kt qu trn  th v s ph thuc ca lc n hi vo  bin dng ca l xo.",
    " Tho lun v nhn xt kt qu thu c.",
    "",
    "**? Cu hi:**",
    "1. Em hy cho bit loi bin dng trong mi trng hp sau:",
    "a) Ct chu lc trong to nh.",
    "b) Cnh cung khi ko dy cung.",
    "2. Tm thm v d v bin dng nn v bin dng ko trong i sng.",
    "",
    "**2. nh lut Hooke**",
    "Hnh 33.3 l  th v s ph thuc  ln ca lc n hi vo  bin dng ca l xo:",
    "on OA trn  th cho bit s ph thuc  ln ca lc n hi $F_{h}$ vo  bin dng $\\Delta\\ell$ l tuyn tnh, ta c th vit s ph thuc ny bng biu thc ton hc:",
    "$F_{h} = k|\\Delta\\ell|$ (33.1)",
    "Biu thc trn l biu thc ca nh lut Hooke: *Trong gii hn n hi,  ln lc n hi ca l xo t l thun vi  bin dng ca l xo.*",
    "[Hnh 33.3.  th biu din s ph thuc lc n hi vo  dn ca l xo. Trc tung F, trc honh $\\Delta\\ell$. on OA l ng thng i qua gc to  O]",
    "Trong biu thc trn, k l mt hng s vi mt l xo xc nh, c gi l h s n hi hay  cng ca l xo, ph thuc vo kch thc, hnh dng v vt liu ca l xo. Trong h SI, k c n v l N/m.",
    "",
    "129",
    "CHNG VII  BIN DNG CA VT RN, P SUT CHT LNG",
    "",
    "Trong i sng, ngi ta c th ng dng nh lut Hooke  ch to lc k, cn l xo (Hnh 33.4). Trong trng hp , ngi ta  s dng l xo trong gii hn n hi ca n.",
    "[Hnh 33.4. Cn l xo loi to v loi nh]",
    "",
    "**? Cu hi:**",
    "1. Mt l xo c chiu di t nhin 15 cm. L xo c gi c nh ti mt u, cn u kia chu mt lc ko bng 4,5 N. Khi y l xo di 18 cm.  cng ca l xo bng bao nhiu?",
    "2. Mt l xo c  cng l 100 N/m. Nu chu mt lc ko bng 1 N th l xo s b dn ra mt on bng bao nhiu?",
    "3. Mt l xo c chiu di t nhin $l_0$ = 20 cm v  cng k = 20 N/m. C th dng l xo ny  to ra mt lc y bng 1 N c khng? Nu c, chiu di ca l xo khi  bng bao nhiu?",
    "",
    "**EM  HC**",
    "- Bin dng nn: Kch thc vt rn dc theo phng tc dng ca lc nn gim so vi kch thc t nhin.",
    "- Bin dng ko: Kch thc ca vt rn dc theo phng tc dng lc ko tng so vi kch thc t nhin.",
    "- nh lut Hooke: Trong gii hn n hi,  ln lc n hi ca l xo t l thun vi  bin dng ca l xo: $F_{h} = k|\\Delta\\ell|$.",
    "",
    "**EM C TH**",
    "- Gii thch c s lm vic ca lc k, cc loi cn dng l xo.",
    "- Thc hin c th nghim vi cc vt liu thng thng nh dy cao su, l xo bt bi,...  rt ra c nh lut Hooke.",
    "",
    "130",
    "CHNG VII  BIN DNG CA VT RN, P SUT CHT LNG",
    "",
    "Phn  th ngoi on thng OA ng vi lc t vo vt qu gii hn n hi ca l xo. Khi  lc n hi khng cn t l thun vi  bin dng na. Nu treo vt nng c khi lng qu ln, tnh n hi ca l xo s b ph hu.",
    "*Bi tp v d:* Mt l xo b tr theo phng thng ng v c gn vt nng khi lng 200 g. Khi vt treo  di (Hnh 33.4a) th l xo di 17 cm, khi vt t  trn (Hnh 33.4b) th l xo di 13 cm. Ly g = 10 m/s$^2$ v b qua trng lng ca mc treo, gi  vt nng. Tnh  cng ca l xo.",
    "*Gii*",
    "Trong hai trng hp, vt nng chu tc dng ca lc n hi v trng lc. Xt vt nng  v tr cn bng.",
    "Khi vt treo  di l xo: $F_{h1} = P \\Rightarrow k|0,17 - \\ell_0| = m.g$ (1)",
    "Khi t vt  trn l xo: $F_{h2} = P \\Rightarrow k|0,13 - \\ell_0| = m.g$ (2)",
    "T (1) v (2) $\\Rightarrow \\ell_0 = 0,15$ (m). Thay vo (1) hoc (2), tnh c k = 100 (N/m).",
    "",
    "**! Ch :**",
    "Trong cng thc (33.1), nu khi bin dng (dn hoc nn) chiu di l xo bng $\\ell$ v chiu di khi cha bin dng bng $\\ell_0$ th  bin dng l:",
    "$\\Delta\\ell = \\ell - \\ell_0$, ta c th vit li:",
    "$F = k|\\ell - \\ell_0|$",
    "[Hnh 33.4. a) Vt treo di l xo. b) Vt t trn l xo]",
    "*(Lu : sch nh s hnh ny l Hnh 33.4, nhng hnh Cn l xo  trang trc cng l Hnh 33.4)*",
    "",
    "**Hot ng:**",
    "1. T kt qu thu c trong hot ng  mc 1, hy tnh  cng ca l xo  dng lm th nghim. Ti sao khi lng l xo cn rt nh so vi khi lng ca cc vt nng treo vo n?",
    "2. Trn Hnh 33.5 l  th s ph thuc ca  ln lc n hi F vo  bin dng $\\Delta\\ell$ ca 3 l xo khc nhau A, B v C.",
    "a) L xo no c  cng ln nht?",
    "b) L xo no c  cng nh nht?",
    "c) L xo no khng tun theo nh lut Hooke?",
    "[Hnh 33.5.  th F - $\\Delta\\ell$ ca 3 l xo A, B, C. A l ng cong. B v C l on thng i qua gc to , B dc hn C]",
    "",
    "**EM  HC**",
    "- Bin dng n hi. Bin dng ko, bin dng nn.",
    "- c im bin dng v  cng ca l xo.",
    "- Lin h gia lc n hi v  bin dng ca l xo, nh lut Hooke: $F = k|\\Delta\\ell|$.",
    "",
    "**EM C TH**",
    "Gii thch c nguyn tc hot ng ca b phn gim xc trong  t, xe my.",
    "",
    "130"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B34', 'Bài 34. Khối lượng riêng. Áp suất chất lỏng', 132, 2, $JSON$
{
  "content": [
    "# Bi 34 KHI LNG RING. P SUT CHT LNG",
    "",
    "**Khi ng:**",
    "*Khi lng ring ca mt cht lng v p sut ca cht lng c mi quan h nh th no?*",
    "",
    "## I. KHI LNG RING",
    "Khi lng ring ca mt cht l khi lng ca mt n v th tch cht :",
    "$\\text{Khi lng ring} = \\frac{\\text{Khi lng}}{\\text{Th tch}}$",
    "$\\rho = \\frac{m}{V}$ (34.1)",
    "n v ca khi lng ring trong h SI l kg/m$^3$ (kg.m$^{-3}$). Ngi ta cng dng n v khi lng ring l g/cm$^3$ (g.cm$^{-3}$).",
    "$1 \\text{ g/cm}^3 = 1000 \\text{ kg/m}^3$",
    "",
    "**Bng 34.1.** Khi lng ring ca mt s cht  iu kin bnh thng v nhit  v p sut",
    "| Cht rn | $\\rho$ (kg/m$^3$) | Cht lng | $\\rho$ (kg/m$^3$) | Cht kh | $\\rho$ (kg/m$^3$) |",
    "|---|---|---|---|---|---|",
    "| Ch | 11 300 | Thu ngn | 13 500 | Carbonic | 1,98 |",
    "| ng | 8 900 | Nc | 999 | Oxygen | 1,43 |",
    "| Thp | 7 800 | Xng | 700 | Hydrogen | 0,09 |",
    "",
    "**? Cu hi:**",
    "1. Ti sao khi lng ring ca mt cht li ph thuc vo nhit ?",
    "2. Mt hp kim ng v bc c khi lng ring l 10,3 g/cm$^3$. Tnh khi lng ca bc v ng c trong 100 g hp kim. Bit khi lng ring ca ng l 8,9 g/cm$^3$, ca bc l 10,4 g/cm$^3$.",
    "",
    "**Bng 34.2.** Khi lng ring ca nc  cc nhit  khc nhau",
    "| Nhit  | $\\rho$ (kg/m$^3$) |",
    "|---|---|",
    "| $20^\\circ$C | 999 |",
    "| $40^\\circ$C | 992 |",
    "| $60^\\circ$C | 983 |",
    "| $80^\\circ$C | 972 |",
    "",
    "## II. P LC V P SUT",
    "**1. p lc**",
    "**a) Khi nim p lc**",
    "Mt cun sch nm yn trn mt bn nm ngang chu tc dng ca hai lc cn bng l lc ht ca Tri t v lc y ca mt bn (Hnh 34.1a).",
    "Do mt bn tc dng ln cun sch lc $\\vec{F}$ c phng thng ng, chiu hng ln trn v c  ln bng trng lng P ca cun sch, nn theo nh lut 3 Newton: cun sch tc dng ln mt bn lc $\\vec{F}_N$ c phng thng ng, chiu hng xung di v c  ln bng F. Lc $\\vec{F}_N$ p ln mt bn theo phng vung gc vi mt bn, c gi l p lc (Hnh 34.1b).",
    "",
    "[Hnh 34.1.",
    "a) Cun sch chu lc ko P ca Tri t v phn lc F ca bn.",
    "b) Cun sch tc dng p lc $F_N$ ln mt bn]",
    "",
    "$^{(1)}$ K hiu $\\rho$ c l \"r\".",
    "",
    "131",
    "CHNG VII  BIN DNG CA VT RN, P SUT CHT LNG",
    "",
    "**b) p lc ph thuc nhng yu t no?**",
    "**? Cu hi:**",
    "Hy da vo th nghim v  Hnh 34.2, cho bit  ln ca p lc ph thuc vo nhng yu t no v ph thuc nh th no.",
    "[Hnh 34.2. Th nghim v p lc.",
    "(1) Khi ch nht dng ng, ln su vo ct.",
    "(2) Khi ch nht nm ngang, ln t hn (1).",
    "(3) Khi ch nht nm ngang, c thm mt khi khc  ln, ln su hn (2)]",
    "",
    "**? Cu hi:**",
    "1. Trong Hnh 34.3, lc no sau y l lc n hi, lc ma st, p lc?",
    "a) Lc ca chn em b tc dng ln sn nh.",
    "b) Lc ca tay em b ko hp  chi.",
    "c) Lc ca hp  chi tc dng ln sn nh.",
    "[Hnh 34.3. B gi ang ko xe  chi trn sn nh]",
    "",
    "**2. p sut**",
    "Do tc dng ca p lc ln mt b p cng mnh khi cng  ca p lc cng ln v din tch mt b p cng nh, nn  c trng cho tc dng ca p lc ngi ta dng khi nim p sut, c  ln bng p lc chia cho din tch b p.",
    "$\\text{p sut} = \\frac{\\text{p lc}}{\\text{Din tch b p}}$",
    "$p = \\frac{F_N}{S}$ (34.2)",
    "n v ca p sut l N/m$^2$, c tn gi l paxcan (Pa):",
    "$1 \\text{ Pa} = 1 \\text{ N/m}^2$",
    "",
    "**? Cu hi:**",
    "1. Ti sao xe tng nng hn  t nhiu ln li c th chy bnh thng trn t bn (Hnh 34.5a), cn  t b ln bnh v sa ly trn chnh qung ng ny (Hnh 34.5b)?",
    "[Hnh 34.5. a) Xe tng i trn bn. b)  t ln trn bn]",
    "2. Trong hai chic xng v  Hnh 34.6, xng no dng  xn t tt hn, xng no dng  xc t tt hn? Ti sao?",
    "[Hnh 34.6. a) Xng vung mi thng. b) Xng nhn mi cong]",
    "3. Mt ngi nng 50 kg ng trn mt t nm ngang. Bit din tch tip xc ca mi bn chn vi t l 0,015 m$^2$. Tnh p sut ngi  tc dng ln mt t khi:",
    "a) ng c hai chn.",
    "b) ng mt chn.",
    "",
    "**? Cu hi:**",
    "2. Chng minh rng p lc ca cun sch tc dng ln mt bn nm nghing mt gc $\\alpha$ (Hnh 34.4) c  ln l:",
    "$F_N = P.\\cos\\alpha$",
    "[Hnh 34.4. Cun sch trn mt phng nghing gc $\\alpha$]",
    "",
    "**Bng 34.3.**  ln ca mt s p sut",
    "| p sut ti mt s v tr | p (Pa) |",
    "|---|---|",
    "| p sut  tm Tri t | $4.10^{11}$ |",
    "| p sut ca nc  y bin su nht | $1,1.10^8$ |",
    "| p sut ca khng kh trong lp  t | $4.10^5$ |",
    "| p sut kh quyn   cao ca mt nc bin | $1.10^5$ |",
    "",
    "132",
    "CHNG VII  BIN DNG CA VT RN, P SUT CHT LNG",
    "",
    "## III. P SUT CA CHT LNG",
    "**1. S tn ti p sut ca cht lng**",
    "Khi t vt rn ln mt bn th vt rn tc dng ln mt bn p sut theo phng vung gc vi mt bn. Khi nhn chm mt vt vo trong nc th nc c gy p sut ln vt khng? Nu c th p sut ny c ging p sut ca vt rn khng?",
    "Ai ln xung nc cng d cm thy p sut ca nc tc dng ln c th mnh, cng ln su th p sut cng mnh. Tuy nhin, p sut ny c phi ch tc dng theo mt phng nh p sut ca vt rn khng?",
    "",
    "**Hot ng:**",
    "Hy da vo th nghim vi mt bnh cu c cc l nh  thnh bnh trong cc Hnh 34.7a v 34.7b  ni v s tn ti p sut ca cht lng v c im ca p sut ny so vi p sut ca vt rn.",
    "[Hnh 34.7.",
    "a) Bp bp cao su, nc pht ra t cc l nh trn qu cu theo mi hng.",
    "b) Nhng qu cu c mng cao su bc l nh vo nc, cc mng cao su lm vo]",
    "",
    "**2. Cng thc tnh p sut ca cht lng**",
    "C th xc nh c cng thc tnh p sut ca cht lng da trn bi ton sau y:",
    "",
    "**? Cu hi:**",
    "Mt khi cht lng ng yn c khi lng ring $\\rho$, hnh tr din tch y S, chiu cao h (Hnh 34.8). Hy dng cng thc tnh p sut  trn  chng minh rng p sut ca khi cht lng trn tc dng ln y bnh c  ln l $p = \\rho.g.h$.",
    "Trong :",
    "p l p sut ca cht lng tc dng ln y bnh;",
    "$\\rho$ l khi lng ring ca cht lng;",
    "g l gia tc trng trng;",
    "h l chiu cao ca ct cht lng, cng l  su ca cht lng so vi mt thong.",
    "[Hnh 34.8. Mt khi cht lng hnh tr trong bnh]",
